#[derive(Debug)]
enum ScenarioActivationError {
    Recoverable(String),
    Fatal(EngineError),
}

impl fmt::Display for ScenarioActivationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Recoverable(message) => f.write_str(message),
            Self::Fatal(error) => error.fmt(f),
        }
    }
}

impl From<String> for ScenarioActivationError {
    fn from(message: String) -> Self {
        Self::Recoverable(message)
    }
}

struct ScenarioLoadingState {
    scenario: FrontendScenario,
    refreshed_resources: Option<LoaderResources>,
    refreshed_tooltip_font: Option<Arc<lc_graphics::clonk_font::ClonkFont>>,
    refreshed_native_font_source: Option<ClassicNativeFontSource>,
    refreshed_global_gui_overrides: Option<HashMap<&'static str, String>>,
    refresh_requested: bool,
    receiver: Receiver<ScenarioLoadingEvent>,
    finished: bool,
    prepared_go: Option<PreparedGoLoadingState>,
    offline_startup_players: Option<OfflineStartupPlayers>,
}

impl ScenarioLoadingState {
    fn new(
        scenario: FrontendScenario,
        refreshed_resources: LoaderResources,
        refreshed_global_gui_overrides: HashMap<&'static str, String>,
        receiver: Receiver<ScenarioLoadingEvent>,
    ) -> Self {
        Self {
            refreshed_resources: Some(refreshed_resources),
            refreshed_tooltip_font: None,
            refreshed_native_font_source: None,
            refreshed_global_gui_overrides: Some(refreshed_global_gui_overrides),
            refresh_requested: false,
            scenario,
            receiver,
            finished: false,
            prepared_go: None,
            offline_startup_players: None,
        }
    }

    fn from_loaded(
        scenario: FrontendScenario,
        data: Scenario,
        status: lc_network::NetworkStatus,
        restore_player_infos: Vec<lc_engine::ControlPlayerInfoEntry>,
        random_seed: u64,
        use_fair_crew: bool,
        fair_crew_strength: i32,
        fair_crew_forced: bool,
        allow_debug: bool,
        team_configuration: TeamConfiguration,
        team_registry: Vec<lc_engine::TeamInfo>,
    ) -> Self {
        let (sender, receiver) = mpsc::channel();
        let _ = sender.send(ScenarioLoadingEvent::Finished(Ok(data)));
        Self {
            scenario,
            refreshed_resources: None,
            refreshed_tooltip_font: None,
            refreshed_native_font_source: None,
            refreshed_global_gui_overrides: None,
            refresh_requested: false,
            receiver,
            finished: false,
            prepared_go: Some(PreparedGoLoadingState {
                status,
                local_reached: false,
                restore_player_infos,
                random_seed,
                use_fair_crew,
                fair_crew_strength,
                fair_crew_forced,
                allow_debug,
                team_configuration,
                team_registry,
            }),
            offline_startup_players: None,
        }
    }
}

