    fn option_flags(&self) -> OptionFlags {
        OptionFlags {
            sound: self
                .audio
                .as_ref()
                .map(|audio| audio.options.sound_enabled)
                .unwrap_or(false),
            music: self
                .audio
                .as_ref()
                .map(|audio| audio.options.music_enabled)
                .unwrap_or(false),
            mouse_shown: self.mouse_control_allowed,
            mouse: self.mouse_control,
        }
    }

    /// Restart the running round (C4AbortGameDialog's Restart button:
    /// `Application.SetNextMission` + `Game.Abort`, C4GameDialogs.cpp:116-120).
    fn restart_current_scenario(&mut self) -> Result<(), EngineError> {
        let Some(scenario) = self.active_scenario.clone() else {
            self.return_to_menu();
            return Ok(());
        };
        let definition_load = self.active_definition_load.clone();
        self.return_to_menu();
        let start_result = match definition_load {
            Some(definition_load) => {
                self.start_scenario_with_definition_load(scenario, definition_load)
            }
            None => self.start_scenario(scenario),
        };
        if let Err(err) = start_result {
            tracing::error!(error = ?err, "failed to restart scenario");
            self.status_text = format!("Restart failed: {err:#}");
        }
        Ok(())
    }

    fn ensure_ingame_menu_gfx(&mut self) -> &mut IngameMenuGraphics {
        if self.ingame_menu_gfx.is_none() {
            let hud = self.current_hud_graphics();
            let throw_key = self
                .bindings
                .key_for(ControlBindingId::Throw)
                .map(format_key_label)
                .unwrap_or_default();
            let dig_key = self
                .bindings
                .key_for(ControlBindingId::Dig)
                .map(format_key_label)
                .unwrap_or_default();
            let special2_key = self
                .bindings
                .key_for(ControlBindingId::Special2)
                .map(format_key_label)
                .unwrap_or_default();
            self.ingame_menu_gfx = Some(IngameMenuGraphics {
                hud: hud.as_ref().clone(),
                owner_colors: HashMap::new(),
                menu: hud
                    .menu
                    .clone()
                    .or_else(|| self.assets.dialog_image("Menu.png")),
                options: self.current_options_graphic(),
                control: hud
                    .control
                    .clone()
                    .or_else(|| self.assets.dialog_image("Control.png")),
                gui_icons: self.assets.dialog_image("GUIIcons.png"),
                player: hud
                    .player
                    .clone()
                    .or_else(|| self.assets.dialog_image("Player.png")),
                caption_bar: self.assets.dialog_image("GUICaption.png"),
                definition_icons: HashMap::new(),
                font_images: HashMap::new(),
                frame_decoration: None,
                menu_location: None,
                show_commands: self.display_flags.show_commands,
                show_command_keys: self.display_flags.show_command_keys,
                throw_key,
                special2_key,
                dig_key,
            });
        }
        self.ingame_menu_gfx
            .as_mut()
            .expect("ingame menu gfx initialised above")
    }

    fn open_save_browser(&mut self) -> Result<()> {
        let entries = self.collect_save_entries()?;
        let suggested_label = self.generate_default_save_label();
        let state = SaveBrowserState::new(SaveBrowserMode::Save { suggested_label }, entries);
        self.save_browser = Some(state);
        self.save_browser_return_to_menu = true;
        self.ingame_menu.clear();
        self.object_menu = None;
        Ok(())
    }

    fn open_load_browser(&mut self) -> Result<()> {
        let entries = self.collect_save_entries()?;
        if entries.is_empty() {
            self.status_text = "No saved games found".to_string();
        }
        let state = SaveBrowserState::new(SaveBrowserMode::Load, entries);
        self.save_browser = Some(state);
        self.save_browser_return_to_menu = true;
        self.ingame_menu.clear();
        self.object_menu = None;
        Ok(())
    }

    fn dismiss_save_browser(&mut self, reopen_ingame_menu: bool) -> Result<(), EngineError> {
        self.save_browser = None;
        let reopen = reopen_ingame_menu && self.save_browser_return_to_menu;
        self.save_browser_return_to_menu = false;
        if reopen {
            self.open_ingame_menu()?;
        }
        Ok(())
    }

    fn execute_save_browser_action(
        &mut self,
        action: SaveBrowserAction,
    ) -> Result<(), EngineError> {
        match action {
            SaveBrowserAction::Close => {
                self.dismiss_save_browser(true)?;
            }
            SaveBrowserAction::SaveNew { label } => match self.perform_named_save(&label, None) {
                Ok(_) => {
                    self.dismiss_save_browser(true)?;
                }
                Err(err) => {
                    tracing::error!(error = ?err, "failed to save game");
                    self.status_text = format!("Save failed: {err:#}");
                }
            },
            SaveBrowserAction::SaveExisting { entry } => {
                match self.perform_named_save(&entry.display_name, Some(entry.path.clone())) {
                    Ok(_) => {
                        self.dismiss_save_browser(true)?;
                    }
                    Err(err) => {
                        tracing::error!(error = ?err, "failed to overwrite save");
                        self.status_text = format!("Save failed: {err:#}");
                    }
                }
            }
            SaveBrowserAction::Load { entry } => {
                match self.load_saved_game_from_path(&entry.path) {
                    Ok(_) => {
                        self.save_browser = None;
                        self.save_browser_return_to_menu = false;
                        self.close_ingame_menu();
                    }
                    Err(err) => {
                        if let Some(boundary) = err.downcast_ref::<ClassicParityBoundary>() {
                            return Err(classic_parity_engine_error(
                                report_classic_parity_boundary(boundary.clone()),
                            ));
                        }
                        tracing::error!(
                            error = ?err,
                            path = %entry.path.display(),
                            "failed to load saved game"
                        );
                        self.status_text = format!("Load failed: {err:#}");
                    }
                }
            }
        }
        Ok(())
    }

    fn collect_save_entries(&self) -> Result<Vec<SaveEntry>> {
        let dir = resolve_save_directory();
        let mut entries = Vec::new();
        let read_dir = match fs::read_dir(&dir) {
            Ok(iter) => iter,
            Err(_) => return Ok(entries),
        };
        for entry in read_dir {
            let entry = match entry {
                Ok(value) => value,
                Err(err) => {
                    tracing::warn!(error = %err, "failed to iterate save directory entry");
                    continue;
                }
            };
            let path = entry.path();
            if !is_save_file(&path) {
                continue;
            }
            match load_save_entry(&path) {
                Ok(save_entry) => entries.push(save_entry),
                Err(err) => {
                    tracing::warn!(path = %path.display(), error = %err, "failed to read save metadata");
                }
            }
        }
        Ok(entries)
    }

    fn generate_default_save_label(&self) -> String {
        let base = self
            .active_scenario
            .as_ref()
            .map(|scenario| scenario.title.clone())
            .unwrap_or_else(|| self.scenario_label.clone());
        format!("{} {}", base, current_unix_timestamp())
    }

    fn perform_named_save(&mut self, label: &str, target: Option<PathBuf>) -> Result<PathBuf> {
        if self.mode != AppMode::Running {
            anyhow::bail!("cannot save while not running a scenario");
        }

        let scenario = self
            .active_scenario
            .clone()
            .unwrap_or_else(FrontendScenario::fallback);
        let engine_state = self.engine.capture_state();
        let sanitized_label = if label.trim().is_empty() {
            self.generate_default_save_label()
        } else {
            label.trim().to_string()
        };

        let saved = SavedGameFile {
            version: SAVE_FILE_VERSION,
            saved_at_seconds: current_unix_timestamp(),
            scenario: SavedScenarioInfo::from_frontend(
                &scenario,
                &self.scenario_label,
                self.fallback_ground,
            ),
            definition_load: self.active_definition_load.clone(),
            focus_id: self.focus_id,
            user_label: Some(sanitized_label.clone()),
            runtime_music_enabled: Some(self.runtime_music_enabled),
            engine_state,
        };

        let dir = ensure_save_directory()?;
        let path = match target {
            Some(path) => path,
            None => {
                let base = sanitize_save_label(&sanitized_label);
                unique_save_path(&dir, &base)
            }
        };

        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).with_context(|| {
                format!("failed to create save directory at {}", parent.display())
            })?;
        }

        let mut file = File::create(&path)
            .with_context(|| format!("failed to create save file at {}", path.display()))?;
        serde_json::to_writer_pretty(&mut file, &saved).context("failed to serialise save data")?;
        file.flush().context("failed to flush save data")?;

        self.write_save_thumbnail(&path)?;
        self.last_save_path = Some(path.clone());
        self.status_text = format!("Saved {}", saved.scenario.title);
        Ok(path)
    }

    fn write_save_thumbnail(&mut self, path: &Path) -> Result<()> {
        let surface = self.graphics.surface();
        let encoded =
            encode_surface_to_png(surface).context("failed to encode save thumbnail image")?;
        let target = path.with_extension("png");
        let mut file = File::create(&target)
            .with_context(|| format!("failed to create thumbnail at {}", target.display()))?;
        file.write_all(&encoded)
            .context("failed to write save thumbnail")?;
        file.flush()
            .context("failed to flush save thumbnail to disk")?;
        Ok(())
    }

    fn save_next_screenshot(
        &mut self,
        presented_frame: &[u8],
        physical_width: u32,
        physical_height: u32,
        scale: f32,
    ) -> Result<Option<PathBuf>> {
        let Some(request) = self.pending_screenshots.pop_front() else {
            return Ok(None);
        };

        let path = match request.kind {
            ScreenshotKind::PresentedFrame => write_numbered_screenshot(
                self.app_paths.as_ref(),
                physical_width,
                physical_height,
                presented_frame,
            )?,
            ScreenshotKind::FullLandscape => {
                let surface = self
                    .graphics
                    .render_full_landscape_with_gamma(&self.snapshot, &request.gamma)
                    .context("full-landscape screenshot requires an active viewport")?;
                let width = scaled_screenshot_extent(surface.width(), scale)?;
                let height = scaled_screenshot_extent(surface.height(), scale)?;
                let frame_len = (width as usize)
                    .checked_mul(height as usize)
                    .and_then(|pixels| pixels.checked_mul(4))
                    .context("full-landscape screenshot dimensions overflow")?;
                let mut frame = vec![0_u8; frame_len];
                lc_scaling::upscale_frame(
                    surface.pixels(),
                    surface.width(),
                    surface.height(),
                    &mut frame,
                    width,
                    height,
                );
                write_numbered_screenshot(self.app_paths.as_ref(), width, height, &frame)?
            }
        };

        // Both Rust paths already contain the gamma used for presentation:
        // F9 copies the physical frame and the full-map world pass encodes
        // fragments with the request-time installed ramp. Applying it again
        // would double it.
        Ok(Some(path))
    }

    fn load_saved_game_from_path(&mut self, path: &Path) -> Result<()> {
        let contents = fs::read_to_string(path)
            .with_context(|| format!("failed to read save from {}", path.display()))?;
        let save: SavedGameFile = serde_json::from_str(&contents)
            .with_context(|| format!("failed to parse save data from {}", path.display()))?;
        let save = migrate_save_file(save)?;
        self.apply_loaded_game(save)?;
        self.last_save_path = Some(path.to_path_buf());
        Ok(())
    }

    fn issue_unjoined_joins_for_client(&mut self, client_id: i32) {
        let resources = &self.admission_resources;
        let joins = self
            .control_player_infos
            .issue_unjoined_players(client_id, |core| {
                resources.complete_path(core.id).and_then(|path| {
                    lc_engine::LegacyCString::from_bytes(path.to_string_lossy().as_bytes().to_vec())
                })
            });
        let tick = self.local_control_submission_tick();
        for join in joins {
            if let Some(Err(error)) = self
                .network
                .as_ref()
                .map(|network| network.submit_join_player(tick, join))
            {
                tracing::error!(%error, "failed to submit synchronized JoinPlayer");
            }
        }
    }

    fn prepare_network_savegame_recreation(&mut self) {
        let restore_player_infos = self
            .loading_state
            .as_ref()
            .and_then(|loading| loading.prepared_go.as_ref())
            .map(|prepared| prepared.restore_player_infos.clone())
            .unwrap_or_default();
        if !restore_player_infos
            .iter()
            .any(|restore| restore.flags & lc_engine::PLAYER_INFO_FLAG_REMOVED == 0)
        {
            self.deferred_network_savegame_recreation.clear();
            return;
        }
        self.deferred_network_savegame_recreation = route_network_savegame_recreation(
            &mut self.control_player_infos,
            &restore_player_infos,
        );
        seed_engine_player_info_parameters(
            &mut self.engine,
            &self.network_league_name,
            &self.control_player_infos,
        );

        let memberships = ordered_control_player_team_memberships(&self.control_player_infos);
        let exact_teams = self.network_team_assignment.as_mut().map(|assignment| {
            self.control_player_infos
                .recheck_team_players(assignment.teams_mut());
            let metadata = assignment.teams().clone();
            (
                runtime_teams_from_initial_metadata(&metadata),
                lc_network::join_team_list_snapshot(metadata),
            )
        });
        let runtime_teams = if let Some((runtime_teams, snapshot)) = exact_teams {
            if let Some(host_snapshot) = self.host_join_snapshot.as_mut() {
                host_snapshot.parameters.teams = snapshot;
            }
            runtime_teams
        } else {
            let mut runtime_teams = self.engine.teams().to_vec();
            recheck_runtime_team_memberships_from_infos(&mut runtime_teams, &memberships);
            if let Some(host_snapshot) = self.host_join_snapshot.as_mut() {
                recheck_join_team_memberships_from_infos(
                    &mut host_snapshot.parameters.teams.teams,
                    &memberships,
                );
            }
            runtime_teams
        };
        self.engine.set_teams(runtime_teams.clone());
        if let Some(prepared) = self
            .loading_state
            .as_mut()
            .and_then(|loading| loading.prepared_go.as_mut())
        {
            prepared.team_registry = runtime_teams;
        }
        self.publish_current_host_player_infos();
        if !self.deferred_network_savegame_recreation.is_empty() {
            tracing::debug!(
                players = ?self.deferred_network_savegame_recreation,
                "routed joined savegame infos to deferred recreation"
            );
        }
    }

    fn issue_reserved_joins_for_player_snapshot(
        &mut self,
        client_id: i32,
        players: &[lc_engine::ControlPlayerInfoEntry],
    ) {
        let resources = &self.admission_resources;
        let joins = self.control_player_infos.issue_reserved_player_snapshots(
            client_id,
            players,
            |core| {
                resources.complete_path(core.id).and_then(|path| {
                    lc_engine::LegacyCString::from_bytes(path.to_string_lossy().as_bytes().to_vec())
                })
            },
        );
        let tick = self.local_control_submission_tick();
        for join in joins {
            if let Some(Err(error)) = self
                .network
                .as_ref()
                .map(|network| network.submit_join_player(tick, join))
            {
                tracing::error!(%error, "failed to submit synchronized JoinPlayer");
            }
        }
    }

    fn handle_script_player_info_updates(&mut self) -> Result<(), EngineError> {
        // SetMaxPlayer writes Game.Parameters.MaxPlayers inside the engine's
        // synchronized script call. Mirror that value before either the
        // queued CreateScriptPlayer admission or the empty fast path.
        let mut host_snapshot_changed = false;
        if let Some(max_players) = self.engine.max_players() {
            self.network_max_players = usize::try_from(max_players).unwrap_or(0);
            if let Some(snapshot) = self.host_join_snapshot.as_mut() {
                if snapshot.parameters.max_players != max_players {
                    snapshot.parameters.max_players = max_players;
                    host_snapshot_changed = true;
                }
            }
        }
        let progress_updates = self.engine.take_player_info_league_progress_updates();
        let mut player_infos_changed = self.refresh_current_player_info_teams();
        for (player_info_id, data) in progress_updates {
            player_infos_changed |= self
                .control_player_infos
                .set_league_progress_data(player_info_id, data);
        }
        if player_infos_changed {
            host_snapshot_changed |= self.refresh_current_host_player_infos();
        }
        if host_snapshot_changed {
            self.publish_updated_host_join_snapshot();
        }
        let updates = self.engine.take_script_player_info_updates();
        if updates.is_empty() {
            return Ok(());
        }
        match self.runtime_network_role() {
            RuntimeNetworkRole::Host => {
                let Some(network) = self.network.as_ref() else {
                    return Ok(());
                };
                for update in updates {
                    if let Err(error) = network.submit_player_info_update(update) {
                        tracing::error!(%error, "failed to submit script-player PlayerInfo");
                    }
                }
            }
            RuntimeNetworkRole::Offline => {
                for update in updates {
                    let Some(info) = self
                        .control_player_infos
                        .admit_request(update, self.network_max_players)
                    else {
                        continue;
                    };
                    let client_id = info.client_id;
                    self.control_player_infos.apply(info);
                    self.recheck_team_memberships_from_player_infos();
                    seed_engine_player_info_parameters(
                        &mut self.engine,
                        &self.network_league_name,
                        &self.control_player_infos,
                    );
                    let joins = self
                        .control_player_infos
                        .issue_unjoined_local_players(client_id, |_| {
                            Some(lc_engine::LegacyCString::default())
                        });
                    for join in joins {
                        self.apply_join_player_control(join)?;
                    }
                }
                // Offline admission applies JoinPlayer immediately, after the
                // regular tick snapshot was captured. Keep rendering and
                // recording on the post-control engine state.
                self.snapshot = self.engine.snapshot();
            }
            RuntimeNetworkRole::Client | RuntimeNetworkRole::Ambiguous => {
                tracing::debug!(
                    count = updates.len(),
                    "discarding non-host script-player requests"
                );
            }
        }
        Ok(())
    }

    fn prepare_client_network_scenario_if_ready(&mut self) {
        if let Err(error) = self.try_prepare_client_network_scenario() {
            tracing::error!(%error, "failed to prepare client network scenario");
            self.status_text = format!("Unable to prepare network scenario: {error}");
        }
    }

    fn acknowledge_initial_lobby_status_if_ready(&mut self) {
        if !self.initial_lobby_status_ack_pending
            || self.network_lobby.is_none()
            || self.startup_view != StartupView::NetworkLobby
        {
            return;
        }
        let Some(current_control_tick) = self
            .network_control_clock
            .map(NetworkControlClock::current_tick)
        else {
            tracing::error!("cannot acknowledge initial lobby status without a control clock");
            return;
        };
        let current_frame = i32::try_from(self.engine.frame()).unwrap_or(i32::MAX);
        match self
            .network
            .as_mut()
            .map(|network| {
                network.acknowledge_requested_status_at_frame(
                    current_control_tick,
                    current_frame,
                )
            })
        {
            Some(Ok(())) => self.initial_lobby_status_ack_pending = false,
            Some(Err(error)) => {
                tracing::error!(%error, "failed to acknowledge initial lobby status");
            }
            None => {}
        }
    }

    fn try_prepare_client_network_scenario(&mut self) -> Result<(), String> {
        let Some(status) = self.pending_client_start_status else {
            return Ok(());
        };
        let Some(join_data) = self.pending_network_join_data.clone() else {
            return Ok(());
        };
        let Some(NetworkMode::Client(settings)) = self.network_mode.as_ref() else {
            return Ok(());
        };
        let resource_directory = settings.resource_directory.clone();
        let maker = settings.player_name.clone();
        if self.client_combined_scenario_path.is_none() {
            let resources = match resolve_client_scenario_resources(&join_data, |core| {
                self.admission_resources
                    .complete_path(core.id)
                    .map(Path::to_path_buf)
            }) {
                Ok(resources) => resources,
                Err(_) => return Ok(()),
            };
            let filename = format!("Combined{}.c4s", join_data.client_id);
            let packed = compose_client_network_scenario(&resources, &filename, &maker)
                .map_err(|error| error.to_string())?;
            fs::create_dir_all(&resource_directory).map_err(|error| {
                format!("failed to create {}: {error}", resource_directory.display())
            })?;
            let combined_path = resource_directory.join(filename);
            fs::write(&combined_path, packed)
                .map_err(|error| format!("failed to write {}: {error}", combined_path.display()))?;
            self.network
                .as_ref()
                .ok_or_else(|| "client network disappeared during scenario merge".to_string())?
                .remove_client_resource(join_data.dynamic.id)
                .map_err(|error| {
                    format!(
                        "failed to retire merged dynamic resource {}: {error}",
                        join_data.dynamic.id
                    )
                })?;
            self.client_combined_scenario_path = Some(combined_path);
        }
        if self.loading_state.is_some() {
            return Ok(());
        }
        let game_resources = match resolve_client_game_resources(&join_data, |core| {
            self.admission_resources
                .complete_path(core.id)
                .map(Path::to_path_buf)
        }) {
            Ok(resources) => resources,
            Err(_) => return Ok(()),
        };
        let combined_path = self
            .client_combined_scenario_path
            .clone()
            .expect("combined path was installed above");
        let mut definition_groups = Vec::new();
        let mut material_groups = Vec::new();
        for resource in &game_resources {
            let target = match resource.core.resource_type {
                value if value == lc_network::HostResourceType::Definitions as u8 => {
                    &mut definition_groups
                }
                value if value == lc_network::HostResourceType::Material as u8 => {
                    &mut material_groups
                }
                _ => continue,
            };
            target.push(Group::open(&resource.path).map_err(|error| {
                format!(
                    "failed to open synchronized game resource {} at {}: {error}",
                    resource.core.id,
                    resource.path.display()
                )
            })?);
        }
        let resolver_paths = cached_app_paths().ok();
        let scenario_group = Group::open(&combined_path).map_err(|error| {
            format!(
                "failed to open combined scenario {} for graphics lookup: {error}",
                combined_path.display()
            )
        })?;
        let graphics_groups = InstallDefinitionResolver::new(resolver_paths.clone())
            .resolve_graphics_groups_with_definition_roots(&scenario_group, &definition_groups)
            .map_err(|error| format!("failed to resolve client graphics resources: {error}"))?;
        let languages = startup_language_sequence(resolver_paths.as_deref());
        let language_packs = resolver_paths
            .as_deref()
            .map(classic_language_packs)
            .unwrap_or_default();
        let random_seed = u64::from(join_data.parameters.random_seed as u32);
        self.fade_out_game_music();
        let scenario_data = Scenario::load_network_from_path_with_languages_and_seed_and_packs(
            &combined_path,
            &definition_groups,
            &material_groups,
            &graphics_groups,
            &languages,
            random_seed,
            &language_packs,
        )
        .map_err(|error| error.to_string())?;
        validate_client_network_scenario(&scenario_data)?;
        self.client_material_resource_groups = Some(material_groups);
        let title = legacy_presentation_text(join_data.parameters.title.as_bytes());
        let scenario = FrontendScenario {
            identifier: combined_path
                .file_name()
                .map(|name| name.to_string_lossy().into_owned())
                .unwrap_or_else(|| format!("Combined{}.c4s", join_data.client_id)),
            title: if title.is_empty() {
                "Network game".to_string()
            } else {
                title
            },
            description: None,
            kind: ScenarioKind::Scenario,
            is_editable: false,
            is_playable: true,
            path: Some(combined_path.clone()),
            source_paths: vec![combined_path],
            root_label: None,
            preview: None,
            title_picture: None,
            children: Vec::new(),
            folder_index: None,
            icon_index: None,
            difficulty: None,
            author: None,
            version: None,
            local_only: None,
            allow_user_change: None,
            definition_modules: Vec::new(),
        };
        let team_registry = runtime_teams_from_join_snapshot(&join_data.parameters.teams);
        self.loading_state = Some(ScenarioLoadingState::from_loaded(
            scenario,
            scenario_data,
            status,
            player_info_list_entries(&join_data.parameters.restore_player_infos).collect(),
            random_seed,
            join_data.parameters.use_fair_crew,
            join_data.parameters.fair_crew_strength,
            join_data.parameters.fair_crew_forced,
            join_data.parameters.allow_debug,
            synchronized_team_configuration(&join_data.parameters),
            team_registry,
        ));
        self.pending_network_join_data = None;
        self.mode = AppMode::Loading;
        Ok(())
    }

    fn handle_status_committed(
        &mut self,
        status: lc_network::NetworkStatus,
    ) -> Result<(), EngineError> {
        let runtime_commit = self.runtime_network_status_barrier;
        if runtime_commit.is_some_and(|pending| {
            !pending.local_reached
                || !same_runtime_network_status_barrier(pending.status, status)
        }) {
            tracing::warn!(
                state = status.state,
                target_tick = status.target_tick,
                "ignoring runtime network commit before local arrival"
            );
            return Ok(());
        }
        let client_commit = if runtime_commit.is_some() {
            true
        } else if matches!(self.network_mode, Some(NetworkMode::Client(_))) {
            self.client_start_barrier.status_committed(status).is_some()
        } else {
            true
        };
        if !client_commit {
            tracing::warn!(
                state = status.state,
                target_tick = status.target_tick,
                "ignoring network commit before the client reached its matching barrier"
            );
            return Ok(());
        }
        self.network_control_running = false;
        let prepared_go = self
            .loading_state
            .as_ref()
            .and_then(|loading| loading.prepared_go.as_ref())
            .map(|pending| (pending.status, pending.local_reached));
        if let Some((expected, local_reached)) = prepared_go {
            let matching_barrier = if matches!(self.network_mode, Some(NetworkMode::Client(_))) {
                expected.state == status.state && expected.target_tick == status.target_tick
            } else {
                expected == status
            };
            if !matching_barrier || !local_reached {
                tracing::warn!(
                    expected_state = expected.state,
                    expected_control_mode = expected.control_mode,
                    expected_target_tick = expected.target_tick,
                    state = status.state,
                    control_mode = status.control_mode,
                    target_tick = status.target_tick,
                    "ignoring commit before the prepared game reached its exact Go barrier"
                );
                return Ok(());
            }
        }
        let Ok(target_tick) = Tick::try_from(status.target_tick) else {
            tracing::warn!(
                target_tick = status.target_tick,
                "ignoring negative committed status tick"
            );
            return Ok(());
        };
        if let Some(clock) = self.network_control_clock.as_mut() {
            clock.set_target_tick(None);
        }
        if status.state == lc_network::NETWORK_STATE_GO {
            let runtime_join_allowed = self.network_mode.as_ref().and_then(|mode| match mode {
                NetworkMode::Host(HostSettings {
                    prepared: Some(prepared),
                    ..
                }) => Some(prepared.admission().runtime_join_allowed()),
                NetworkMode::Host(_) | NetworkMode::Client(_) => None,
            });
            if let Some(Err(error)) = runtime_join_allowed.and_then(|allowed| {
                self.network
                    .as_ref()
                    .map(|network| network.set_join_allowed(allowed))
            }) {
                self.status_text = format!("Unable to apply runtime join policy: {error}");
                return Ok(());
            }
        }
        // Clear the completed barrier before synchronized controls execute.
        // A VoteEnd control may synchronously open the follow-up Go barrier;
        // that newer transition must own the final running/reference state.
        if runtime_commit.is_some() {
            self.runtime_network_status_barrier = None;
        }
        let sync_tick = runtime_commit
            .and_then(|pending| pending.actual_control_tick)
            .and_then(|tick| Tick::try_from(tick).ok())
            .unwrap_or(target_tick);
        let sync_controls = self.network_sync.take_exact(sync_tick);
        if !sync_controls.is_empty() {
            self.apply_ready_controls(sync_tick, sync_controls)?;
        }
        if runtime_commit.is_some()
            && (self.mode != AppMode::Running
                || self.network.is_none()
                || self.runtime_network_status_barrier.is_some())
        {
            return Ok(());
        }
        if status.state == lc_network::NETWORK_STATE_GO {
            self.host_reference_paused = false;
            if matches!(self.network_mode.as_ref(), Some(NetworkMode::Host(_))) {
                for client_id in self.control_clients.activated_client_ids() {
                    self.issue_unjoined_joins_for_client(client_id);
                }
            }
            if prepared_go.is_some() {
                self.finalize_network_loaded_scenario()?;
                self.loading_state = None;
                self.pending_client_start_status = None;
                self.mode = AppMode::Running;
            }
            self.network_control_running = true;
            self.publish_running_host_reference();
        } else if status.state == lc_network::NETWORK_STATE_PAUSE {
            self.host_reference_paused = true;
            self.publish_running_host_reference();
        }
        Ok(())
    }

    fn freeze_configured_client_players_for_game(&mut self) -> Result<()> {
        self.configured_client_player_selection = self
            .app_paths
            .as_ref()
            .map(snapshot_configured_client_player_selection)
            .transpose()?;
        Ok(())
    }

    fn submit_initial_client_player_info(&mut self, client_id: i32) -> bool {
        let Some(network) = self.network.as_ref() else {
            return false;
        };
        let mut completed_resources = Vec::new();
        let empty_request = || lc_network::PlayerInfoUpdateRequest {
            client_id,
            flags: lc_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
            players: Vec::new(),
        };
        let request = self
            .app_paths
            .as_ref()
            .zip(self.configured_client_player_selection.as_ref())
            .map(|(paths, selection)| {
                let configured = load_snapshotted_client_players(paths, selection);
                publish_initial_configured_client_players(client_id, &configured, |publication| {
                    let source_path = publication.source_path.clone();
                    network
                        .publish_client_player_resource(lc_network::ClientPlayerResourceRequest {
                            source_path: publication.source_path,
                            wire_name: publication.wire_name,
                            group_maker: publication.group_maker,
                        })
                        .inspect(|core| {
                            completed_resources.push((core.clone(), source_path.clone()));
                        })
                        .inspect_err(|error| {
                            tracing::warn!(
                                path = %source_path.display(),
                                %error,
                                "failed to publish configured network player"
                            );
                        })
                })
            })
            .unwrap_or_else(empty_request);
        for (core, path) in completed_resources {
            self.admission_resources.ensure_by_core(&core);
            self.admission_resources.mark_complete(core.id, path);
        }
        match network.submit_player_info_update(request) {
            Ok(()) => true,
            Err(error) => {
                tracing::error!(%error, "failed to submit initial PlayerInfo");
                false
            }
        }
    }

    fn apply_direct_player_info_control(
        &mut self,
        info: lc_engine::PlayerInfoControlData,
        issue_joins: bool,
    ) -> Vec<lc_engine::PlayerInfoControlData> {
        let client_id = info.client_id;
        let local_origin = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
            == Some(info.by_client);
        let had_client_packet = self
            .control_player_infos
            .client_packet(client_id)
            .is_some();
        let send_clean_follow_up = matches!(self.network_mode.as_ref(), Some(NetworkMode::Host(_)))
            && info.by_client == 0
            && info.flags & lc_engine::CLIENT_PLAYER_INFO_FLAG_UPDATED != 0
            && (info.flags & lc_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS == 0
                || !had_client_packet);
        self.admission_resources
            .register_player_info_resources(&info.players);
        self.control_player_infos.apply(info);
        let rebalance_updates = self.recheck_team_memberships_from_player_infos();
        let follow_ups = if local_origin {
            let mut updated_clients = rebalance_updates
                .iter()
                .map(|update| update.client_id)
                .collect::<HashSet<_>>();
            if send_clean_follow_up {
                updated_clients.insert(client_id);
            }
            self.control_player_infos
                .client_packets(&updated_clients)
        } else {
            Vec::new()
        };
        seed_engine_player_info_parameters(
            &mut self.engine,
            &self.network_league_name,
            &self.control_player_infos,
        );
        self.publish_current_host_player_infos();
        let should_issue_joins = issue_joins
            && self.mode == AppMode::Running
            && matches!(self.network_mode.as_ref(), Some(NetworkMode::Host(_)))
            && self.control_clients.contains(client_id)
            && self.control_clients.is_activated(client_id);
        if should_issue_joins {
            self.issue_unjoined_joins_for_client(client_id);
        }
        follow_ups
    }

    fn broadcast_and_preexecute_player_info(
        &mut self,
        info: lc_engine::PlayerInfoControlData,
        issue_joins_now: bool,
        capture_join_players_on_echo: bool,
    ) -> Result<()> {
        let mut controls =
            VecDeque::from([(info, issue_joins_now, capture_join_players_on_echo)]);
        while let Some((info, issue_joins_now, capture_join_players_on_echo)) =
            controls.pop_front()
        {
            let capture_join_players = capture_join_players_on_echo
                && self.mode == AppMode::Running
                && matches!(self.network_mode.as_ref(), Some(NetworkMode::Host(_)))
                && self.control_clients.contains(info.client_id)
                && self.control_clients.is_activated(info.client_id);
            let join_players_on_echo = if capture_join_players {
                let mut post_control = self.control_player_infos.clone();
                post_control.apply(info.clone());
                post_control
                    .client_packet(info.client_id)
                    .map(|packet| packet.players)
                    .unwrap_or_default()
                    .into_iter()
                    .filter(|player| {
                        player.flags & lc_engine::PLAYER_INFO_FLAG_JOINED == 0
                            && player.savegame_player == 0
                    })
                    .collect()
            } else {
                Vec::new()
            };
            self.network
                .as_ref()
                .ok_or_else(|| anyhow!("network session is unavailable"))?
                .broadcast_preexecuted_player_info(info.clone(), join_players_on_echo.clone())?;
            let follow_ups = self.apply_direct_player_info_control(info, issue_joins_now);
            if capture_join_players {
                self.control_player_infos
                    .reserve_unjoined_player_snapshots(&join_players_on_echo);
            }
            for follow_up in follow_ups.into_iter().rev() {
                // HandlePlayerInfo's nested DirectExec precedes the next outer
                // admission control and inherits its join-issuance boundary.
                controls.push_front((
                    follow_up,
                    issue_joins_now,
                    capture_join_players_on_echo,
                ));
            }
        }
        Ok(())
    }

    fn apply_preexecuted_player_info_echo(
        &mut self,
        original: lc_engine::PlayerInfoControlData,
        info: lc_engine::PlayerInfoControlData,
        mut join_players_on_echo: Vec<lc_engine::ControlPlayerInfoEntry>,
    ) {
        let client_id = info.client_id;
        self.admission_resources
            .register_player_info_resources(&info.players);
        for player in &mut join_players_on_echo {
            let Some(normalized) = info.players.iter().find(|normalized| normalized.id == player.id)
            else {
                continue;
            };
            player.flags = (player.flags & !lc_engine::PLAYER_INFO_FLAG_HAS_RESOURCE)
                | (normalized.flags & lc_engine::PLAYER_INFO_FLAG_HAS_RESOURCE);
            player.resource.clone_from(&normalized.resource);
        }
        if self
            .control_player_infos
            .apply_player_resource_normalization(&original, &info)
        {
            seed_engine_player_info_parameters(
                &mut self.engine,
                &self.network_league_name,
                &self.control_player_infos,
            );
            self.publish_current_host_player_infos();
        }
        if !join_players_on_echo.is_empty() {
            self.issue_reserved_joins_for_player_snapshot(client_id, &join_players_on_echo);
        }
    }

    fn commit_host_player_info_admission(
        &mut self,
        admission: lc_engine::PlayerInfoAdmission,
    ) -> Result<()> {
        let lc_engine::PlayerInfoAdmission {
            updated_existing,
            admitted,
            joined_player_team_updates,
        } = admission;
        for update in &joined_player_team_updates {
            self.engine.apply_admitted_player_team_update(
                update.info_id,
                update.team,
                update.color,
            )?;
        }
        for info in updated_existing {
            self.broadcast_and_preexecute_player_info(info, true, false)?;
        }
        self.broadcast_and_preexecute_player_info(admitted, false, true)
    }

    fn submit_runtime_network_player(&mut self, file: &str) -> Result<(), String> {
        let host = match self.network_mode.as_ref() {
            Some(NetworkMode::Host(_)) => true,
            Some(NetworkMode::Client(_)) => false,
            None => return Err("runtime joining requires a network session".to_string()),
        };
        let network = self
            .network
            .as_ref()
            .ok_or_else(|| "network session is unavailable".to_string())?;
        let client_id = i32::try_from(network.local_client_id())
            .map_err(|_| "local client ID exceeds the PlayerInfo wire field".to_string())?;
        if !self.control_clients.is_activated(client_id) {
            return Err("network client is not active".to_string());
        }

        let source_path = PathBuf::from(file);
        let player_file = PlayerFile::load_from_path(&source_path)
            .map_err(|error| format!("failed to load {}: {error}", source_path.display()))?;
        let wire_name = lc_engine::LegacyCString::from_bytes(file.as_bytes().to_vec())
            .ok_or_else(|| "player filename contains an interior NUL".to_string())?;
        let group_maker =
            lc_engine::LegacyCString::from_bytes(self.player_name.as_bytes().to_vec())
                .ok_or_else(|| "network player name contains an interior NUL".to_string())?;
        let selected =
            SelectedClientPlayer::new(source_path.clone(), wire_name.clone(), player_file);

        // LoadFromLocalFile publishes/reuses NRT_Player before JoinLocalPlayer
        // handles its CIF_AddPlayers request. Hosts process that request
        // directly; clients send it to the host (src/C4PlayerInfo.cpp:70-104;
        // src/C4Network2Players.cpp:78-137).
        let publication = lc_network::ClientPlayerResourceRequest {
            source_path: source_path.clone(),
            wire_name,
            group_maker,
        };
        let resource = if host {
            network.publish_host_player_resource(publication)
        } else {
            network.publish_client_player_resource(publication)
        }
        .map_err(|error| error.to_string())?;
        let request = selected
            .runtime_add_player_info_update(client_id, resource)
            .map_err(|error| error.to_string())?;
        // A locally published resource keeps its original file for this
        // process's JoinPlayer while the backend serves the optimized
        // standalone to peers
        // (src/C4Network2Res.cpp:409-424,1168-1189;
        // src/C4Network2Players.cpp:353-382).
        let resource_core = request
            .players
            .first()
            .and_then(|player| player.resource.as_ref())
            .cloned()
            .ok_or_else(|| "runtime player request has no resource".to_string())?;
        self.admission_resources
            .register_lobby_resource(&resource_core);
        self.admission_resources
            .mark_complete(resource_core.id, source_path);
        if !host {
            return network
                .submit_player_info_update(request)
                .map_err(|error| error.to_string());
        }

        let restore_players = host_restore_player_info_entries(self.host_join_snapshot.as_ref());
        let generated_team_name_template = self.generated_team_name_template.clone();
        let has_or_will_have_lobby = self.has_or_will_have_network_lobby();
        let admission = match self.network_team_assignment.as_mut() {
            Some(team_assignment) => team_assignment.admit_request(
                &mut self.control_player_infos,
                request,
                self.network_max_players,
                true,
                has_or_will_have_lobby,
                &restore_players,
            ),
            None => {
                let mut oracle = ProcessInitialHostTeamAssignmentOracle::new(
                    generated_team_name_template,
                );
                self.control_player_infos.admit_request_with_attributes(
                    request,
                    self.network_max_players,
                    None,
                    &restore_players,
                    &mut oracle,
                )
                .map_err(NetworkTeamControlError::from)
            }
        }
        .map_err(|error| format!("host rejected the runtime player attributes: {error}"))?
        .ok_or_else(|| "host rejected the runtime player request".to_string())?;
        self.commit_host_player_info_admission(admission)
            .map_err(|error| error.to_string())
    }

    fn control_message_has_lobby(&self) -> bool {
        self.classic_host_lobby.is_some()
            || (self.startup_view == StartupView::NetworkLobby && self.network_lobby.is_some())
    }

    fn control_message_lobby_chat_color(&self, client_id: i32) -> u32 {
        if self.control_clients.is_activated(client_id) {
            let hide_assigned_team_color = self.control_message_has_lobby()
                && self.engine.team_distribution() == 4
                && self.engine.team_colors();
            let teams = self.engine.teams();
            self.control_player_infos
                .first_user_lobby_color(client_id, hide_assigned_team_color, |team_id| {
                    teams.iter().any(|team| team.id == team_id)
                })
                .unwrap_or(0x00ff_ffff)
        } else {
            0x00ff_ffff
        }
    }

    fn append_control_message_log(
        &mut self,
        line: String,
        color: u32,
        lobby_sender: Option<i32>,
    ) {
        tracing::info!(message = %line, "network message");
        let line = self.timestamp_log_line(line);
        let color = lobby_sender
            .map(|client_id| {
                if self.control_message_has_lobby() && !self.control_clients.contains(client_id) {
                    self.network
                        .as_ref()
                        .and_then(|network| i32::try_from(network.local_client_id()).ok())
                        .unwrap_or(0)
                } else {
                    client_id
                }
            })
            .map(|client_id| self.control_message_lobby_chat_color(client_id))
            .unwrap_or(color);
        let rgba = [
            ((color >> 16) & 0xff) as u8,
            ((color >> 8) & 0xff) as u8,
            (color & 0xff) as u8,
            0xff,
        ];
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby.controller.push_log(LobbyLogLine {
                text: line,
                color: rgba,
            });
            return;
        }
        if self.startup_view == StartupView::NetworkLobby {
            if let Some(lobby) = self.network_lobby.as_mut() {
                lobby.push_log(LobbyLogLine {
                    text: line,
                    color: rgba,
                });
                return;
            }
        }
        self.enqueue_control_message_board_line(line);
    }

    fn timestamp_log_line(&self, line: String) -> String {
        if self.show_log_timestamps {
            format!("{} {line}", lc_core::chrono_util::current_timestamp(true))
        } else {
            line
        }
    }

    /// The native `/mute` and `/unmute` commands are process-local policy,
    /// not controls. Command names are case-sensitive in ProcessCommand and
    /// client names are matched exactly.
    fn process_control_message_local_command(&mut self, text: &str) -> bool {
        let raw = lc_script::c4_string_bytes(text);
        let Some(command) = raw.strip_prefix(b"/") else {
            return false;
        };
        let (name, parameter) = command
            .iter()
            .position(|byte| *byte == b' ')
            .map_or((command, &[][..]), |space| {
                (&command[..space], &command[space + 1..])
            });
        let muted = match name {
            b"mute" => true,
            b"unmute" => false,
            _ => return false,
        };
        if let Some(client_id) = self
            .control_clients
            .snapshot()
            .into_iter()
            .find(|client| client.name.as_bytes() == parameter)
            .map(|client| client.client_id)
        {
            self.control_messages.set_muted(client_id, muted);
        }
        true
    }

    fn start_running_chat(&mut self, mode: RunningChatMode) {
        let text = match mode {
            RunningChatMode::All => String::new(),
            RunningChatMode::Allies => "/team ".to_string(),
            RunningChatMode::Say => "\"".to_string(),
        };
        self.running_chat = Some(RunningChatState {
            edit: LobbyChatEditView {
                caret: text.len(),
                text,
                cursor_visible: true,
                ..LobbyChatEditView::default()
            },
            history_index: -1,
        });
    }

    fn browse_running_chat_history(&mut self, older: bool) {
        let Some(chat) = self.running_chat.as_mut() else {
            return;
        };
        chat.history_index += if older { 1 } else { -1 };
        let text = usize::try_from(chat.history_index)
            .ok()
            .and_then(|index| self.message_input_history.get(index))
            .cloned();
        match text {
            Some(text) => {
                chat.edit = LobbyChatEditView {
                    caret: text.len(),
                    selection: (!text.is_empty()).then_some((0, text.len())),
                    text,
                    cursor_visible: true,
                    ..LobbyChatEditView::default()
                };
            }
            None => {
                chat.history_index = -1;
                chat.edit = LobbyChatEditView::default();
            }
        }
    }

    fn store_message_input_history(&mut self, text: &str) {
        if text.is_empty() {
            return;
        }
        if let Some(position) = self
            .message_input_history
            .iter()
            .position(|previous| previous == text)
        {
            self.message_input_history.remove(position);
        }
        self.message_input_history.push_front(text.to_string());
        self.message_input_history.truncate(20);
    }

    fn complete_running_chat_nick(&mut self) {
        let Some(chat) = self.running_chat.as_mut() else {
            return;
        };
        let before_cursor = &chat.edit.text[..chat.edit.caret];
        let start = before_cursor
            .char_indices()
            .rev()
            .find(|(_, character)| {
                character.is_ascii()
                    && !character.is_ascii_alphanumeric()
                    && *character != '_'
            })
            .map_or(0, |(index, character)| index + character.len_utf8());
        let incomplete = lc_script::c4_string_bytes(&before_cursor[start..]);
        if incomplete.is_empty() {
            return;
        }
        let suffix = self.snapshot.players.iter().find_map(|player| {
            let name = lc_script::c4_string_bytes(&player.name);
            name.get(..incomplete.len())
                .filter(|prefix| prefix.eq_ignore_ascii_case(&incomplete))
                .map(|_| lc_script::c4_string_from_bytes(&name[incomplete.len()..]))
        });
        if let Some(suffix) = suffix {
            lobby_chat_insert_text(&mut chat.edit, &suffix);
        }
    }

    fn submit_running_chat(&mut self) {
        let Some(chat) = self.running_chat.take() else {
            return;
        };
        let text = chat.edit.text;
        self.store_message_input_history(&text);
        if self.process_control_message_local_command(&text) {
            return;
        }
        let player = self
            .snapshot
            .hud
            .local_players
            .first()
            .copied()
            .unwrap_or(-1);
        let control = match parse_running_message_control(
            &text,
            player,
            self.engine.cinematic_film(),
            &self.snapshot,
        ) {
            Ok(control) => control,
            Err(error) => {
                tracing::warn!(%error, "classic game chat command is not implemented");
                self.append_control_message_log(
                    "Unknown command.".to_string(),
                    CONTROL_LOG_COLOR,
                    None,
                );
                return;
            }
        };
        let Some(mut control) = control else {
            return;
        };
        if let Some(network) = self.network.as_ref() {
            if let Err(error) = network.submit_message(control) {
                tracing::error!(%error, "failed to submit classic game message");
            }
        } else {
            control.by_client = 0;
            self.execute_message_control(control);
        }
    }

    fn handle_running_chat_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> bool {
        if !matches!(self.mode, AppMode::Running) {
            return false;
        }
        if self.running_chat.is_none() {
            let modifiers = self.keyboard_modifiers
                & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
            let mode = match (key, modifiers) {
                (VirtualKeyCode::Return | VirtualKeyCode::F2, modifiers)
                    if modifiers.is_empty() =>
                {
                    Some(RunningChatMode::All)
                }
                (VirtualKeyCode::Return, ModifiersState::SHIFT) => {
                    Some(RunningChatMode::Allies)
                }
                (VirtualKeyCode::Return, ModifiersState::ALT) => Some(RunningChatMode::Say),
                _ => None,
            };
            if let Some(mode) = mode {
                if state == ElementState::Pressed {
                    self.start_running_chat(mode);
                }
                return true;
            }
            return false;
        }
        if state == ElementState::Released {
            return true;
        }
        match key {
            VirtualKeyCode::Escape | VirtualKeyCode::F2 => self.running_chat = None,
            VirtualKeyCode::Return | VirtualKeyCode::NumpadEnter => self.submit_running_chat(),
            VirtualKeyCode::Tab => self.complete_running_chat_nick(),
            VirtualKeyCode::Up => self.browse_running_chat_history(true),
            VirtualKeyCode::Down => self.browse_running_chat_history(false),
            VirtualKeyCode::Back => {
                let empty = self
                    .running_chat
                    .as_ref()
                    .is_none_or(|chat| chat.edit.text.is_empty());
                if empty {
                    self.running_chat = None;
                } else if let Some(chat) = self.running_chat.as_mut() {
                    lobby_chat_apply_edit_key(
                        &mut chat.edit,
                        LobbyChatEditKey::Backspace,
                        LobbyChatKeyModifiers {
                            shift: self.keyboard_modifiers.shift(),
                            control: self.keyboard_modifiers.ctrl(),
                        },
                    );
                }
            }
            key => {
                let operation = match key {
                    VirtualKeyCode::Delete => Some(LobbyChatEditKey::Delete),
                    VirtualKeyCode::Left => Some(LobbyChatEditKey::Left),
                    VirtualKeyCode::Right => Some(LobbyChatEditKey::Right),
                    VirtualKeyCode::Home => Some(LobbyChatEditKey::Home),
                    VirtualKeyCode::End => Some(LobbyChatEditKey::End),
                    _ => None,
                };
                if let (Some(operation), Some(chat)) = (operation, self.running_chat.as_mut()) {
                    lobby_chat_apply_edit_key(
                        &mut chat.edit,
                        operation,
                        LobbyChatKeyModifiers {
                            shift: self.keyboard_modifiers.shift(),
                            control: self.keyboard_modifiers.ctrl(),
                        },
                    );
                }
            }
        }
        true
    }

    fn note_control_message_sound(&mut self, client_id: i32, muted: bool) {
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby.controller.note_client_sound(client_id, muted);
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.note_client_sound(client_id, muted);
        }
    }

    fn request_control_message_attention(&mut self) -> bool {
        if self.window_active {
            return false;
        }
        self.control_messages.request_user_attention();
        true
    }

    fn control_message_mentions_local_nick(&self, control: &MessageControlData) -> bool {
        let local_client = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
            .unwrap_or(0);
        if local_client == control.by_client {
            return false;
        }
        self.control_clients
            .state(local_client)
            .is_some_and(|client| mentions_nick(control.message.as_bytes(), client.nick.as_bytes()))
    }

    fn play_control_message_sound(&mut self, name: &str) -> bool {
        let fallback_center = {
            let surface = self.graphics.surface();
            Vector2::new((surface.width() as i32) / 2, (surface.height() as i32) / 2)
        };
        let viewport_center = self
            .focus_snapshot
            .as_ref()
            .map(|object| object.position)
            .unwrap_or(fallback_center);
        let Some(audio) = self.audio.as_mut() else {
            return false;
        };
        for candidate in [name.to_string(), format!("{name}.ogg"), format!("{name}.mp3")] {
            match audio.try_start_sound(
                &candidate,
                None,
                100,
                false,
                true,
                None,
                &self.snapshot,
                self.focus_snapshot.as_ref(),
                viewport_center,
            ) {
                Ok(true) => return true,
                Ok(false) => {}
                Err(error) => {
                    tracing::warn!(sound = %candidate, %error, "failed to play control message sound");
                }
            }
        }
        false
    }

    fn execute_message_control(&mut self, control: MessageControlData) -> MessageControlOutcome {
        self.execute_message_control_with_sound_at(control, Instant::now(), |app, name| {
            app.play_control_message_sound(name)
        })
    }

    fn execute_message_control_with_sound_at<F>(
        &mut self,
        control: MessageControlData,
        now: Instant,
        mut play_sound: F,
    ) -> MessageControlOutcome
    where
        F: FnMut(&mut Self, &str) -> bool,
    {
        let mut outcome = MessageControlOutcome::default();
        let sender = (control.player >= 0)
            .then(|| self.engine.player(control.player))
            .flatten()
            .map(|player| {
                let color = player.color().map_or(0, |color| {
                    (u32::from(color.r) << 16) | (u32::from(color.g) << 8) | u32::from(color.b)
                });
                (
                    player.id(),
                    player.at_client().get(),
                    c4_presentation_text(player.name()),
                    color,
                )
            });
        if sender
            .as_ref()
            .is_some_and(|(_, at_client, _, _)| *at_client != control.by_client)
        {
            outcome.rejected = true;
            return outcome;
        }

        let message = legacy_presentation_text(control.message.as_bytes());
        let mut check_alert = false;
        match control.message_type {
            MESSAGE_TYPE_NORMAL | MESSAGE_TYPE_ME => {
                let (line, color) = match sender.as_ref() {
                    Some((_, _, name, color)) => {
                        let line = match (control.message_type, self.display_flags.white_chat) {
                            (MESSAGE_TYPE_NORMAL, true) => {
                                format!("<c {color:x}><{name}></c> {message}")
                            }
                            (MESSAGE_TYPE_NORMAL, false) => {
                                format!("<c {color:x}><{name}> {message}")
                            }
                            (MESSAGE_TYPE_ME, true) => {
                                format!("<c {color:x}> * {name}</c> {message}")
                            }
                            (MESSAGE_TYPE_ME, false) => {
                                format!("<c {color:x}> * {name} {message}")
                            }
                            _ => unreachable!(),
                        };
                        (line, *color)
                    }
                    None => {
                        let nick = self
                            .control_clients
                            .state(control.by_client)
                            .map(|client| legacy_presentation_text(client.nick.as_bytes()))
                            .unwrap_or_else(|| "???".to_string());
                        let white = self.control_message_has_lobby() && self.white_lobby_chat;
                        let line = match (control.message_type, white) {
                            (MESSAGE_TYPE_NORMAL, true) => {
                                format!("<{nick}> <c ffffff>{message}")
                            }
                            (MESSAGE_TYPE_NORMAL, false) => format!("<{nick}> {message}"),
                            (MESSAGE_TYPE_ME, true) => {
                                format!(" * {nick} <c ffffff>{message}")
                            }
                            (MESSAGE_TYPE_ME, false) => format!(" * {nick} {message}"),
                            _ => unreachable!(),
                        };
                        (line, 0x00ff_ffff)
                    }
                };
                self.append_control_message_log(line, color, Some(control.by_client));
                outcome.displayed = true;
                check_alert = true;
            }
            MESSAGE_TYPE_SAY => {
                outcome.say_displayed = self.engine.execute_message_control_say(&control);
            }
            MESSAGE_TYPE_TEAM => {
                if let Some((sender_id, _, name, color)) = sender.as_ref() {
                    let local_players = self.engine.snapshot().hud.local_players;
                    let visible = local_players.iter().any(|local_id| {
                        self.engine.player(*local_id).is_some_and(|local| {
                            !local.is_hostile_towards(*sender_id)
                                && self
                                    .engine
                                    .player(*sender_id)
                                    .is_some_and(|sender| !sender.is_hostile_towards(*local_id))
                        })
                    });
                    if visible {
                        let line = if self.display_flags.white_chat {
                            format!("<c {color:x}>{{{name}}}</c> {message}")
                        } else {
                            format!("<c {color:x}>{{{name}}} {message}")
                        };
                        self.append_control_message_log(line, CONTROL_LOG_COLOR, None);
                        outcome.displayed = true;
                    }
                    check_alert = true;
                } else if self.control_message_has_lobby() {
                    let local_client = self
                        .network
                        .as_ref()
                        .and_then(|network| i32::try_from(network.local_client_id()).ok())
                        .unwrap_or(0);
                    if !self
                        .control_player_infos
                        .has_same_team_players(control.by_client, local_client)
                    {
                        return outcome;
                    }
                    let nick = self
                        .control_clients
                        .state(control.by_client)
                        .map(|client| legacy_presentation_text(client.nick.as_bytes()))
                        .unwrap_or_else(|| "???".to_string());
                    let line = if self.white_lobby_chat {
                        format!("{{{nick}}} <c ffffff>{message}")
                    } else {
                        format!("{{{nick}}} {message}")
                    };
                    self.append_control_message_log(
                        line,
                        0x00ff_ffff,
                        Some(control.by_client),
                    );
                    outcome.displayed = true;
                    check_alert = true;
                } else {
                    check_alert = true;
                }
            }
            MESSAGE_TYPE_PRIVATE => {
                let Some((_, _, name, color)) = sender.as_ref() else {
                    return outcome;
                };
                let visible = self
                    .engine
                    .snapshot()
                    .hud
                    .local_players
                    .contains(&control.to_player);
                if visible {
                    let line = if self.display_flags.white_chat {
                        format!("<c {color:x}>[{name}]</c> {message}")
                    } else {
                        format!("<c {color:x}>[{name}] {message}")
                    };
                    self.append_control_message_log(line, CONTROL_LOG_COLOR, None);
                    outcome.displayed = true;
                }
                check_alert = true;
            }
            MESSAGE_TYPE_SOUND => {
                if self.control_clients.state(control.by_client).is_none()
                    || !self.control_messages.try_allow_sound_at(now)
                {
                    return outcome;
                }
                let muted = self.control_messages.is_muted(control.by_client);
                if !muted {
                    outcome.sound_attempted = true;
                    outcome.sound_played = play_sound(self, &message);
                }
                if muted || outcome.sound_played {
                    if self.control_message_has_lobby() {
                        self.note_control_message_sound(control.by_client, muted);
                        outcome.lobby_sound = true;
                    }
                }
            }
            MESSAGE_TYPE_ALERT => {
                outcome.attention_requested = self.request_control_message_attention();
            }
            MESSAGE_TYPE_SYSTEM => {
                if control.by_client == 0 {
                    self.append_control_message_log(
                        format!("Network: {message}"),
                        CONTROL_LOG_COLOR,
                        None,
                    );
                    outcome.displayed = true;
                }
            }
            _ => {}
        }

        if check_alert && self.control_message_mentions_local_nick(&control) {
            outcome.attention_requested = self.request_control_message_attention();
        }
        outcome
    }

    fn process_network_events(&mut self) -> Result<(), EngineError> {
        let events = self
            .network
            .as_mut()
            .map(NetworkManager::poll_events)
            .unwrap_or_default();
        if !events.is_empty() {
            self.mark_menu_dirty();
        }
        {
            for event in events {
                // C4GameControlNetwork::HandleControlPkt executes synchronized
                // controls immediately while network control is frozen in the
                // lobby (src/C4GameControlNetwork.cpp:558-588).
                let frozen_lobby = self.network_lobby.is_some() || self.classic_host_lobby_active();
                if frozen_lobby && matches!(&event, NetworkEvent::ScheduledSync { .. }) {
                    let NetworkEvent::ScheduledSync { tick, controls } = event else {
                        unreachable!("ScheduledSync was matched above");
                    };
                    self.apply_ready_controls(tick, controls)?;
                    continue;
                }
                if self.classic_host_lobby_active() {
                    if let NetworkEvent::LeagueUpdate(response) = &event {
                        self.apply_league_update_response(response.clone());
                        continue;
                    }
                    if let NetworkEvent::NetpuncherStateChanged {
                        game_ids,
                        local_addresses,
                    } = &event
                    {
                        self.update_host_netpuncher_reference(
                            *game_ids,
                            local_addresses.clone(),
                        );
                        continue;
                    }
                    let player_info_event = matches!(
                        &event,
                        NetworkEvent::PlayerInfoUpdateRequest { .. }
                            | NetworkEvent::PreexecutedPlayerInfoEcho { .. }
                            | NetworkEvent::DirectControl(NetworkControl::PlayerInfo(_))
                    );
                    if let NetworkEvent::DirectControl(NetworkControl::Message(control)) = &event {
                        self.execute_message_control(control.clone());
                        continue;
                    }
                    let boundary = match &event {
                        NetworkEvent::HostPingMeasured { .. } => None,
                        NetworkEvent::HostStatusChanged(_) => None,
                        NetworkEvent::PeerConnected { client_id: 0, .. } => None,
                        NetworkEvent::JoinData(_) => Some("join data"),
                        NetworkEvent::LeagueRoundResults(_) => Some("league round results"),
                        NetworkEvent::LeagueUpdate(_) => Some("league update"),
                        NetworkEvent::ReadyCheck(_) => Some("ready check"),
                        NetworkEvent::StatusRequested(_) => Some("status request"),
                        NetworkEvent::StatusCommitted(_) => Some("status commit"),
                        NetworkEvent::LobbyCountdown(_) => Some("lobby countdown"),
                        NetworkEvent::ActivationRequest { .. } => Some("activation request"),
                        NetworkEvent::PlayerInfoUpdateRequest { .. } => None,
                        NetworkEvent::PreexecutedPlayerInfoEcho { .. } => None,
                        NetworkEvent::ReadyTick { .. } => Some("ready control tick"),
                        NetworkEvent::ScheduledSync { .. } => Some("scheduled control"),
                        NetworkEvent::DirectControl(NetworkControl::PlayerInfo(_)) => None,
                        NetworkEvent::DirectControl(_) => Some("direct player/resource control"),
                        NetworkEvent::PeerConnected { .. } => Some("remote client row"),
                        NetworkEvent::PeerDisconnected { .. } => Some("client removal"),
                        NetworkEvent::PeerConnectionFailed { .. } => {
                            Some("client connection failure")
                        }
                        NetworkEvent::NetpuncherStateChanged { .. } => unreachable!(
                            "netpuncher state is applied before the classic-lobby boundary"
                        ),
                        NetworkEvent::ResourceAction(_) => Some("resource action"),
                        NetworkEvent::ResourceComplete { .. } => Some("resource completion"),
                        NetworkEvent::ResourceLoadFailed { .. } => Some("resource load failure"),
                        NetworkEvent::ResourceDeriveUnsupported { .. } => {
                            Some("resource derivation")
                        }
                        NetworkEvent::Error(_) => Some("network error presentation"),
                    };
                    if let Some(boundary) = boundary {
                        return Err(classic_game_lobby_child_error(
                            ClassicGameLobbyChild::NetworkEvent(boundary),
                        ));
                    }
                    if !player_info_event {
                        continue;
                    }
                }
                match event {
                    NetworkEvent::HostPingMeasured { round_trip_ms } => {
                        if let Some(clock) = self.network_control_clock.as_mut() {
                            clock.observe_round_trip_ms(round_trip_ms);
                        }
                    }
                    NetworkEvent::HostStatusChanged(status) => {
                        if let Some(clock) = self.network_control_clock.as_mut() {
                            clock.set_target_tick(Some(status.target_tick));
                        }
                        if self.mode == AppMode::Running {
                            self.arm_runtime_network_status_barrier(status);
                        }
                    }
                    NetworkEvent::JoinData(join_data) => {
                        // Game.Parameters is the authoritative client/player
                        // snapshot. Scenario and dynamic resource application
                        // remains deferred until the game leaves the lobby
                        // (src/C4Network2.cpp:1574-1620,619-671).
                        self.admission_resources
                            .register_join_data_resources(&join_data);
                        self.network_max_players =
                            usize::try_from(join_data.parameters.max_players).unwrap_or(0);
                        self.engine
                            .set_max_players(join_data.parameters.max_players);
                        self.engine
                            .set_use_fair_crew(join_data.parameters.use_fair_crew);
                        self.engine
                            .set_fair_crew_strength(join_data.parameters.fair_crew_strength);
                        self.engine
                            .set_fair_crew_forced(join_data.parameters.fair_crew_forced);
                        self.engine
                            .set_allow_debug(join_data.parameters.allow_debug);
                        self.network_is_league =
                            synchronized_parameters_are_league(&join_data.parameters);
                        self.network_league_name = synchronized_league_name(&join_data.parameters);
                        self.network_control_clock = Some(NetworkControlClock::new(
                            join_data.start_control_tick,
                            join_data.parameters.control_rate,
                        ));
                        self.control_clients
                            .replace_snapshot(join_data.parameters.clients.clients.iter().cloned());
                        self.network_client_activity.replace_clients(
                            join_data
                                .parameters
                                .clients
                                .clients
                                .iter()
                                .map(|client| client.client_id),
                        );
                        self.control_player_infos.replace_snapshot(
                            join_data.parameters.player_infos.last_player_id,
                            join_data
                                .parameters
                                .player_infos
                                .clients
                                .iter()
                                .cloned()
                                .map(|client| lc_engine::PlayerInfoControlData {
                                    client_id: client.client_id,
                                    flags: client.flags,
                                    players: client.players,
                                    by_client: 0,
                                }),
                        );
                        seed_engine_player_info_parameters(
                            &mut self.engine,
                            &self.network_league_name,
                            &self.control_player_infos,
                        );
                        let scenario_title =
                            legacy_presentation_text(join_data.parameters.title.as_bytes());
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            lobby.replace_participants_from_clients(
                                &join_data.parameters.clients.clients,
                            );
                            lobby.set_scenario_title(&scenario_title);
                        }
                        if !scenario_title.is_empty() {
                            self.scenario_label = scenario_title;
                        }
                        let is_client =
                            matches!(self.network_mode.as_ref(), Some(NetworkMode::Client(_)));
                        let local_is_observer =
                            self.control_clients.is_observer(join_data.client_id);
                        let initial_player_info_ready = if is_client && !local_is_observer {
                            self.submit_initial_client_player_info(join_data.client_id)
                        } else {
                            is_client && local_is_observer
                        };
                        self.initial_lobby_status_ack_pending = initial_player_info_ready
                            && join_data.status.state == lc_network::NETWORK_STATE_LOBBY;
                        self.client_start_barrier =
                            ClientStartBarrier::from_join_data_status(join_data.status);
                        self.pending_client_start_status = None;
                        self.client_combined_scenario_path = None;
                        self.client_material_resource_groups = None;
                        self.pending_network_join_data = Some(join_data);
                        self.acknowledge_initial_lobby_status_if_ready();
                    }
                    NetworkEvent::LeagueRoundResults(packet) => {
                        self.apply_league_round_results_packet(&packet);
                    }
                    NetworkEvent::LeagueUpdate(response) => {
                        self.apply_league_update_response(response);
                    }
                    NetworkEvent::ReadyCheck(packet) => {
                        if packet.data.vote_requested() {
                            if self.control_clients.clear_nonhost_lobby_ready() {
                                self.publish_updated_host_join_snapshot();
                            }
                            self.handle_lobby_ready_check_request(packet)?;
                        } else {
                            let ready_state_changed = self
                                .control_clients
                                .set_lobby_ready(packet.client_id, packet.data.is_ready());
                            let changed_client_id = self
                                .network_lobby
                                .as_mut()
                                .and_then(|lobby| lobby.apply_ready_check(packet));
                            if ready_state_changed {
                                self.publish_updated_host_join_snapshot();
                            }
                            if let Some(changed_client_id) = changed_client_id {
                                self.on_lobby_client_ready_state_change(changed_client_id)?;
                            }
                        }
                    }
                    NetworkEvent::LobbyCountdown(packet) => {
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            lobby.apply_lobby_countdown(packet);
                        }
                    }
                    NetworkEvent::StatusRequested(status) => {
                        if let Some(clock) = self.network_control_clock.as_mut() {
                            clock.set_target_tick(Some(status.target_tick));
                        }
                        if self.mode == AppMode::Running {
                            // CheckStatusReached keeps control running until
                            // the requested target is reached at an empty
                            // cadence boundary. Receipt alone never pauses.
                            self.arm_runtime_network_status_barrier(status);
                        } else {
                            // Before InitGameFinal, local scenario preparation
                            // is the reach condition and control stays stopped.
                            self.network_control_running = false;
                            if matches!(self.network_mode, Some(NetworkMode::Client(_))) {
                                if let Some(requested) =
                                    self.client_start_barrier.status_requested(status)
                                {
                                    self.pending_client_start_status = Some(requested);
                                }
                                self.prepare_client_network_scenario_if_ready();
                            }
                        }
                        tracing::debug!(
                            state = status.state,
                            control_mode = status.control_mode,
                            target_tick = status.target_tick,
                            "network status is waiting for local preparation"
                        );
                    }
                    NetworkEvent::StatusCommitted(status) => {
                        self.handle_status_committed(status)?;
                    }
                    NetworkEvent::ActivationRequest {
                        client_id,
                        tick,
                        waited_for,
                        ping_ms,
                    } => {
                        let client_id = i32::try_from(client_id).unwrap_or(i32::MAX);
                        let host_frame = i32::try_from(self.engine.frame()).unwrap_or(i32::MAX);
                        let running =
                            matches!(self.mode, AppMode::Running) && self.network_control_running;
                        if let Some(update) = self.control_clients.activation_update_for_request(
                            client_id,
                            tick,
                            host_frame,
                            running,
                            waited_for,
                            ping_ms,
                            self.frames_per_second,
                        ) {
                            if let Some(Err(error)) = self
                                .network
                                .as_ref()
                                .map(|network| network.submit_client_update(update))
                            {
                                tracing::error!(%error, "failed to submit client activation");
                            }
                        }
                    }
                    NetworkEvent::PlayerInfoUpdateRequest {
                        origin,
                        request,
                        by_host,
                    } => {
                        tracing::debug!(%origin, by_host, "processing PlayerInfo update request");
                        let restore_players =
                            host_restore_player_info_entries(self.host_join_snapshot.as_ref());
                        let generated_team_name_template =
                            self.generated_team_name_template.clone();
                        let has_or_will_have_lobby = self.has_or_will_have_network_lobby();
                        let admission = match self.network_team_assignment.as_mut() {
                            Some(team_assignment) => team_assignment.admit_request(
                                &mut self.control_player_infos,
                                request,
                                self.network_max_players,
                                by_host,
                                has_or_will_have_lobby,
                                &restore_players,
                            ),
                            None => {
                                let mut oracle = ProcessInitialHostTeamAssignmentOracle::new(
                                    generated_team_name_template,
                                );
                                self.control_player_infos
                                    .admit_request_with_attributes(
                                        request,
                                        self.network_max_players,
                                        None,
                                        &restore_players,
                                        &mut oracle,
                                    )
                                    .map_err(NetworkTeamControlError::from)
                            }
                        };
                        match admission {
                            Ok(Some(admission)) => {
                                if let Err(error) =
                                    self.commit_host_player_info_admission(admission)
                                {
                                    tracing::error!(%error, "failed to broadcast authoritative PlayerInfo");
                                }
                            }
                            Ok(None) => {}
                            Err(error) => {
                                tracing::warn!(
                                    %origin,
                                    %error,
                                    "rejected PlayerInfo update with unavailable attribute-conflict state"
                                );
                            }
                        }
                    }
                    NetworkEvent::PreexecutedPlayerInfoEcho {
                        original,
                        info,
                        join_players_on_echo,
                    } => {
                        self.apply_preexecuted_player_info_echo(
                            original,
                            info,
                            join_players_on_echo,
                        );
                    }
                    NetworkEvent::ReadyTick { tick, controls } => {
                        if self.mode == AppMode::Running {
                            let expected_tick = self.expected_network_control_tick();
                            self.network_ticks.queue(expected_tick, tick, controls);
                        }
                    }
                    NetworkEvent::ScheduledSync { tick, controls } => {
                        let expected_tick = self.expected_network_control_tick();
                        self.network_sync.queue(expected_tick, tick, controls);
                    }
                    NetworkEvent::DirectControl(control) => match control {
                        NetworkControl::ClientJoin(join) => {
                            if self.control_clients.apply_join(&join) {
                                self.network_client_activity
                                    .reset_client(join.core.client_id);
                                self.publish_updated_host_join_snapshot();
                            }
                        }
                        NetworkControl::SyncCheck(packet) => {
                            self.handle_sync_check(packet);
                        }
                        NetworkControl::PlayerInfo(info) => {
                            let follow_ups = self.apply_direct_player_info_control(info, true);
                            for follow_up in follow_ups {
                                if let Err(error) = self.broadcast_and_preexecute_player_info(
                                    follow_up,
                                    true,
                                    false,
                                )
                                {
                                    tracing::error!(%error, "failed to broadcast updated PlayerInfo follow-up");
                                }
                            }
                        }
                        NetworkControl::Vote(vote) => self.execute_league_vote(vote)?,
                        NetworkControl::Set(set) => self.execute_control_set(set),
                        NetworkControl::Message(message) => {
                            self.execute_message_control(message);
                        }
                        control => {
                            tracing::warn!(?control, "ignoring unsupported direct control");
                        }
                    },
                    NetworkEvent::PeerConnected {
                        client_id,
                        name,
                        kind,
                    } => {
                        tracing::info!(%client_id, %name, ?kind, "network client connected");
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            lobby.register_peer(client_id, name.clone(), kind);
                        }
                        self.status_text = format!("{name} joined the lobby");
                    }
                    NetworkEvent::PeerDisconnected { client_id, reason } => {
                        let abort_countdown_for_disconnected_client = matches!(
                            self.network_mode,
                            Some(NetworkMode::Host(_))
                        ) && self.network_lobby.as_ref().is_some_and(|lobby| {
                            lobby.countdown.is_some_and(|remaining| {
                                remaining <= ALMOST_START_LOBBY_COUNTDOWN_SECONDS
                            })
                        })
                            && i32::try_from(client_id).ok().is_some_and(|client_id| {
                                !self.control_player_infos.client_info_ids(client_id).is_empty()
                            });
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            lobby.unregister_peer(client_id);
                        }
                        if abort_countdown_for_disconnected_client {
                            self.abort_network_lobby_countdown();
                        }
                        let local_client_id = (client_id == 0
                            && matches!(self.network_mode.as_ref(), Some(NetworkMode::Client(_))))
                        .then(|| {
                            self.network
                                .as_ref()
                                .and_then(|network| i32::try_from(network.local_client_id()).ok())
                        })
                        .flatten();
                        if let Some(local_client_id) = local_client_id {
                            // A lost host cannot receive a graceful ConnRe;
                            // C4Network2 clears directly into ChangeToLocal
                            // (C4Network2.cpp:1786-1817).
                            self.report_league_disconnect(
                                local_client_id,
                                lc_network::LeagueDisconnectReason::ConnectionFailed,
                            );
                            self.change_network_control_to_local(local_client_id);
                        }
                        match reason {
                            Some(reason) => {
                                tracing::info!(
                                    %client_id,
                                    reason = %reason,
                                    "network client disconnected"
                                );
                                self.status_text = format!("Client {client_id} left: {reason}");
                            }
                            None => {
                                tracing::info!(%client_id, "network client disconnected");
                                self.status_text = format!("Client {client_id} left the lobby");
                            }
                        }
                    }
                    NetworkEvent::PeerConnectionFailed { client_id } => {
                        if let Ok(client_id) = i32::try_from(client_id) {
                            self.report_league_disconnect(
                                client_id,
                                lc_network::LeagueDisconnectReason::ConnectionFailed,
                            );
                        }
                    }
                    NetworkEvent::NetpuncherStateChanged {
                        game_ids,
                        local_addresses,
                    } => {
                        self.update_host_netpuncher_reference(game_ids, local_addresses);
                    }
                    NetworkEvent::ResourceAction(action) => {
                        // Socket/protocol state is already retained by
                        // lc-network. Filesystem-backed serving and chunk
                        // persistence are completed by the resource backend
                        // rather than silently treating loadable cores as
                        // available.
                        tracing::debug!(?action, "network resource backend action pending");
                    }
                    NetworkEvent::ResourceComplete {
                        resource_id,
                        core,
                        path,
                    } => {
                        self.admission_resources.register_lobby_resource(&core);
                        self.admission_resources
                            .mark_complete(resource_id, path.clone());
                        tracing::info!(
                            resource_id,
                            resource = %core.filename.to_string_lossy(),
                            path = %path.display(),
                            "network resource received"
                        );
                        self.prepare_client_network_scenario_if_ready();
                    }
                    NetworkEvent::ResourceLoadFailed { resource_id } => {
                        self.admission_resources.mark_failed(resource_id);
                        tracing::warn!(resource_id, "network resource load failed");
                    }
                    NetworkEvent::ResourceDeriveUnsupported { core } => {
                        tracing::warn!(
                            resource_id = core.id,
                            parent_resource_id = core.derived_id,
                            "network resource derivation is not implemented"
                        );
                    }
                    NetworkEvent::Error(message) => {
                        tracing::error!(message = %message, "network error");
                    }
                }
            }
        }
        Ok(())
    }

    fn apply_league_round_results_packet(
        &mut self,
        packet: &lc_network::LeagueRoundResultsPacket,
    ) {
        self.engine.evaluate_league_round_results(
            packet.success,
            packet.result_string.as_bytes().to_vec(),
            packet.players.iter().map(|result| lc_engine::LeagueRoundResultUpdate {
                player_info_id: result.player_info_id,
                league_score_new: result.league_score_new,
                league_score_gain: result.league_score_gain,
                league_rank_new: result.league_rank_new,
                league_rank_symbol_new: result.league_rank_symbol_new,
                league_progress_data: result.league_progress_data.as_bytes().to_vec(),
            }),
        );
        self.snapshot.round_results = self.engine.snapshot().round_results;
        tracing::info!(
            success = packet.success,
            player_count = packet.players.len(),
            result = %packet.result_string.to_string_lossy(),
            "applied league round results"
        );
    }

    fn apply_league_update_response(&mut self, response: lc_network::LeagueUpdateResponse) {
        let updates = self.control_player_infos.apply_league_projected_gains(
            response
                .player_infos
                .players
                .iter()
                .map(|player| (player.id, player.league_projected_gain)),
        );
        if updates.is_empty() {
            return;
        }
        if let Some(network) = self.network.as_ref() {
            for update in updates {
                if let Err(error) = network.broadcast_player_info(update) {
                    tracing::error!(%error, "failed to broadcast league projected gains");
                }
            }
        }
        self.publish_current_host_player_infos();
    }

    fn report_league_disconnect(
        &self,
        client_id: i32,
        reason: lc_network::LeagueDisconnectReason,
    ) {
        if !self.network_is_league
            || self.mode != AppMode::Running
            || self.snapshot.game_over
        {
            return;
        }
        let (_, clients) = self.control_player_infos.retained_rows_snapshot();
        let Some((_, flags, players)) = clients
            .into_iter()
            .find(|(id, _, players)| *id == client_id && players.iter().any(|p| p.is_joined()))
        else {
            return;
        };
        let Some(network) = self.network.as_ref() else {
            return;
        };
        if let Err(error) = network.report_league_disconnect(
            reason,
            lc_network::ClientPlayerInfosSnapshot {
                client_id,
                flags,
                players,
            },
            lc_network::LeagueFbidRegistry::new(),
        ) {
            tracing::error!(%error, client_id, "failed to queue league disconnect report");
        }
    }

    fn handle_sync_check(&mut self, packet: SyncCheckPacket) {
        if matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return;
        }
        if let Some((local, remote)) = self.sync_checks.record_remote(packet) {
            self.evaluate_sync_checks(local, remote);
        }
    }

    fn evaluate_sync_checks(&mut self, local: SyncCheckPacket, remote: SyncCheckPacket) {
        if local.matches(&remote) {
            return;
        }
        self.handle_desync(local, remote);
    }

    fn handle_desync(&mut self, local: SyncCheckPacket, remote: SyncCheckPacket) {
        tracing::error!(
            frame = local.frame,
            local = ?local,
            host = ?remote,
            "network desync detected"
        );
        self.sync_checks.clear();
        if matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            self.status_text = "Network desync detected".to_string();
            return;
        }
        if let Some(local_client_id) = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
        {
            // C4ControlSyncCheck::Execute clears C4Network2 on a live network
            // mismatch; C4Network2::Clear then invokes ChangeToLocal rather
            // than sending a graceful removal or aborting the round
            // (C4Control.cpp:469-519; C4Network2.cpp:746-789).
            self.report_league_disconnect(
                local_client_id,
                lc_network::LeagueDisconnectReason::Desync,
            );
            self.change_network_control_to_local(local_client_id);
        }
        self.status_text = "Network desync detected; disconnected from host".to_string();
    }

    fn process_gamepad_events(&mut self) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        let events = self.gamepads.poll();
        let gamepad_gui_control = self.gamepad_gui_control;
        self.process_sourced_gamepad_event_batch(events, gamepad_gui_control)
    }

    #[cfg(test)]
    fn process_gamepad_event_batch(
        &mut self,
        events: impl IntoIterator<Item = GamepadEvent>,
    ) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        let mut cluster = 0_u64;
        let mut started = false;
        let mut sourced = Vec::new();
        for event in events {
            if !started
                || matches!(
                    event,
                    GamepadEvent::Direction { .. } | GamepadEvent::GuiButton { .. }
                )
            {
                if started {
                    cluster = cluster.wrapping_add(1);
                }
                started = true;
            }
            sourced.push(SourcedGamepadEvent {
                gamepad: 0,
                cluster,
                event,
            });
        }
        self.process_sourced_gamepad_event_batch(sourced, true)
    }

    fn process_sourced_gamepad_event_batch(
        &mut self,
        events: impl IntoIterator<Item = SourcedGamepadEvent>,
        gamepad_gui_control: bool,
    ) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        let events = events.into_iter().collect::<Vec<_>>();
        if !events.is_empty() {
            self.mark_menu_dirty();
            if self.startup_network_transition_active() {
                return Ok(());
            }
            if self.mode == AppMode::Menu && self.startup_view == StartupView::MainMenu {
                self.main_menu_state.note_non_pointer_input();
            }
        }
        #[derive(Clone, Copy)]
        enum ClusterOwner {
            Suppressed,
            Message,
            Definition,
            ContextPending,
            Context,
            Input,
            GameOver,
            Base,
        }

        let mut events = events.into_iter().peekable();
        while let Some(first) = events.next() {
            let gamepad = first.gamepad;
            let cluster = first.cluster;
            let mut cluster_events = vec![first.event];
            while events
                .peek()
                .is_some_and(|event| event.gamepad == gamepad && event.cluster == cluster)
            {
                cluster_events.push(events.next().expect("peeked cluster event").event);
            }

            let game_over_open = self.mode == AppMode::Running && self.game_over_dialog.is_some();
            let eligible_gamepad_gui = gamepad_gui_control && gamepad == 0;
            let mut owner = if game_over_open && !eligible_gamepad_gui {
                // The exclusive evaluation screen owns the whole GUI stack,
                // but C++ did not register a receiver for this source.
                ClusterOwner::Suppressed
            } else if !self.message_dialogs.is_empty() {
                ClusterOwner::Message
            } else if self.definition_selector.is_some() {
                ClusterOwner::Definition
            } else if self.context_menu.is_some() {
                ClusterOwner::ContextPending
            } else if self.game_option_input_dialog.is_some() {
                ClusterOwner::Input
            } else if game_over_open {
                ClusterOwner::GameOver
            } else {
                ClusterOwner::Base
            };
            let mut suppress_base_select_alias = false;
            let mut suppress_base_cancel_alias = false;

            for event in cluster_events {
                let mut pending = Some(event);
                while let Some(event) = pending.take() {
                    match owner {
                        ClusterOwner::Suppressed => {}
                        ClusterOwner::Message => {
                            self.handle_message_dialog_gamepad_event(event)?;
                        }
                        ClusterOwner::Definition => {
                            self.handle_definition_selector_gamepad_event(event)?;
                        }
                        ClusterOwner::ContextPending => {
                            if self.handle_context_menu_gamepad_event(event)? {
                                owner = ClusterOwner::Context;
                            } else {
                                owner = if self.game_option_input_dialog.is_some() {
                                    ClusterOwner::Input
                                } else if self.mode == AppMode::Running
                                    && self.game_over_dialog.is_some()
                                {
                                    ClusterOwner::GameOver
                                } else {
                                    ClusterOwner::Base
                                };
                                pending = Some(event);
                            }
                        }
                        ClusterOwner::Context => {}
                        ClusterOwner::Input => {
                            self.handle_game_option_input_dialog_gamepad_event(event)?;
                        }
                        ClusterOwner::GameOver => {
                            self.handle_game_over_gamepad_event(event)?;
                        }
                        ClusterOwner::Base => {
                            if suppress_base_select_alias
                                && matches!(
                                    event,
                                    GamepadEvent::Action {
                                        action: GamepadActionType::Select,
                                        ..
                                    }
                                )
                            {
                                continue;
                            }
                            if suppress_base_cancel_alias
                                && matches!(
                                    event,
                                    GamepadEvent::Action {
                                        action: GamepadActionType::Cancel,
                                        ..
                                    }
                                )
                            {
                                continue;
                            }
                            let options_owns_raw_gui_button = eligible_gamepad_gui
                                && self.mode == AppMode::Menu
                                && self.startup_view == StartupView::Options;
                            match event {
                                GamepadEvent::GuiButton {
                                    class: GuiButtonClass::Low,
                                    state,
                                    ..
                                } if options_owns_raw_gui_button => {
                                    let actions = self
                                        .startup_options_dialog
                                        .as_mut()
                                        .map(|dialog| match state {
                                            ElementState::Pressed => {
                                                dialog.handle_gamepad_low_down()
                                            }
                                            ElementState::Released => {
                                                dialog.handle_gamepad_low_up()
                                            }
                                        })
                                        .unwrap_or_default();
                                    self.process_options_dialog_actions(actions)?;
                                    // Every AnyLowButton may also produce the
                                    // abstract Select event in this cluster.
                                    suppress_base_select_alias = true;
                                }
                                GamepadEvent::GuiButton {
                                    class: GuiButtonClass::High,
                                    state,
                                    ..
                                } if options_owns_raw_gui_button => {
                                    let actions = if state == ElementState::Pressed {
                                        self.startup_options_dialog
                                            .as_mut()
                                            .map(|dialog| dialog.handle_gamepad_high_down())
                                            .unwrap_or_default()
                                    } else {
                                        Vec::new()
                                    };
                                    self.process_options_dialog_actions(actions)?;
                                    suppress_base_cancel_alias = true;
                                }
                                event => self.handle_gamepad_event(event)?,
                            }
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn handle_definition_selector_gamepad_event(
        &mut self,
        event: GamepadEvent,
    ) -> Result<(), EngineError> {
        let layout = self.definition_selector_layout();
        let actions = self
            .definition_selector
            .as_mut()
            .map(|controller| match event {
                GamepadEvent::Direction {
                    button,
                    state: ElementState::Pressed,
                    ..
                } => layout
                    .as_ref()
                    .map(|layout| match button {
                        ControlButton::Up => controller.handle_gamepad_up(layout),
                        ControlButton::Down => controller.handle_gamepad_down(layout),
                        ControlButton::Left => controller.handle_gamepad_left(layout),
                        ControlButton::Right => controller.handle_gamepad_right(layout),
                    })
                    .unwrap_or_default(),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::Low,
                    state: ElementState::Pressed,
                    ..
                } => layout
                    .as_ref()
                    .map(|layout| controller.handle_gamepad_low_down(layout))
                    .unwrap_or_default(),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::Low,
                    state: ElementState::Released,
                    ..
                } => controller.handle_gamepad_low_up(),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::High,
                    state: ElementState::Pressed,
                    ..
                } => controller.handle_gamepad_high_down(),
                GamepadEvent::Clear { .. } => {
                    controller.cancel_interaction();
                    Vec::new()
                }
                GamepadEvent::Direction { .. }
                | GamepadEvent::Button { .. }
                | GamepadEvent::Action { .. }
                | GamepadEvent::GuiButton { .. } => Vec::new(),
            })
            .unwrap_or_default();
        self.finish_definition_selector_input(actions)
    }

    fn handle_game_option_input_dialog_gamepad_event(
        &mut self,
        event: GamepadEvent,
    ) -> Result<(), EngineError> {
        let layout = self.game_option_input_layout();
        let fonts = self.assets.clonk_fonts.clone();
        let actions = self
            .game_option_input_dialog
            .as_mut()
            .map(|dialog| match event {
                GamepadEvent::Direction {
                    button: ControlButton::Left,
                    state: ElementState::Pressed,
                    ..
                } => dialog.controller.handle_gamepad_direction(false),
                GamepadEvent::Direction {
                    button: ControlButton::Right,
                    state: ElementState::Pressed,
                    ..
                } => dialog.controller.handle_gamepad_direction(true),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::Low,
                    state: ElementState::Pressed,
                    ..
                } => layout
                    .as_ref()
                    .zip(fonts.as_deref())
                    .map(|(layout, fonts)| {
                        dialog
                            .controller
                            .handle_gamepad_low_down(layout, &fonts.text)
                    })
                    .unwrap_or_default(),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::Low,
                    state: ElementState::Released,
                    ..
                } => dialog.controller.handle_gamepad_low_up(),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::High,
                    state: ElementState::Pressed,
                    ..
                } => dialog.controller.handle_gamepad_high_down(),
                GamepadEvent::Clear { .. } => {
                    dialog.controller.cancel_interaction();
                    Vec::new()
                }
                GamepadEvent::Direction { .. }
                | GamepadEvent::Button { .. }
                | GamepadEvent::Action { .. }
                | GamepadEvent::GuiButton { .. } => Vec::new(),
            })
            .unwrap_or_default();
        self.finish_game_option_input_dialog_actions(actions)
    }

    fn handle_message_dialog_gamepad_event(
        &mut self,
        event: GamepadEvent,
    ) -> Result<(), EngineError> {
        let result = match event {
            GamepadEvent::Direction {
                button: button @ (ControlButton::Left | ControlButton::Right),
                state: ElementState::Pressed,
                ..
            } => self.message_dialogs.last_mut().and_then(|dialog| {
                dialog
                    .state
                    .handle_key_down(KeyCode::Tab, button == ControlButton::Left)
            }),
            GamepadEvent::GuiButton {
                class: GuiButtonClass::Low,
                state,
                ..
            } => self
                .message_dialogs
                .last_mut()
                .and_then(|dialog| match state {
                    ElementState::Pressed => dialog.state.handle_gamepad_low_down(),
                    ElementState::Released => dialog.state.handle_gamepad_low_up(),
                }),
            GamepadEvent::GuiButton {
                class: GuiButtonClass::High,
                state: ElementState::Pressed,
                ..
            } => self
                .message_dialogs
                .last_mut()
                .and_then(|dialog| dialog.state.handle_key_down(KeyCode::Escape, false)),
            GamepadEvent::Clear { .. } => {
                if let Some(dialog) = self.message_dialogs.last_mut() {
                    dialog.state.cancel_interaction();
                }
                None
            }
            GamepadEvent::Direction { .. }
            | GamepadEvent::Button { .. }
            | GamepadEvent::Action { .. }
            | GamepadEvent::GuiButton { .. } => None,
        };
        let sounds = self
            .message_dialogs
            .last_mut()
            .map(|dialog| dialog.state.take_sound_events())
            .unwrap_or_default();
        self.play_message_dialog_sound_events(sounds);
        if let Some(result) = result {
            self.finish_message_dialog(result)?;
        }
        Ok(())
    }

    fn handle_game_over_gamepad_event(&mut self, event: GamepadEvent) -> Result<(), EngineError> {
        match event {
            GamepadEvent::GuiButton {
                class: GuiButtonClass::Low,
                state: ElementState::Pressed,
                ..
            } => Err(classic_parity_engine_error(report_classic_parity_boundary(
                ClassicParityBoundary::GameOverChat(ClassicChatMode::All),
            ))),
            GamepadEvent::GuiButton {
                class: GuiButtonClass::High,
                state: ElementState::Pressed,
                ..
            } => self.handle_game_over_action(GameOverAction::End),
            GamepadEvent::Direction {
                button: ControlButton::Left,
                state: ElementState::Pressed,
                ..
            } => Err(classic_parity_engine_error(report_classic_parity_boundary(
                ClassicParityBoundary::GameOverFocusTraversal(
                    ClassicGameOverFocusDirection::Backward,
                ),
            ))),
            GamepadEvent::Direction {
                button: ControlButton::Right,
                state: ElementState::Pressed,
                ..
            } => Err(classic_parity_engine_error(report_classic_parity_boundary(
                ClassicParityBoundary::GameOverFocusTraversal(
                    ClassicGameOverFocusDirection::Forward,
                ),
            ))),
            GamepadEvent::Direction { .. }
            | GamepadEvent::Button { .. }
            | GamepadEvent::Clear { .. }
            | GamepadEvent::GuiButton { .. }
            | GamepadEvent::Action { .. } => Ok(()),
        }
    }

    fn handle_gamepad_event(&mut self, event: GamepadEvent) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        match event {
            GamepadEvent::Direction {
                slot,
                button,
                state,
            } => {
                self.handle_gamepad_direction(slot, button, state)?;
            }
            GamepadEvent::Button {
                slot,
                button,
                state,
            } => {
                self.handle_gamepad_button(slot, button, state)?;
            }
            GamepadEvent::Clear { .. } => {
                if self.classic_host_lobby_active() {
                    self.cancel_classic_host_lobby_interaction();
                } else if self.mode == AppMode::Menu
                    && self.startup_view == StartupView::ScenarioBrowser
                {
                    self.scenario_game_options.cancel_interaction();
                } else if self.mode == AppMode::Menu && self.startup_view == StartupView::Options {
                    let actions = self
                        .startup_options_dialog
                        .as_mut()
                        .map(|dialog| dialog.handle_pointer_left())
                        .unwrap_or_default();
                    self.process_options_dialog_actions(actions)?;
                } else if matches!(self.mode, AppMode::Running) && self.game_over_dialog.is_none() {
                    self.dispatch_control_event(ControlEvent::ClearPressed)?;
                }
            }
            GamepadEvent::GuiButton { .. } => {}
            GamepadEvent::Action {
                slot,
                action,
                state,
            } => {
                self.handle_gamepad_action(slot, action, state)?;
            }
        }
        Ok(())
    }

    fn handle_gamepad_button(
        &mut self,
        slot: GamepadSlot,
        button: LegacyGamepadButton,
        state: ElementState,
    ) -> Result<(), EngineError> {
        if !self.message_dialogs.is_empty() {
            return Ok(());
        }
        if self.definition_selector.is_some() {
            return Ok(());
        }
        if self.game_over_dialog.is_some() {
            return Ok(());
        }
        if !matches!(self.mode, AppMode::Running) {
            return Ok(());
        }
        let routing = self.local_controls.route_keyboard_candidates(
            self.gamepad_bindings.control_candidates_for_button(
                slot.index(),
                button.index(),
                state,
            ),
            state,
            false,
            |owner| {
                self.engine
                    .player(owner)
                    .map(|player| player.control_style())
            },
        );
        if let KeyboardRoutingOutcome::Consumed {
            owner: Some(owner),
            event: Some(event),
        } = routing
        {
            self.dispatch_control_event_for_local_player(owner, event)?;
        }
        Ok(())
    }

    fn handle_gamepad_direction(
        &mut self,
        slot: GamepadSlot,
        button: ControlButton,
        state: ElementState,
    ) -> Result<(), EngineError> {
        if !self.message_dialogs.is_empty() {
            return self.handle_message_dialog_gamepad_event(GamepadEvent::Direction {
                slot,
                button,
                state,
            });
        }
        if self.definition_selector.is_some() {
            return self.handle_definition_selector_gamepad_event(GamepadEvent::Direction {
                slot,
                button,
                state,
            });
        }
        if self.game_over_dialog.is_some() {
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            return self.handle_classic_lobby_gamepad_direction(button, state);
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::ScenarioBrowser {
            let direction = match button {
                ControlButton::Left => GameOptionGamepadDirection::Left,
                ControlButton::Right => GameOptionGamepadDirection::Right,
                ControlButton::Up => GameOptionGamepadDirection::Up,
                ControlButton::Down => GameOptionGamepadDirection::Down,
            };
            if state == ElementState::Pressed
                && self.scenario_game_options.focused_button().is_some()
            {
                self.menu_state
                    .set_dialog_focus(ScenselDialogFocus::Options);
                let outcome = self
                    .scenario_game_options
                    .handle_gamepad_direction(direction);
                let captured = outcome.captured;
                self.finish_game_option_input(outcome.actions)?;
                if captured {
                    return Ok(());
                }
            }
            if matches!(button, ControlButton::Left | ControlButton::Right) {
                if state == ElementState::Pressed {
                    self.advance_scensel_dialog_focus(button == ControlButton::Left);
                }
                return Ok(());
            }
        }
        if self.mode == AppMode::Menu
            && matches!(button, ControlButton::Left | ControlButton::Right)
            && matches!(
                self.startup_view,
                StartupView::NetworkGame | StartupView::PlayerSelection | StartupView::Options
            )
        {
            if state == ElementState::Pressed {
                let backwards = button == ControlButton::Left;
                match self.startup_view {
                    StartupView::NetworkGame => {
                        let actions = self
                            .startup_network_dialog
                            .as_mut()
                            .map(|dialog| dialog.handle_gamepad_horizontal(backwards))
                            .unwrap_or_default();
                        self.process_network_dialog_actions(actions)?;
                    }
                    StartupView::PlayerSelection => {
                        let actions = self
                            .startup_player_dialog
                            .as_mut()
                            .map(|dialog| dialog.handle_gamepad_horizontal(backwards))
                            .unwrap_or_default();
                        self.process_player_dialog_actions(actions)?;
                    }
                    StartupView::Options => {
                        let actions = self
                            .startup_options_dialog
                            .as_mut()
                            .map(|dialog| dialog.handle_gamepad_horizontal(backwards))
                            .unwrap_or_default();
                        self.process_options_dialog_actions(actions)?;
                    }
                    _ => unreachable!(),
                }
            }
            return Ok(());
        }
        match self.mode {
            AppMode::Menu => {
                if let Some(key) = menu_key_from_control_button(button) {
                    if self.handle_startup_dialog_key(key, state)? {
                        return Ok(());
                    }
                    match self.startup_view {
                        StartupView::ScenarioBrowser => match (state, key) {
                            (ElementState::Pressed, KeyCode::Up) => {
                                self.handle_menu_input(|menu| menu.move_list_selection_clamped(-1))?
                            }
                            (ElementState::Pressed, KeyCode::Down) => {
                                self.handle_menu_input(|menu| menu.move_list_selection_clamped(1))?
                            }
                            (ElementState::Pressed, KeyCode::Left) => self.scensel_do_back()?,
                            (ElementState::Pressed, KeyCode::Right) => {
                                self.handle_menu_input(|menu| {
                                    menu.menu().handle_key_down(KeyCode::Enter)
                                })?;
                                self.handle_menu_input(|menu| {
                                    menu.menu().handle_key_up(KeyCode::Enter)
                                })?;
                            }
                            (ElementState::Pressed, _) => {
                                self.handle_menu_input(|menu| menu.menu().handle_key_down(key))?
                            }
                            (
                                ElementState::Released,
                                KeyCode::Up | KeyCode::Down | KeyCode::Left | KeyCode::Right,
                            ) => {}
                            (ElementState::Released, _) => {
                                self.handle_menu_input(|menu| menu.menu().handle_key_up(key))?
                            }
                        },
                        StartupView::NetworkGame | StartupView::PlayerSelection => {}
                        StartupView::MainMenu => {
                            let actions = match state {
                                ElementState::Pressed => self.main_menu_state.handle_key_down(key),
                                ElementState::Released => self.main_menu_state.handle_key_up(key),
                            };
                            self.process_main_menu_actions(actions)?;
                        }
                        StartupView::NetworkLobby => match state {
                            ElementState::Pressed => {
                                self.handle_menu_input(|menu| menu.menu().handle_key_down(key))?
                            }
                            ElementState::Released => {
                                self.handle_menu_input(|menu| menu.menu().handle_key_up(key))?
                            }
                        },
                        StartupView::Options | StartupView::About => {}
                    }
                }
            }
            AppMode::Running => {
                let event = match state {
                    ElementState::Pressed => ControlEvent::Press(button),
                    ElementState::Released => ControlEvent::Release(button),
                };
                if let Some(owner) = self.local_controls.owner_for_set(slot.control_set()) {
                    self.dispatch_control_event_for_local_player(owner, event)?;
                }
            }
            AppMode::Loading => {}
        }
        Ok(())
    }

    fn handle_menu_cancel_action(&mut self, state: ElementState) -> Result<(), EngineError> {
        if self.game_over_dialog.is_some() {
            if state == ElementState::Pressed {
                self.handle_game_over_action(GameOverAction::End)?;
            }
            return Ok(());
        }
        if self.handle_startup_dialog_key(KeyCode::Escape, state)? {
            return Ok(());
        }
        match self.startup_view {
            StartupView::ScenarioBrowser => match state {
                ElementState::Pressed => self.close_scenario_browser(),
                ElementState::Released => {}
            },
            StartupView::NetworkGame | StartupView::PlayerSelection => {}
            StartupView::MainMenu => {
                if state == ElementState::Pressed {
                    self.request_exit();
                }
            }
            StartupView::NetworkLobby => {
                if state == ElementState::Pressed {
                    self.show_main_menu();
                }
            }
            StartupView::Options | StartupView::About => {}
        }
        Ok(())
    }

    fn handle_gamepad_action(
        &mut self,
        slot: GamepadSlot,
        action: GamepadActionType,
        state: ElementState,
    ) -> Result<(), EngineError> {
        if !self.message_dialogs.is_empty() {
            return self.handle_message_dialog_gamepad_event(GamepadEvent::Action {
                slot,
                action,
                state,
            });
        }
        if self.definition_selector.is_some() {
            return Ok(());
        }
        if self.game_over_dialog.is_some() {
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            return self.handle_classic_lobby_gamepad_action(action, state);
        }
        match action {
            GamepadActionType::Select => match self.mode {
                AppMode::Menu => {
                    if self.startup_view == StartupView::ScenarioBrowser
                        && self.scenario_game_options.focused_button().is_some()
                    {
                        self.menu_state
                            .set_dialog_focus(ScenselDialogFocus::Options);
                        let outcome = match state {
                            ElementState::Pressed => {
                                self.scenario_game_options.handle_gamepad_low_down()
                            }
                            ElementState::Released => {
                                self.scenario_game_options.handle_gamepad_low_up()
                            }
                        };
                        let captured = outcome.captured;
                        self.finish_game_option_input(outcome.actions)?;
                        if captured {
                            return Ok(());
                        }
                    }
                    if self.startup_view == StartupView::ScenarioBrowser
                        && self.menu_state.definition_checkbox_focused
                    {
                        if state == ElementState::Pressed
                            && self.menu_state.toggle_definition_checkbox()
                        {
                            self.play_ui_sound("ArrowHit");
                        }
                        return Ok(());
                    }
                    if self.startup_view == StartupView::ScenarioBrowser {
                        match self.menu_state.dialog_focus() {
                            ScenselDialogFocus::Back => {
                                if state == ElementState::Pressed {
                                    self.scensel_do_back()?;
                                }
                                return Ok(());
                            }
                            ScenselDialogFocus::Search => return Ok(()),
                            ScenselDialogFocus::Definitions => return Ok(()),
                            ScenselDialogFocus::List
                            | ScenselDialogFocus::Options
                            | ScenselDialogFocus::Open => {}
                        }
                    }
                    if self.handle_startup_dialog_key(KeyCode::Enter, state)? {
                        return Ok(());
                    }
                    match self.startup_view {
                        StartupView::ScenarioBrowser => match state {
                            ElementState::Pressed => self.handle_menu_input(|menu| {
                                menu.menu().handle_key_down(KeyCode::Enter)
                            })?,
                            ElementState::Released => self.handle_menu_input(|menu| {
                                menu.menu().handle_key_up(KeyCode::Enter)
                            })?,
                        },
                        StartupView::NetworkGame | StartupView::PlayerSelection => {}
                        StartupView::MainMenu => {
                            let actions = match state {
                                ElementState::Pressed => {
                                    self.main_menu_state.handle_key_down(KeyCode::Enter)
                                }
                                ElementState::Released => {
                                    self.main_menu_state.handle_key_up(KeyCode::Enter)
                                }
                            };
                            self.process_main_menu_actions(actions)?;
                        }
                        StartupView::NetworkLobby => match state {
                            ElementState::Pressed => self.handle_menu_input(|menu| {
                                menu.menu().handle_key_down(KeyCode::Enter)
                            })?,
                            ElementState::Released => self.handle_menu_input(|menu| {
                                menu.menu().handle_key_up(KeyCode::Enter)
                            })?,
                        },
                        StartupView::Options | StartupView::About => {}
                    }
                }
                AppMode::Running | AppMode::Loading => {}
            },
            GamepadActionType::Cancel => match self.mode {
                AppMode::Menu => {
                    self.handle_menu_cancel_action(state)?;
                }
                AppMode::Running | AppMode::Loading => {}
            },
            GamepadActionType::MenuToggle => match self.mode {
                AppMode::Menu => {
                    self.handle_menu_cancel_action(state)?;
                }
                AppMode::Running => {
                    if state == ElementState::Pressed {
                        if self.ingame_menu_belongs_to(self.local_owner) {
                            self.close_ingame_menu_by_user()?;
                        } else {
                            self.open_ingame_menu()?;
                        }
                    }
                }
                AppMode::Loading => {}
            },
        }
        Ok(())
    }

    fn handle_cursor_moved(&mut self, position: PhysicalPosition<f64>) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.mark_menu_dirty();
        if self.startup_network_transition_active() {
            return Ok(());
        }
        let point = gui_point_from_position(position);
        if self.mode == AppMode::Running {
            self.running_pointer_position = Some(point);
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::MainMenu {
            self.main_menu_state.note_pointer_position(Some(point));
        }
        if self.handle_message_dialog_pointer_move(point) {
            return Ok(());
        }
        if self.definition_selector.is_some() {
            let actions = self
                .definition_selector_layout()
                .and_then(|layout| {
                    self.definition_selector
                        .as_mut()
                        .map(|controller| controller.handle_pointer_move(point, &layout))
                })
                .unwrap_or_default();
            self.finish_definition_selector_input(actions)?;
            return Ok(());
        }
        if self.handle_context_menu_pointer_move(point)? {
            return Ok(());
        }
        if self.game_option_input_dialog.is_some() {
            self.game_option_input_pointer_position = Some(point);
            let layout = self.game_option_input_layout();
            let fonts = self.assets.clonk_fonts.clone();
            let actions = layout
                .as_ref()
                .zip(fonts.as_deref())
                .and_then(|(layout, fonts)| {
                    self.game_option_input_dialog.as_mut().map(|dialog| {
                        dialog
                            .controller
                            .handle_pointer_move(point, layout, &fonts.text)
                    })
                })
                .unwrap_or_default();
            self.finish_game_option_input_dialog_actions(actions)?;
            return Ok(());
        }
        if let Some(dialog) = self.game_over_dialog.as_mut() {
            let surface = self.graphics.surface();
            dialog.handle_pointer_move(point.x, point.y, surface.width(), surface.height());
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            return self.handle_classic_lobby_pointer_move(point);
        }
        match self.mode {
            AppMode::Menu => {
                if self.game_over_dialog.is_some() {
                    self.pointer_left_unchecked();
                    return Ok(());
                }
                match self.startup_view {
                    StartupView::ScenarioBrowser => {
                        self.menu_state.set_pointer_position(Some(point));
                        let actions = self.scenario_game_options.handle_pointer_move(point);
                        self.finish_game_option_input(actions)?;
                        if self.handle_scensel_search_pointer_move(point)
                            || self.handle_scensel_scrollbar_move(point)
                        {
                            Ok(())
                        } else {
                            self.handle_menu_input(|state| state.menu().handle_pointer_move(point))
                        }
                    }
                    StartupView::NetworkGame => {
                        let actions = self
                            .startup_network_dialog
                            .as_mut()
                            .map(|dialog| dialog.handle_pointer_move(point))
                            .unwrap_or_default();
                        self.process_network_dialog_actions(actions)
                    }
                    StartupView::PlayerSelection => {
                        let actions = self
                            .startup_player_dialog
                            .as_mut()
                            .map(|dialog| dialog.handle_pointer_move(point))
                            .unwrap_or_default();
                        self.process_player_dialog_actions(actions)
                    }
                    StartupView::MainMenu => {
                        self.main_menu_state.set_pointer_position(Some(point));
                        let actions = self.main_menu_state.handle_pointer_move(point);
                        self.process_main_menu_actions(actions)
                    }
                    StartupView::NetworkLobby => {
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            let width = self.graphics.surface().width() as f32;
                            let height = self.graphics.surface().height() as f32;
                            lobby.update_layout(width, height);
                            match lobby.pointer_region(point) {
                                LobbyPointerRegion::Menu => self.handle_menu_input(|state| {
                                    state.set_pointer_position(Some(point));
                                    state.menu().handle_pointer_move(point)
                                }),
                                LobbyPointerRegion::Panel => {
                                    lobby.handle_panel_pointer_move(point);
                                    self.menu_state.set_pointer_position(None);
                                    Ok(())
                                }
                            }
                        } else {
                            Ok(())
                        }
                    }
                    StartupView::Options => {
                        let actions = self
                            .startup_options_dialog
                            .as_mut()
                            .map(|dialog| dialog.handle_pointer_move(point))
                            .unwrap_or_default();
                        self.process_options_dialog_actions(actions)?;
                        Ok(())
                    }
                    StartupView::About => {
                        let actions = self
                            .startup_about_dialog
                            .as_mut()
                            .map(|dialog| dialog.handle_pointer_move(point))
                            .unwrap_or_default();
                        self.process_about_dialog_actions(actions)
                    }
                }
            }
            AppMode::Running => {
                self.ingame_gui_pointer = Some(point);
                if self.scoreboard_close_pointer_capture
                    || self.scoreboard_pointer_target(point)?.is_some()
                {
                    if let Some(state) = self.mouse_state.as_mut() {
                        state.moved = true;
                    }
                    self.ingame_pointer = None;
                    return Ok(());
                }
                if self.handle_ingame_menu_pointer_move(point) {
                    self.ingame_pointer = None;
                    return Ok(());
                }
                self.update_ingame_pointer(point);
                if let Some(EngineScriptMenuPointerTarget::Item(index)) =
                    self.script_menu_pointer_target(point)?
                {
                    if self.select_script_menu_pointer_item(index)? {
                        self.refresh_after_script_menu_pointer();
                    }
                }
                Ok(())
            }
            AppMode::Loading => Ok(()),
        }
    }

    fn update_ingame_pointer(&mut self, point: GuiPoint) {
        let pointer = self
            .local_controls
            .mouse_owner()
            .and_then(|owner| self.graphics.viewport_output_point_for_owner(owner, point));
        if let Some(pointer) = pointer {
            if let Some(state) = self.mouse_state.as_mut() {
                state.update(pointer);
            }
            if let Some(state) = self.ingame_right_mouse_state.as_mut() {
                state.motion.update(pointer);
            }
            self.ingame_pointer = Some(pointer);
            self.update_ingame_drag_selection_kinds();
        } else {
            if let Some(state) = self.mouse_state.as_mut() {
                state.moved = true;
            }
            if let Some(state) = self.ingame_right_mouse_state.as_mut() {
                state.motion.moved = true;
            }
            self.ingame_pointer = None;
        }
    }

    fn ingame_menu_pointer_target(
        &self,
        point: GuiPoint,
    ) -> Option<(i32, IngameMenuPointerTarget)> {
        if !self.mouse_control {
            return None;
        }
        let player = self.local_controls.mouse_owner()?;
        let area = self.graphics.viewport_rect(player)?;
        let menu = self.ingame_menu.get(player)?;
        let fallback = self.assets.font_arc();
        let font = lc_frontend::hud::HudFont::from_set(
            self.assets.clonk_fonts.as_deref(),
            fallback.as_ref(),
        );
        let gfx = IngameMenuGraphics {
            show_commands: self.display_flags.show_commands,
            ..IngameMenuGraphics::default()
        };
        menu.pointer_target(area, &font, &gfx, point)
            .map(|target| (player, target))
    }

    fn handle_ingame_menu_pointer_move(&mut self, point: GuiPoint) -> bool {
        let Some((player, target)) = self.ingame_menu_pointer_target(point) else {
            return false;
        };
        if let IngameMenuPointerTarget::Item(index) = target {
            if let Some(menu) = self.ingame_menu.get_mut(player) {
                // C4MenuItem::MouseEnter directly selects the hovered item
                // (C4Menu.cpp:239-244; C4MainMenu.cpp:299-303).
                menu.set_selection(index);
            }
        }
        true
    }

    fn handle_ingame_menu_pointer_button(
        &mut self,
        button_state: ElementState,
        enter_all: bool,
    ) -> Result<bool, EngineError> {
        let Some(point) = self.ingame_gui_pointer else {
            return Ok(false);
        };
        let Some((player, target)) = self.ingame_menu_pointer_target(point) else {
            return Ok(false);
        };
        self.mouse_state = None;
        self.ingame_right_mouse_state = None;
        if button_state == ElementState::Released {
            if let IngameMenuPointerTarget::Item(index) = target {
                let outcome = self.ingame_menu.get_mut(player).and_then(|menu| {
                    menu.set_selection(index);
                    menu.handle_command(
                        if enter_all {
                            ControlCommand::MenuEnterAll
                        } else {
                            ControlCommand::MenuEnter
                        },
                        CommandKind::Press,
                    )
                });
                if let Some(outcome) = outcome {
                    // C4MenuItem enters on button-up; C4MainMenu executes its
                    // own Player-owned command directly (C4Menu.cpp:213-233;
                    // C4MainMenu.cpp:305-310).
                    self.execute_ingame_menu_outcome_for_player(player, outcome)?;
                }
            }
        }
        Ok(true)
    }

    fn ingame_drag_selection_kind(&self, motion: IngameMouseState) -> IngameDragSelectionKind {
        if !motion.moved
            || !motion.selection_frame
            || motion.selection_kind != IngameDragSelectionKind::Unknown
        {
            return motion.selection_kind;
        }
        let first = ingame_pointer_world_pixel(motion.start);
        let second = ingame_pointer_world_pixel(motion.last);
        if !self
            .engine
            .mouse_drag_crew_in_rect(self.local_owner, first, second)
            .is_empty()
        {
            IngameDragSelectionKind::Crew
        } else if !self
            .engine
            .mouse_drag_carryables_in_rect(first, second)
            .is_empty()
        {
            IngameDragSelectionKind::Objects
        } else {
            IngameDragSelectionKind::Unknown
        }
    }

    fn ingame_mouse_selectable_object(&self, owner: i32, object: ObjectId) -> bool {
        self.snapshot.object(object).is_some_and(|snapshot| {
            snapshot.category & lc_engine::CATEGORY_MOUSE_SELECT != 0
                || snapshot.ocf & lc_engine::ocf::ALIVE != 0
                    && self
                        .snapshot
                        .players
                        .iter()
                        .find(|player| player.id == owner)
                        .is_some_and(|player| player.crew.contains(&object))
        })
    }

    fn ingame_primary_mouse_target(&self, owner: i32, point: GuiPoint) -> Option<ObjectId> {
        let primary_ocf = lc_engine::ocf::GRAB
            | lc_engine::ocf::CHOP
            | lc_engine::ocf::CONTAINER
            | lc_engine::ocf::CONSTRUCT
            | lc_engine::ocf::LIVING
            | lc_engine::ocf::CARRYABLE
            | lc_engine::ocf::EXCLUSIVE;
        self.graphics
            .object_at_point_with_ocf(&self.snapshot, owner, point, primary_ocf)
    }

    fn ingame_mouse_select_target(&self, owner: i32, point: GuiPoint) -> Option<ObjectId> {
        self.ingame_primary_mouse_target(owner, point)
            .filter(|object| self.ingame_mouse_selectable_object(owner, *object))
    }

    fn update_ingame_drag_selection_kinds(&mut self) {
        let left_kind = self
            .mouse_state
            .map(|motion| self.ingame_drag_selection_kind(motion));
        let right_kind = self
            .ingame_right_mouse_state
            .map(|state| self.ingame_drag_selection_kind(state.motion));
        if let Some(kind) = left_kind {
            if let Some(motion) = self.mouse_state.as_mut() {
                motion.selection_kind = kind;
            }
        }
        if let Some(kind) = right_kind {
            if let Some(state) = self.ingame_right_mouse_state.as_mut() {
                state.motion.selection_kind = kind;
            }
        }
    }

    /// The target copied into C4MouseControl::DownRegion for one grouped
    /// cursor-inventory cell. These regions sit above the world pick layer
    /// and retain the group's first object as their Target
    /// (C4Viewport.cpp:911-917; C4ObjectList.cpp:343-372).
    fn ingame_inventory_region_target(&self, point: GuiPoint) -> Option<ObjectId> {
        let pointer = self.graphics.viewport_output_point_at(point)?;
        if pointer.owner != self.local_owner {
            return None;
        }
        let viewport = self.graphics.viewport_rect(pointer.owner)?;
        let cursor = self
            .snapshot
            .players
            .iter()
            .find(|player| player.id == pointer.owner)
            .and_then(|player| player.view_cursor.or(player.cursor))?;
        let cursor_definition = &self.snapshot.object(cursor)?.definition_id;
        if self
            .engine
            .definition_hide_hud_elements(cursor_definition)
            & lc_engine::HIDE_HUD_ELEMENT_INVENTORY
            != 0
        {
            return None;
        }
        let inventory = collect_crew_inventory(&self.engine, &self.snapshot, cursor);
        let section = lc_frontend::hud::inventory_region_index(viewport, point, inventory.len())?;
        inventory.get(section).map(|item| item.object_id)
    }

    fn ingame_command_region_at(&self, point: GuiPoint) -> bool {
        if !self.display_flags.show_commands
            || self.object_menu.is_some()
            || self.engine.cursor_object_menu(self.local_owner).is_some()
        {
            return false;
        }
        let Some(pointer) = self.graphics.viewport_output_point_at(point) else {
            return false;
        };
        if pointer.owner != self.local_owner {
            return false;
        }
        let Some(cursor) = self
            .snapshot
            .players
            .iter()
            .find(|player| player.id == pointer.owner)
            .and_then(|player| player.cursor)
        else {
            return false;
        };
        let Some(viewport) = self.graphics.viewport_rect(pointer.owner) else {
            return false;
        };
        let context = AppCommandContext {
            engine: &self.engine,
            bindings: &self.bindings,
            snapshot: &self.snapshot,
        };
        let commands = draw_commands::build_cursor_commands(&self.snapshot, cursor, &context);
        lc_frontend::hud::command_region_index(viewport, point, &commands).is_some()
    }

    fn ingame_viewport_region(&self, point: GuiPoint) -> Option<IngameViewportRegion> {
        // DrawCommands registers after DrawIDList and C4RegionList::Add
        // prepends, so command pairs win the unlikely overlap.
        if self.ingame_command_region_at(point) {
            return Some(IngameViewportRegion::Command);
        }
        self.ingame_inventory_region_target(point)
            .map(IngameViewportRegion::Inventory)
    }

    fn handle_ingame_mouse_button(
        &mut self,
        button_state: ElementState,
    ) -> Result<(), EngineError> {
        let script_menu_target = match self.ingame_pointer {
            Some(pointer) => self.script_menu_pointer_target(pointer.screen)?,
            None => None,
        };
        if let Some(target) = script_menu_target {
            self.mouse_state = None;
            if button_state == ElementState::Pressed {
                self.ingame_last_left_down = None;
                self.ingame_ignore_left_up = false;
            }
            if button_state == ElementState::Released {
                match target {
                    EngineScriptMenuPointerTarget::Close => {
                        self.dispatch_control_event(ControlEvent::RawPlayerControl {
                            command: lc_engine::COM_MENU_CLOSE,
                            data: 0,
                        })?;
                    }
                    EngineScriptMenuPointerTarget::Item(index) => {
                        if self.select_script_menu_pointer_item(index)? {
                            let data = i32::try_from(index).unwrap_or(i32::MAX);
                            self.dispatch_control_event(ControlEvent::RawPlayerControl {
                                command: lc_engine::COM_MENU_ENTER,
                                data,
                            })?;
                        }
                    }
                    EngineScriptMenuPointerTarget::Background => {}
                }
                self.refresh_after_script_menu_pointer();
            }
            return Ok(());
        }
        match button_state {
            ElementState::Pressed => {
                let now = Instant::now();
                let is_double = self.ingame_last_left_down.take().is_some_and(|last| {
                    now.saturating_duration_since(last) < INGAME_DOUBLE_CLICK_INTERVAL
                });
                if is_double {
                    // The platform emits LeftDouble instead of a second
                    // LeftDown. C4MouseControl clears the down state and
                    // consumes the subsequent LeftUp (cpp:982-988).
                    self.mouse_state = None;
                    self.ingame_ignore_left_up = true;
                    self.on_ingame_mouse_double()
                } else {
                    self.ingame_last_left_down = Some(now);
                    self.ingame_ignore_left_up = false;
                    self.on_ingame_mouse_down()
                }
            }
            ElementState::Released => {
                if std::mem::take(&mut self.ingame_ignore_left_up) {
                    self.mouse_state = None;
                    Ok(())
                } else {
                    self.on_ingame_mouse_up()
                }
            }
        }
    }

    fn handle_scoreboard_pointer_button(
        &mut self,
        button_state: ElementState,
    ) -> Result<bool, EngineError> {
        if button_state == ElementState::Pressed {
            self.scoreboard_close_pointer_capture = false;
        }
        if button_state == ElementState::Released
            && std::mem::take(&mut self.scoreboard_close_pointer_capture)
        {
            let target = self
                .running_pointer_position
                .map(|point| self.scoreboard_pointer_target(point))
                .transpose()?
                .flatten();
            if target == Some(ScoreboardPointerTarget::Close)
                && self.scoreboard_dialog.take().is_some()
            {
                self.play_ui_sound("Click");
            }
            // CMouse clears pDragElement before release hit-testing. A release
            // back over this dialog remains consumed; one outside falls
            // through to the next shared dialog or the game world.
            return Ok(target.is_some());
        }

        let Some(point) = self.running_pointer_position else {
            return Ok(false);
        };
        let target = self.scoreboard_pointer_target(point)?;
        if button_state == ElementState::Pressed && target == Some(ScoreboardPointerTarget::Close) {
            self.scoreboard_close_pointer_capture = true;
        }
        Ok(target.is_some())
    }

    fn handle_right_mouse_button(&mut self, button_state: ElementState) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.mark_menu_dirty();
        if self.startup_network_transition_active() {
            return Ok(());
        }
        if button_state == ElementState::Pressed {
            // A context action closes on down. If its matching up was lost,
            // the next physical press starts a new gesture and invalidates
            // the old release latch before any underlying control sees it.
            self.context_menu_pointer_capture = None;
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::MainMenu {
            self.main_menu_state.note_pointer_button();
        }
        if self
            .consume_closed_context_pointer_release(button_state, ContextMenuPointerButton::Right)
        {
            return Ok(());
        }
        if !self.message_dialogs.is_empty() {
            return Ok(());
        }
        if self.definition_selector.is_some() {
            return Ok(());
        }
        if self.handle_context_menu_pointer_button(button_state, ContextMenuPointerButton::Right)? {
            return Ok(());
        }
        if self.game_option_input_dialog.is_some() {
            if button_state == ElementState::Pressed {
                let point = self.game_option_input_pointer_position;
                let layout = self.game_option_input_layout();
                let outcome = point.zip(layout.as_ref()).and_then(|(point, layout)| {
                    self.game_option_input_dialog.as_mut().map(|dialog| {
                        dialog.controller.request_context_menu_at(
                            point,
                            layout,
                            clipboard_text_available(),
                            &InputDialogContextLabels::default(),
                        )
                    })
                });
                if let Some(outcome) = outcome {
                    self.finish_game_option_input_dialog_actions(outcome.actions)?;
                }
            }
            return Ok(());
        }
        if self.game_over_dialog.is_some() {
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            return self.handle_classic_lobby_secondary_button(button_state);
        }
        match self.mode {
            AppMode::Menu => {
                if button_state == ElementState::Pressed {
                    match self.startup_view {
                        StartupView::MainMenu => {
                            self.open_startup_participants_context_menu()?;
                        }
                        StartupView::ScenarioBrowser => {
                            self.open_scenario_search_context_menu(false)?;
                        }
                        StartupView::PlayerSelection => {
                            self.open_startup_player_context_menu()?;
                        }
                        _ => {}
                    }
                }
                Ok(())
            }
            AppMode::Running => {
                let scoreboard_hit = self
                    .running_pointer_position
                    .map(|point| self.scoreboard_pointer_target(point))
                    .transpose()?
                    .flatten()
                    .is_some();
                if scoreboard_hit || self.handle_ingame_menu_pointer_button(button_state, true)? {
                    Ok(())
                } else {
                    self.handle_ingame_right_mouse_button(button_state)
                }
            }
            AppMode::Loading => Ok(()),
        }
    }

    fn handle_other_mouse_button(&mut self, button_state: ElementState) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.mark_menu_dirty();
        if self.startup_network_transition_active() {
            return Ok(());
        }
        if button_state == ElementState::Pressed {
            self.context_menu_pointer_capture = None;
            self.game_option_pointer_capture = false;
            self.game_option_input_pointer_capture = (self.game_option_input_dialog.is_some()
                && self.context_menu.is_none()
                && self.message_dialogs.is_empty())
            .then_some(ContextMenuPointerButton::Other);
        }
        let input_dialog_release_latched = button_state == ElementState::Released
            && self.game_option_input_pointer_capture == Some(ContextMenuPointerButton::Other);
        if input_dialog_release_latched {
            self.game_option_input_pointer_capture = None;
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::MainMenu {
            self.main_menu_state.note_pointer_button();
        }
        if self
            .consume_closed_context_pointer_release(button_state, ContextMenuPointerButton::Other)
        {
            return Ok(());
        }
        if self.game_option_input_dialog.is_some()
            && self.context_menu.is_none()
            && self.message_dialogs.is_empty()
        {
            if button_state == ElementState::Pressed {
                let point = self.game_option_input_pointer_position;
                let layout = self.game_option_input_layout();
                let fonts = self.assets.clonk_fonts.clone();
                let primary = arboard::Clipboard::new()
                    .and_then(|mut clipboard| clipboard.get_text())
                    .ok();
                let outcome = point.zip(layout.as_ref()).zip(fonts.as_deref()).and_then(
                    |((point, layout), fonts)| {
                        self.game_option_input_dialog.as_mut().map(|dialog| {
                            dialog.controller.handle_pointer_middle_down(
                                point,
                                primary.as_deref(),
                                layout,
                                &fonts.text,
                            )
                        })
                    },
                );
                if let Some(outcome) = outcome {
                    self.finish_game_option_input_dialog_actions(outcome.actions)?;
                }
            }
            return Ok(());
        }
        if input_dialog_release_latched {
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            return self.handle_classic_lobby_middle_button(button_state);
        }
        if self.message_dialogs.is_empty() && self.definition_selector.is_none() {
            self.handle_context_menu_pointer_button(button_state, ContextMenuPointerButton::Other)?;
        }
        Ok(())
    }

    fn handle_ingame_right_mouse_button(
        &mut self,
        button_state: ElementState,
    ) -> Result<(), EngineError> {
        let script_menu_target = match self.ingame_pointer {
            Some(pointer) => self.script_menu_pointer_target(pointer.screen)?,
            None => None,
        };
        if let Some(target) = script_menu_target {
            self.ingame_right_mouse_state = None;
            if button_state == ElementState::Released {
                if let EngineScriptMenuPointerTarget::Item(index) = target {
                    if self.select_script_menu_pointer_item(index)? {
                        let data = i32::try_from(index).unwrap_or(i32::MAX);
                        self.dispatch_control_event(ControlEvent::RawPlayerControl {
                            command: lc_engine::COM_MENU_ENTER_ALL,
                            data,
                        })?;
                    }
                }
                self.refresh_after_script_menu_pointer();
            }
            return Ok(());
        }
        if !self.mouse_control {
            self.ingame_right_mouse_state = None;
            self.ingame_dragged_objects.clear();
            return Ok(());
        }

        if button_state == ElementState::Pressed {
            let Some(pointer) = self.ingame_pointer else {
                self.ingame_right_mouse_state = None;
                return Ok(());
            };
            if pointer.owner != self.local_owner {
                self.ingame_right_mouse_state = None;
                return Ok(());
            }
            let region = self.ingame_viewport_region(pointer.screen);
            let region_target = region.and_then(|region| match region {
                IngameViewportRegion::Inventory(target) => Some(target),
                IngameViewportRegion::Command => None,
            });
            // UpdateCursorTarget's primary FindVisObject mask. RightUp later
            // refills with OCF_All for context, but DownTarget must ignore
            // plain background objects exactly like C++ (cpp:469-477,1248).
            let primary_ocf = lc_engine::ocf::GRAB
                | lc_engine::ocf::CHOP
                | lc_engine::ocf::CONTAINER
                | lc_engine::ocf::CONSTRUCT
                | lc_engine::ocf::LIVING
                | lc_engine::ocf::CARRYABLE
                | lc_engine::ocf::EXCLUSIVE;
            let down_target = region_target.or_else(|| {
                if region.is_some() {
                    return None;
                }
                self.graphics.object_at_point_with_ocf(
                    &self.snapshot,
                    self.local_owner,
                    pointer.screen,
                    primary_ocf,
                )
            });
            self.ingame_right_mouse_state = Some(IngameRightMouseState::new(
                pointer,
                down_target,
                region.is_some(),
            ));
            return Ok(());
        }

        let drag = self.ingame_right_mouse_state.take();
        if let Some(drag) = drag {
            if drag.motion.start.owner != self.local_owner {
                return Ok(());
            }
            if drag.motion.moved {
                // RightUp refreshes TargetRegion before evaluating an active
                // moving drag. A region cursor has no Drop/Throw/PushTo case,
                // so ButtonUpDragMoving emits only C4CMD_None and clears the
                // local Selection (C4MouseControl.cpp:267,1171-1201).
                if self
                    .ingame_viewport_region(drag.motion.last.screen)
                    .is_some()
                {
                    self.ingame_dragged_objects.clear();
                    return Ok(());
                }
                if drag.down_target.is_none() && !drag.down_region {
                    // C4MouseControl locks an unknown landscape frame to the
                    // first type found. Crew frames queue CID_PlrSelect and
                    // clear; object frames retain their local Selection for a
                    // subsequent moving drag (C4MouseControl.cpp:795-817,
                    // 909-968,1160-1169).
                    let first = ingame_pointer_world_pixel(drag.motion.start);
                    let second = ingame_pointer_world_pixel(drag.motion.last);
                    match drag.motion.selection_kind {
                        IngameDragSelectionKind::Crew => {
                            self.ingame_dragged_objects.clear();
                            let selected = self.engine.mouse_drag_crew_in_rect(
                                self.local_owner,
                                first,
                                second,
                            );
                            self.submit_or_execute_player_select(PlayerSelectControlData {
                                player: self.local_owner,
                                objects: selected
                                    .into_iter()
                                    .map(|object| object.as_u64() as i32)
                                    .collect(),
                                by_client: -1,
                            })?;
                            self.snapshot = self.engine.snapshot();
                            self.refresh_object_menu();
                            self.refresh_focus();
                        }
                        IngameDragSelectionKind::Objects => {
                            self.ingame_dragged_objects =
                                self.engine.mouse_drag_carryables_in_rect(first, second);
                        }
                        IngameDragSelectionKind::Unknown => {
                            self.ingame_dragged_objects.clear();
                        }
                    }
                    return Ok(());
                }
                if let Some(target) = drag.down_target {
                    let source = if drag.down_region {
                        self.engine.mouse_region_drag_source(target)
                    } else {
                        self.engine.mouse_world_drag_source(
                            self.local_owner,
                            target,
                            ingame_pointer_world_pixel(drag.motion.start),
                        )
                    };
                    let region_selection = drag
                        .down_region
                        .then(|| self.engine.mouse_region_drag_objects(target, true));
                    match source {
                        Some(MouseDragSource::Carryable) => {
                            return self.finish_ingame_carryable_drag(
                                drag,
                                target,
                                region_selection,
                            );
                        }
                        Some(MouseDragSource::Vehicle) => {
                            return self.finish_ingame_vehicle_drag(drag, target, region_selection);
                        }
                        None => {}
                    }
                }
            }
        }

        let Some(pointer) = self.ingame_pointer else {
            return Ok(());
        };
        if pointer.owner != self.local_owner {
            return Ok(());
        }
        // RightUpDragNone sends the copied DownRegion.RightCom whenever the
        // release cursor is a region. Inventory regions leave RightCom at
        // COM_None, so they consume the click without opening world context
        // or cycling crew (C4MouseControl.cpp:1230-1237).
        if self.ingame_viewport_region(pointer.screen).is_some() {
            return Ok(());
        }
        let primary_target =
            self.ingame_primary_mouse_target(self.local_owner, pointer.screen);
        let context_target = primary_target.or_else(|| {
            self.graphics
                .object_at_point(&self.snapshot, self.local_owner, pointer.screen)
        });
        if let Some(target) = context_target {
            if let Some(select_target) = primary_target
                .filter(|target| self.ingame_mouse_selectable_object(self.local_owner, *target))
            {
                self.submit_or_execute_player_select(PlayerSelectControlData {
                    player: self.local_owner,
                    objects: vec![select_target.as_u64() as i32],
                    by_client: -1,
                })?;
            }
            self.show_startup_hint = false;
            let add_mode = 2 | if self.keyboard_modifiers.shift() { 4 } else { 0 };
            let (x, y) = self
                .graphics
                .active_viewport_projections()
                .into_iter()
                .find(|viewport| viewport.owner == self.local_owner)
                .map(|viewport| ingame_pointer_viewport_pixel(pointer, viewport))
                .unwrap_or((pointer.world.x as i32, pointer.world.y as i32));
            self.submit_or_execute_player_command(PlayerCommandControlData {
                player: self.local_owner,
                command: CommandId::Context as i32,
                x,
                y,
                target: 0,
                target2: target.as_u64() as i32,
                data: 0,
                add_mode,
                by_client: -1,
            })?;
        } else {
            // C4MouseControl::RightUpDragNone cycles crew on a free click by
            // queuing a one-object CID_PlrSelect packet.
            if let Some(next) = self
                .engine
                .player_mouse_select_next_object(self.local_owner)
            {
                self.submit_or_execute_player_select(PlayerSelectControlData {
                    player: self.local_owner,
                    objects: vec![next.as_u64() as i32],
                    by_client: -1,
                })?;
            }
            self.snapshot = self.engine.snapshot();
            self.refresh_focus();
        }
        Ok(())
    }

    fn finish_ingame_carryable_drag(
        &mut self,
        drag: IngameRightMouseState,
        down_target: ObjectId,
        region_selection: Option<Vec<ObjectId>>,
    ) -> Result<(), EngineError> {
        let selected = if let Some(selected) = region_selection {
            self.ingame_dragged_objects.clear();
            selected
        } else if self.ingame_dragged_objects.contains(&down_target) {
            std::mem::take(&mut self.ingame_dragged_objects)
        } else {
            self.ingame_dragged_objects.clear();
            vec![down_target]
        };
        if drag.motion.last.owner != self.local_owner {
            return Ok(());
        }
        let position = ingame_pointer_world_pixel(drag.motion.last);
        let put_target = self
            .keyboard_modifiers
            .ctrl()
            .then(|| {
                self.graphics.object_at_point_with_ocf(
                    &self.snapshot,
                    self.local_owner,
                    drag.motion.last.screen,
                    lc_engine::ocf::CONTAINER,
                )
            })
            .flatten();
        let command = if put_target.is_none() {
            self.engine
                .mouse_drag_carryable_command(self.local_owner, position)
        } else {
            None
        };
        if put_target.is_none() && command.is_none() {
            return Ok(());
        }
        self.show_startup_hint = false;
        let mut add_mode = 1;
        let shift_append = self.keyboard_modifiers.shift();
        for object in selected {
            let (command, x, y, target, target2) = if let Some(container) = put_target {
                (
                    CommandId::Put,
                    0,
                    0,
                    container.as_u64() as i32,
                    object.as_u64() as i32,
                )
            } else if let Some(command) = command {
                (command, position.x, position.y, object.as_u64() as i32, 0)
            } else {
                continue;
            };
            self.submit_or_execute_player_command(PlayerCommandControlData {
                player: self.local_owner,
                command: command as i32,
                x,
                y,
                target,
                target2,
                data: 0,
                add_mode: add_mode | if shift_append { 4 } else { 0 },
                by_client: -1,
            })?;
            add_mode = 4;
        }
        self.snapshot = self.engine.snapshot();
        self.refresh_object_menu();
        self.refresh_focus();
        Ok(())
    }

    fn finish_ingame_vehicle_drag(
        &mut self,
        drag: IngameRightMouseState,
        down_target: ObjectId,
        region_selection: Option<Vec<ObjectId>>,
    ) -> Result<(), EngineError> {
        self.ingame_dragged_objects.clear();
        let selected = region_selection.unwrap_or_else(|| vec![down_target]);
        if drag.motion.last.owner != self.local_owner {
            return Ok(());
        }
        let position = ingame_pointer_world_pixel(drag.motion.last);
        let put_target = self
            .keyboard_modifiers
            .ctrl()
            .then(|| {
                self.graphics.object_at_point_with_ocf(
                    &self.snapshot,
                    self.local_owner,
                    drag.motion.last.screen,
                    lc_engine::ocf::CONTAINER,
                )
            })
            .flatten();
        self.show_startup_hint = false;
        let mut add_mode = 1;
        let shift_append = self.keyboard_modifiers.shift();
        for vehicle in selected {
            self.submit_or_execute_player_command(PlayerCommandControlData {
                player: self.local_owner,
                command: CommandId::PushTo as i32,
                x: position.x,
                y: position.y,
                target: vehicle.as_u64() as i32,
                target2: put_target.map_or(0, |target| target.as_u64() as i32),
                data: 0,
                add_mode: add_mode | if shift_append { 4 } else { 0 },
                by_client: -1,
            })?;
            add_mode = 4;
        }
        self.snapshot = self.engine.snapshot();
        self.refresh_object_menu();
        self.refresh_focus();
        Ok(())
    }

    fn script_menu_pointer_target(
        &self,
        point: GuiPoint,
    ) -> Result<Option<EngineScriptMenuPointerTarget>, EngineError> {
        if !self.mouse_control {
            return Ok(None);
        }
        let Some((target, menu)) = self.engine.cursor_object_menu(self.local_owner) else {
            return Ok(None);
        };
        self.assets
            .require_classic_ingame_menu_resources()
            .map_err(|error| classic_parity_engine_error(report_classic_parity_boundary(error)))?;
        let fallback = self.assets.font_arc();
        let font = lc_frontend::hud::HudFont::from_set(
            self.assets.clonk_fonts.as_deref(),
            fallback.as_ref(),
        );
        let area = self
            .graphics
            .viewport_rect(self.local_owner)
            .unwrap_or_else(|| {
                let surface = self.graphics.surface();
                Rect::new(0, 0, surface.width(), surface.height())
            });
        let resources = self.script_text_spec_resources();
        let font_images =
            resolve_script_menu_font_images(&self.engine, menu, resources).map_err(|error| {
                classic_parity_engine_error(report_classic_parity_boundary(
                    ClassicParityBoundary::ScriptMenuPointerResources {
                        detail: error.to_string(),
                    },
                ))
            })?;
        let free_location = self
            .script_menu_presentation
            .as_ref()
            .filter(|state| same_script_menu_presentation(state, target, menu))
            .and_then(|state| state.free_location)
            .or_else(|| self.script_menu_free_location(menu));
        Ok(engine_script_menu_pointer_target_with_info(
            area,
            &font,
            menu,
            self.display_flags.show_commands,
            true,
            point,
            &font_images,
            free_location,
        ))
    }

    fn script_menu_free_location(&self, menu: &lc_engine::ObjectMenuState) -> Option<(i32, i32)> {
        if menu.style != 2 || menu.user_menu {
            return None;
        }
        let target_id = menu.items.first()?.picture_object?;
        let target = self.snapshot.object(target_id)?;
        let shape = self.engine.object_current_shape_rect(target_id)?;
        let anchor = Vector2::new(
            target
                .position
                .x
                .saturating_add(shape.x)
                .saturating_add(shape.width)
                .saturating_add(10),
            target.position.y.saturating_add(shape.y),
        );
        self.graphics
            .world_to_screen(self.local_owner, anchor)
            .map(|(x, y)| (x.floor() as i32, y.floor() as i32))
    }

    fn select_script_menu_pointer_item(&mut self, index: usize) -> Result<bool, EngineError> {
        let Some((selection, selectable)) = self
            .engine
            .cursor_object_menu(self.local_owner)
            .and_then(|(_, menu)| {
                menu.items
                    .get(index)
                    .map(|item| (menu.selection, item.selectable))
            })
        else {
            return Ok(false);
        };
        if !selectable {
            return Ok(false);
        }
        if selection != index as i32 {
            let data = i32::try_from(index).unwrap_or(i32::MAX) | lc_engine::C4MN_ADJUST_POSITION;
            self.dispatch_control_event(ControlEvent::RawPlayerControl {
                command: lc_engine::COM_MENU_SELECT,
                data,
            })?;
        }
        Ok(true)
    }

    fn refresh_after_script_menu_pointer(&mut self) {
        self.snapshot = self.engine.snapshot();
        self.refresh_object_menu();
        self.refresh_focus();
    }

    fn on_ingame_mouse_down(&mut self) -> Result<(), EngineError> {
        if !self.mouse_control {
            self.mouse_state = None;
            return Ok(());
        }
        let Some(pointer) = self.ingame_pointer else {
            self.mouse_state = None;
            return Ok(());
        };
        let down_target =
            self.ingame_primary_mouse_target(pointer.owner, pointer.screen);
        self.mouse_state = Some(IngameMouseState::new(pointer, down_target.is_none()));
        Ok(())
    }

    fn on_ingame_mouse_up(&mut self) -> Result<(), EngineError> {
        let Some(state) = self.mouse_state.take() else {
            return Ok(());
        };
        if self.local_controls.mouse_owner() != Some(state.start.owner) {
            return Ok(());
        }
        if state.moved {
            if state.selection_frame
                && state.selection_kind == IngameDragSelectionKind::Crew
            {
                let selected = self.engine.mouse_drag_crew_in_rect(
                    state.start.owner,
                    ingame_pointer_world_pixel(state.start),
                    ingame_pointer_world_pixel(state.last),
                );
                self.submit_or_execute_player_select(PlayerSelectControlData {
                    player: state.start.owner,
                    objects: selected
                        .into_iter()
                        .map(|object| object.as_u64() as i32)
                        .collect(),
                    by_client: -1,
                })?;
                self.snapshot = self.engine.snapshot();
                self.refresh_object_menu();
                self.refresh_focus();
                return Ok(());
            }
            self.handle_mouse_drag(state)?;
        } else {
            self.handle_ingame_mouse_click(state.last)?;
        }
        Ok(())
    }

    fn handle_ingame_mouse_click(&mut self, pointer: ViewportPointer) -> Result<(), EngineError> {
        if !matches!(self.mode, AppMode::Running)
            || !self.mouse_control
            || self.local_controls.mouse_owner() != Some(pointer.owner)
        {
            return Ok(());
        }
        // C4MC_Cursor_Select queues CID_PlrSelect on LeftUp for both crew and
        // C4D_MouseSelect objects (C4MouseControl.cpp:1106-1129).
        if let Some(target) =
            self.ingame_mouse_select_target(pointer.owner, pointer.screen)
        {
            self.submit_or_execute_player_select(PlayerSelectControlData {
                player: pointer.owner,
                objects: vec![target.as_u64() as i32],
                by_client: -1,
            })?;
            self.snapshot = self.engine.snapshot();
            self.refresh_object_menu();
            self.refresh_focus();
            return Ok(());
        }
        self.show_startup_hint = false;
        self.submit_or_execute_player_command(PlayerCommandControlData {
            player: pointer.owner,
            command: CommandId::MoveTo as i32,
            x: pointer.world.x as i32,
            y: pointer.world.y as i32,
            target: 0,
            target2: 0,
            data: 0,
            add_mode: 1,
            by_client: -1,
        })?;
        Ok(())
    }

    fn on_ingame_mouse_double(&mut self) -> Result<(), EngineError> {
        if !matches!(self.mode, AppMode::Running) || !self.mouse_control {
            return Ok(());
        }
        let Some(pointer) = self.ingame_pointer else {
            return Ok(());
        };
        if pointer.owner != self.local_owner {
            return Ok(());
        }
        let Some(target) =
            self.graphics
                .object_at_point(&self.snapshot, self.local_owner, pointer.screen)
        else {
            return Ok(());
        };
        if self
            .snapshot
            .object(target)
            .is_none_or(|object| object.ocf & lc_engine::ocf::CARRYABLE == 0)
        {
            return Ok(());
        }

        self.show_startup_hint = false;
        self.submit_or_execute_player_command(PlayerCommandControlData {
            player: self.local_owner,
            command: CommandId::Get as i32,
            x: 0,
            y: 0,
            target: target.as_u64() as i32,
            target2: 0,
            data: 0,
            add_mode: 1,
            by_client: -1,
        })?;
        Ok(())
    }

    fn handle_mouse_drag(&mut self, state: IngameMouseState) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        if !matches!(self.mode, AppMode::Running) {
            return Ok(());
        }
        // Mouse control disabled from the Options menu
        // (C4Player::ToggleMouseControl analogue, C4MainMenu.cpp:847-849).
        if !self.mouse_control {
            return Ok(());
        }
        let Some(selection) = self.snapshot.crew_selection.get(&self.local_owner) else {
            return Ok(());
        };
        if selection.selected.is_empty() && selection.cursor.is_none() {
            return Ok(());
        }
        let crew_id = selection
            .cursor
            .or_else(|| selection.selected.first().copied());
        let Some(crew_id) = crew_id else {
            return Ok(());
        };
        let Some(crew) = self.snapshot.object(crew_id) else {
            return Ok(());
        };
        if crew.contents.is_empty() {
            return Ok(());
        }

        let delta = state.delta();
        let buttons = drag_direction_buttons(delta);
        if buttons.is_empty() {
            return Ok(());
        }

        for button in &buttons {
            self.dispatch_control_event(ControlEvent::Press(*button))?;
        }
        self.dispatch_control_event(ControlEvent::Command {
            command: ControlCommand::Throw,
            kind: CommandKind::Press,
        })?;
        self.dispatch_control_event(ControlEvent::Command {
            command: ControlCommand::Throw,
            kind: CommandKind::Release,
        })?;
        for button in buttons.into_iter().rev() {
            self.dispatch_control_event(ControlEvent::Release(button))?;
        }

        self.snapshot = self.engine.snapshot();
        self.refresh_object_menu();
        self.refresh_focus();
        Ok(())
    }

    fn handle_mouse_button(&mut self, button_state: ElementState) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.mark_menu_dirty();
        if self.startup_network_transition_active() {
            return Ok(());
        }
        if button_state == ElementState::Pressed {
            self.context_menu_pointer_capture = None;
            // A fresh gesture supersedes any stale modal capture. Only the
            // topmost selector itself may acquire this latch.
            self.definition_selector_pointer_capture =
                self.definition_selector.is_some() && self.message_dialogs.is_empty();
            self.game_option_input_pointer_capture = (self.game_option_input_dialog.is_some()
                && self.context_menu.is_none()
                && self.message_dialogs.is_empty())
            .then_some(ContextMenuPointerButton::Left);
        }
        let definition_selector_release_latched = button_state == ElementState::Released
            && std::mem::take(&mut self.definition_selector_pointer_capture);
        let input_dialog_release_latched = button_state == ElementState::Released
            && self.game_option_input_pointer_capture == Some(ContextMenuPointerButton::Left);
        if input_dialog_release_latched {
            self.game_option_input_pointer_capture = None;
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::MainMenu {
            self.main_menu_state.note_pointer_button();
        }
        if self.consume_closed_context_pointer_release(button_state, ContextMenuPointerButton::Left)
        {
            return Ok(());
        }
        if self.handle_message_dialog_pointer_button(button_state)? {
            return Ok(());
        }
        if self.definition_selector.is_some() {
            let layout = self.definition_selector_layout();
            let point = self
                .definition_selector
                .as_ref()
                .and_then(|controller| controller.pointer_position());
            let clicked_label_row = layout.as_ref().zip(point).and_then(|(layout, point)| {
                self.definition_selector.as_ref().and_then(|controller| {
                    definition_selector_label_row_at(controller, layout, point)
                })
            });
            let mut actions = layout
                .as_ref()
                .zip(point)
                .and_then(|(layout, point)| {
                    self.definition_selector
                        .as_mut()
                        .map(|controller| match button_state {
                            ElementState::Pressed => controller.handle_pointer_down(point, layout),
                            ElementState::Released => controller.handle_pointer_up(point, layout),
                        })
                })
                .unwrap_or_default();
            if button_state == ElementState::Released {
                if let (Some(index), Some(layout), Some(point)) =
                    (clicked_label_row, layout.as_ref(), point)
                {
                    let now = Instant::now();
                    let is_double =
                        self.definition_selector_last_click
                            .is_some_and(|(last_index, at)| {
                                last_index == index
                                    && now.duration_since(at) < Duration::from_millis(500)
                            });
                    self.definition_selector_last_click =
                        if is_double { None } else { Some((index, now)) };
                    if is_double {
                        actions.extend(
                            self.definition_selector
                                .as_mut()
                                .map(|controller| {
                                    controller.handle_pointer_double_click(point, layout)
                                })
                                .unwrap_or_default(),
                        );
                    }
                } else {
                    self.definition_selector_last_click = None;
                }
            }
            self.finish_definition_selector_input(actions)?;
            return Ok(());
        }
        if definition_selector_release_latched {
            return Ok(());
        }
        if self.handle_context_menu_pointer_button(button_state, ContextMenuPointerButton::Left)? {
            return Ok(());
        }
        if self.game_option_input_dialog.is_some() {
            let point = self.game_option_input_pointer_position;
            let layout = self.game_option_input_layout();
            let fonts = self.assets.clonk_fonts.clone();
            let clicked_edit = point.zip(layout.as_ref()).is_some_and(|(point, layout)| {
                let edit = layout.edit;
                point.x >= edit.x as f32
                    && point.x < (edit.x + edit.w) as f32
                    && point.y >= edit.y as f32
                    && point.y < (edit.y + edit.h) as f32
            });
            let actions = point
                .zip(layout.as_ref())
                .zip(fonts.as_deref())
                .and_then(|((point, layout), fonts)| {
                    self.game_option_input_dialog
                        .as_mut()
                        .map(|dialog| match button_state {
                            ElementState::Pressed => {
                                dialog
                                    .controller
                                    .handle_pointer_down(point, layout, &fonts.text)
                            }
                            ElementState::Released => {
                                dialog.controller.handle_pointer_up(point, layout)
                            }
                        })
                })
                .unwrap_or_default();
            self.finish_game_option_input_dialog_actions(actions)?;
            if button_state == ElementState::Released
                && clicked_edit
                && self.game_option_input_dialog.is_some()
            {
                let now = Instant::now();
                let is_double = self
                    .game_option_input_last_click
                    .is_some_and(|last| now.duration_since(last) < Duration::from_millis(500));
                self.game_option_input_last_click = (!is_double).then_some(now);
                if is_double {
                    let actions = point
                        .zip(layout.as_ref())
                        .zip(fonts.as_deref())
                        .and_then(|((point, layout), fonts)| {
                            self.game_option_input_dialog.as_mut().map(|dialog| {
                                dialog.controller.handle_pointer_double_click(
                                    point,
                                    layout,
                                    &fonts.text,
                                )
                            })
                        })
                        .unwrap_or_default();
                    self.finish_game_option_input_dialog_actions(actions)?;
                }
            }
            return Ok(());
        }
        if input_dialog_release_latched {
            return Ok(());
        }
        if self.game_over_dialog.is_some() {
            let (width, height) = {
                let surface = self.graphics.surface();
                (surface.width(), surface.height())
            };
            let action = self
                .game_over_dialog
                .as_mut()
                .and_then(|dialog| match button_state {
                    ElementState::Pressed => {
                        dialog.handle_pointer_down(width, height);
                        None
                    }
                    ElementState::Released => dialog.handle_pointer_up(width, height),
                });
            if let Some(action) = action {
                self.handle_game_over_action(action)?;
            }
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            return self.handle_classic_lobby_pointer_button(button_state);
        }
        match self.mode {
            AppMode::Menu => {
                if self.game_over_dialog.is_some() {
                    if button_state == ElementState::Released {
                        self.dismiss_game_over_dialog();
                    }
                    return Ok(());
                }
                match self.startup_view {
                    StartupView::NetworkGame => {
                        let actions = self
                            .startup_network_dialog
                            .as_mut()
                            .and_then(|dialog| {
                                dialog.pointer_position().map(|point| match button_state {
                                    ElementState::Pressed => dialog.handle_pointer_down(point),
                                    ElementState::Released => dialog.handle_pointer_up(point),
                                })
                            })
                            .unwrap_or_default();
                        self.process_network_dialog_actions(actions)
                    }
                    StartupView::PlayerSelection => {
                        let point = self
                            .startup_player_dialog
                            .as_ref()
                            .and_then(|dialog| dialog.pointer_position());
                        let clicked_row = point.and_then(|point| {
                            let layout = lc_frontend::startup_plrsel::plrsel_layout(
                                self.graphics.surface().width() as i32,
                                self.graphics.surface().height() as i32,
                            );
                            let offset = point.y as i32 - layout.list_client.y;
                            let in_name_column = point.x
                                >= (layout.list_client.x + layout.item_height) as f32
                                && point.x < (layout.list_client.x + layout.item_width) as f32;
                            (in_name_column
                                && offset >= 0
                                && offset % layout.item_pitch < layout.item_height)
                                .then_some((offset / layout.item_pitch) as usize)
                                .filter(|index| *index < self.startup_player_models.len())
                        });
                        let is_double = if button_state == ElementState::Released {
                            let now = Instant::now();
                            let is_double = clicked_row.is_some_and(|index| {
                                self.plrsel_last_click.is_some_and(|(last_index, at)| {
                                    last_index == index
                                        && now.duration_since(at) < Duration::from_millis(500)
                                })
                            });
                            self.plrsel_last_click = clicked_row.map(|index| (index, now));
                            is_double
                        } else {
                            false
                        };
                        let mut actions = self
                            .startup_player_dialog
                            .as_mut()
                            .and_then(|dialog| {
                                point.map(|point| match button_state {
                                    ElementState::Pressed => dialog.handle_pointer_down(point),
                                    ElementState::Released => dialog.handle_pointer_up(point),
                                })
                            })
                            .unwrap_or_default();
                        if is_double {
                            actions.extend(
                                self.startup_player_dialog
                                    .as_mut()
                                    .and_then(|dialog| {
                                        point.map(|point| dialog.handle_pointer_double_click(point))
                                    })
                                    .unwrap_or_default(),
                            );
                            self.plrsel_last_click = None;
                        }
                        self.process_player_dialog_actions(actions)
                    }
                    StartupView::ScenarioBrowser => {
                        if button_state == ElementState::Released
                            && self.game_option_pointer_capture
                            && self.menu_state.pointer_position().is_none()
                        {
                            self.game_option_pointer_capture = false;
                            self.scenario_game_options.cancel_interaction();
                            return Ok(());
                        }
                        if let Some(point) = self.menu_state.pointer_position() {
                            self.scenario_game_options.handle_pointer_move(point);
                            match button_state {
                                ElementState::Pressed => {
                                    self.game_option_pointer_capture = self
                                        .scenario_game_options
                                        .hovered_button()
                                        .and_then(|button| self.scenario_game_options.view(button))
                                        .is_some_and(|view| view.enabled);
                                    if self.game_option_pointer_capture {
                                        self.scenario_game_options.set_focused_button(
                                            self.scenario_game_options.hovered_button(),
                                        );
                                        let actions =
                                            self.scenario_game_options.handle_pointer_down(point);
                                        self.menu_state
                                            .set_dialog_focus(ScenselDialogFocus::Options);
                                        self.finish_game_option_input(actions)?;
                                        return Ok(());
                                    }
                                }
                                ElementState::Released if self.game_option_pointer_capture => {
                                    self.game_option_pointer_capture = false;
                                    let actions =
                                        self.scenario_game_options.handle_pointer_up(point);
                                    self.finish_game_option_input(actions)?;
                                    return Ok(());
                                }
                                ElementState::Released => {}
                            }
                            match button_state {
                                ElementState::Pressed => {
                                    if !self.handle_scensel_search_pointer_down(point) {
                                        self.handle_scensel_scrollbar_down(point);
                                    }
                                }
                                ElementState::Released => {
                                    if !self.handle_scensel_search_pointer_up(point)
                                        && !self.handle_scensel_scrollbar_up(point)
                                    {
                                        self.handle_scensel_parity_click(point)?;
                                    }
                                }
                            }
                        }
                        Ok(())
                    }
                    StartupView::MainMenu => {
                        if let Some(point) = self.main_menu_state.pointer_position() {
                            let actions = match button_state {
                                ElementState::Pressed => {
                                    self.main_menu_state.handle_pointer_down(point)
                                }
                                ElementState::Released => {
                                    self.main_menu_state.handle_pointer_up(point)
                                }
                            };
                            self.process_main_menu_actions(actions)?;
                        }
                        Ok(())
                    }
                    StartupView::NetworkLobby => {
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            let width = self.graphics.surface().width() as f32;
                            let height = self.graphics.surface().height() as f32;
                            lobby.update_layout(width, height);

                            match button_state {
                                ElementState::Pressed => {
                                    if let Some(point) = lobby.pointer_position() {
                                        if matches!(
                                            lobby.pointer_region(point),
                                            LobbyPointerRegion::Panel
                                        ) {
                                            lobby.handle_panel_pointer_down(point);
                                            return Ok(());
                                        }
                                    }
                                    if let Some(point) = self.menu_state.pointer_position() {
                                        self.handle_menu_input(|state| {
                                            state.menu().handle_pointer_down(point)
                                        })?;
                                    }
                                    Ok(())
                                }
                                ElementState::Released => {
                                    if let Some(point) = lobby.pointer_position() {
                                        if matches!(
                                            lobby.pointer_region(point),
                                            LobbyPointerRegion::Panel
                                        ) {
                                            if let Some(action) =
                                                lobby.handle_panel_pointer_up(point)
                                            {
                                                self.process_lobby_action(action)?;
                                            }
                                            return Ok(());
                                        }
                                    }
                                    if let Some(point) = self.menu_state.pointer_position() {
                                        self.handle_menu_input(|state| {
                                            state.menu().handle_pointer_up(point)
                                        })?;
                                    }
                                    Ok(())
                                }
                            }
                        } else {
                            Ok(())
                        }
                    }
                    StartupView::Options => {
                        let actions = self
                            .startup_options_dialog
                            .as_mut()
                            .and_then(|dialog| {
                                dialog.pointer_position().map(|point| match button_state {
                                    ElementState::Pressed => dialog.handle_pointer_down(point),
                                    ElementState::Released => dialog.handle_pointer_up(point),
                                })
                            })
                            .unwrap_or_default();
                        self.process_options_dialog_actions(actions)?;
                        Ok(())
                    }
                    StartupView::About => {
                        let actions = self
                            .startup_about_dialog
                            .as_mut()
                            .and_then(|dialog| {
                                dialog.pointer_position().map(|point| match button_state {
                                    ElementState::Pressed => dialog.handle_pointer_down(point),
                                    ElementState::Released => dialog.handle_pointer_up(point),
                                })
                            })
                            .unwrap_or_default();
                        self.process_about_dialog_actions(actions)
                    }
                }
            }
            AppMode::Running => {
                if self.handle_scoreboard_pointer_button(button_state)?
                    || self.handle_ingame_menu_pointer_button(button_state, false)?
                {
                    Ok(())
                } else {
                    self.handle_ingame_mouse_button(button_state)
                }
            }
            AppMode::Loading => Ok(()),
        }
    }

    fn handle_touch(&mut self, phase: TouchPhase, position: GuiPoint) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        if self.startup_network_transition_active() {
            return Ok(());
        }
        if phase == TouchPhase::Started {
            self.definition_selector_pointer_capture =
                self.definition_selector.is_some() && self.message_dialogs.is_empty();
            self.game_option_input_pointer_capture = (self.game_option_input_dialog.is_some()
                && self.context_menu.is_none()
                && self.message_dialogs.is_empty())
            .then_some(ContextMenuPointerButton::Left);
            self.game_option_pointer_capture = false;
        }
        let definition_selector_release_latched =
            matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled)
                && std::mem::take(&mut self.definition_selector_pointer_capture);
        if phase == TouchPhase::Ended
            && self.consume_closed_context_pointer_release(
                ElementState::Released,
                ContextMenuPointerButton::Left,
            )
        {
            self.mark_menu_dirty();
            return Ok(());
        }
        if phase == TouchPhase::Cancelled {
            self.context_menu_pointer_capture = None;
        }
        if !self.message_dialogs.is_empty() {
            self.mark_menu_dirty();
            if !matches!(phase, TouchPhase::Cancelled) {
                self.handle_message_dialog_pointer_move(position);
            }
            match phase {
                TouchPhase::Started => {
                    self.handle_message_dialog_pointer_button(ElementState::Pressed)?;
                }
                TouchPhase::Ended => {
                    self.handle_message_dialog_pointer_button(ElementState::Released)?;
                }
                TouchPhase::Cancelled => {
                    if let Some(dialog) = self.message_dialogs.last_mut() {
                        dialog.state.cancel_interaction();
                    }
                }
                TouchPhase::Moved => {}
            }
            return Ok(());
        }
        if self.definition_selector.is_some() {
            self.mark_menu_dirty();
            let layout = self.definition_selector_layout();
            let clicked_label_row = layout.as_ref().and_then(|layout| {
                self.definition_selector.as_ref().and_then(|controller| {
                    definition_selector_label_row_at(controller, layout, position)
                })
            });
            let mut actions = layout
                .as_ref()
                .and_then(|layout| {
                    self.definition_selector
                        .as_mut()
                        .map(|controller| match phase {
                            TouchPhase::Started => controller.handle_touch_start(position, layout),
                            TouchPhase::Moved => controller.handle_touch_move(position, layout),
                            TouchPhase::Ended => controller.handle_touch_end(position, layout),
                            TouchPhase::Cancelled => {
                                controller.handle_touch_cancel();
                                Vec::new()
                            }
                        })
                })
                .unwrap_or_default();
            if phase == TouchPhase::Ended {
                if let (Some(index), Some(layout)) = (clicked_label_row, layout.as_ref()) {
                    let now = Instant::now();
                    let is_double =
                        self.definition_selector_last_click
                            .is_some_and(|(last_index, at)| {
                                last_index == index
                                    && now.duration_since(at) < Duration::from_millis(500)
                            });
                    self.definition_selector_last_click =
                        if is_double { None } else { Some((index, now)) };
                    if is_double {
                        actions.extend(
                            self.definition_selector
                                .as_mut()
                                .map(|controller| {
                                    controller.handle_pointer_double_click(position, layout)
                                })
                                .unwrap_or_default(),
                        );
                    }
                } else {
                    self.definition_selector_last_click = None;
                }
            } else if phase == TouchPhase::Cancelled {
                self.definition_selector_last_click = None;
            }
            self.finish_definition_selector_input(actions)?;
            return Ok(());
        }
        if definition_selector_release_latched {
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.context_menu.is_some() {
            self.mark_menu_dirty();
            if phase == TouchPhase::Cancelled {
                self.close_context_menu_silently();
            } else {
                let move_captured = self.handle_context_menu_pointer_move(position)?;
                let button_captured = match phase {
                    TouchPhase::Started => self.handle_context_menu_pointer_button(
                        ElementState::Pressed,
                        ContextMenuPointerButton::Left,
                    )?,
                    TouchPhase::Ended => self.handle_context_menu_pointer_button(
                        ElementState::Released,
                        ContextMenuPointerButton::Left,
                    )?,
                    TouchPhase::Moved => false,
                    TouchPhase::Cancelled => unreachable!(),
                };
                if move_captured || button_captured {
                    return Ok(());
                }
            }
        }
        if self.game_option_input_dialog.is_some() {
            self.game_option_input_pointer_position = Some(position);
            let layout = self.game_option_input_layout();
            let fonts = self.assets.clonk_fonts.clone();
            let actions = layout
                .as_ref()
                .zip(fonts.as_deref())
                .and_then(|(layout, fonts)| {
                    self.game_option_input_dialog
                        .as_mut()
                        .map(|dialog| match phase {
                            TouchPhase::Started => {
                                dialog
                                    .controller
                                    .handle_touch_start(position, layout, &fonts.text)
                            }
                            TouchPhase::Moved => {
                                dialog
                                    .controller
                                    .handle_touch_move(position, layout, &fonts.text)
                            }
                            TouchPhase::Ended => {
                                dialog.controller.handle_touch_end(position, layout)
                            }
                            TouchPhase::Cancelled => {
                                dialog.controller.handle_touch_cancel();
                                Vec::new()
                            }
                        })
                })
                .unwrap_or_default();
            self.finish_game_option_input_dialog_actions(actions)?;
            if matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                self.game_option_input_pointer_capture = None;
                self.game_option_input_pointer_position = None;
            }
            return Ok(());
        }
        let input_dialog_release_latched =
            matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled)
                && self.game_option_input_pointer_capture == Some(ContextMenuPointerButton::Left);
        if input_dialog_release_latched {
            self.game_option_input_pointer_capture = None;
            return Ok(());
        }
        if self.game_over_dialog.is_some() {
            let (width, height) = {
                let surface = self.graphics.surface();
                (surface.width(), surface.height())
            };
            if !matches!(phase, TouchPhase::Cancelled) {
                if let Some(dialog) = self.game_over_dialog.as_mut() {
                    dialog.handle_pointer_move(position.x, position.y, width, height);
                }
            }
            if phase == TouchPhase::Started {
                if let Some(dialog) = self.game_over_dialog.as_mut() {
                    dialog.handle_pointer_down(width, height);
                }
            } else if phase == TouchPhase::Ended {
                let action = self
                    .game_over_dialog
                    .as_mut()
                    .and_then(|dialog| dialog.handle_pointer_up(width, height));
                if let Some(action) = action {
                    self.handle_game_over_action(action)?;
                }
            } else if phase == TouchPhase::Cancelled {
                self.pointer_left_unchecked();
            }
            return Ok(());
        }
        if self.mode == AppMode::Running {
            self.mark_menu_dirty();
            self.running_pointer_position = Some(position);
            match phase {
                TouchPhase::Started => {
                    let _ = self.handle_scoreboard_pointer_button(ElementState::Pressed)?;
                }
                TouchPhase::Ended => {
                    let _ = self.handle_scoreboard_pointer_button(ElementState::Released)?;
                    self.pointer_left_unchecked();
                }
                TouchPhase::Cancelled => self.pointer_left_unchecked(),
                TouchPhase::Moved => {}
            }
            return Ok(());
        }
        if self.mode != AppMode::Menu {
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            self.mark_menu_dirty();
            return self.handle_classic_lobby_touch(phase, position);
        }
        self.mark_menu_dirty();
        if self.game_over_dialog.is_some() {
            if matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                self.dismiss_game_over_dialog();
            }
            return Ok(());
        }
        match self.startup_view {
            StartupView::NetworkGame => {
                let actions = self
                    .startup_network_dialog
                    .as_mut()
                    .map(|dialog| match phase {
                        TouchPhase::Started => dialog.handle_pointer_down(position),
                        TouchPhase::Moved => dialog.handle_pointer_move(position),
                        TouchPhase::Ended => dialog.handle_pointer_up(position),
                        TouchPhase::Cancelled => Vec::new(),
                    })
                    .unwrap_or_default();
                self.process_network_dialog_actions(actions)?;
                if matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                    self.pointer_left_unchecked();
                }
                Ok(())
            }
            StartupView::PlayerSelection => {
                let actions = self
                    .startup_player_dialog
                    .as_mut()
                    .map(|dialog| match phase {
                        TouchPhase::Started => dialog.handle_pointer_down(position),
                        TouchPhase::Moved => dialog.handle_pointer_move(position),
                        TouchPhase::Ended => dialog.handle_pointer_up(position),
                        TouchPhase::Cancelled => Vec::new(),
                    })
                    .unwrap_or_default();
                self.process_player_dialog_actions(actions)?;
                if matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                    self.pointer_left_unchecked();
                }
                Ok(())
            }
            StartupView::ScenarioBrowser => {
                self.menu_state.set_pointer_position(Some(position));
                self.scenario_game_options.handle_pointer_move(position);
                if phase == TouchPhase::Started {
                    self.game_option_pointer_capture = self
                        .scenario_game_options
                        .hovered_button()
                        .and_then(|button| self.scenario_game_options.view(button))
                        .is_some_and(|view| view.enabled);
                }
                if self.game_option_pointer_capture {
                    let actions = match phase {
                        TouchPhase::Started => {
                            self.scenario_game_options
                                .set_focused_button(self.scenario_game_options.hovered_button());
                            self.menu_state
                                .set_dialog_focus(ScenselDialogFocus::Options);
                            self.scenario_game_options.handle_touch_start(position)
                        }
                        TouchPhase::Moved => self.scenario_game_options.handle_touch_move(position),
                        TouchPhase::Ended => self.scenario_game_options.handle_touch_end(position),
                        TouchPhase::Cancelled => {
                            self.scenario_game_options.handle_touch_cancel();
                            Vec::new()
                        }
                    };
                    self.finish_game_option_input(actions)?;
                    if matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                        self.game_option_pointer_capture = false;
                        self.pointer_left_unchecked();
                    }
                    return Ok(());
                }
                match phase {
                    TouchPhase::Started => {
                        if !self.handle_scensel_search_pointer_down(position) {
                            self.handle_scensel_scrollbar_down(position);
                        }
                        Ok(())
                    }
                    TouchPhase::Moved => {
                        let _ = self.handle_scensel_search_pointer_move(position)
                            || self.handle_scensel_scrollbar_move(position);
                        Ok(())
                    }
                    TouchPhase::Ended => {
                        if !self.handle_scensel_search_pointer_up(position)
                            && !self.handle_scensel_scrollbar_up(position)
                        {
                            self.handle_scensel_parity_click(position)?;
                        }
                        self.pointer_left_unchecked();
                        Ok(())
                    }
                    TouchPhase::Cancelled => {
                        self.menu_state.search_edit.dragging = false;
                        self.menu_state.scrollbar_interaction = None;
                        self.pointer_left_unchecked();
                        Ok(())
                    }
                }
            }
            StartupView::MainMenu => {
                self.main_menu_state.set_pointer_position(Some(position));
                let actions = match phase {
                    TouchPhase::Started => self.main_menu_state.handle_pointer_down(position),
                    TouchPhase::Moved => self.main_menu_state.handle_pointer_move(position),
                    TouchPhase::Ended => {
                        let actions = self.main_menu_state.handle_pointer_up(position);
                        self.pointer_left_unchecked();
                        actions
                    }
                    TouchPhase::Cancelled => {
                        self.pointer_left_unchecked();
                        Vec::new()
                    }
                };
                self.process_main_menu_actions(actions)
            }
            StartupView::NetworkLobby => {
                if let Some(lobby) = self.network_lobby.as_mut() {
                    let width = self.graphics.surface().width() as f32;
                    let height = self.graphics.surface().height() as f32;
                    lobby.update_layout(width, height);
                    match phase {
                        TouchPhase::Started => match lobby.pointer_region(position) {
                            LobbyPointerRegion::Menu => self.handle_menu_input(|state| {
                                state.set_pointer_position(Some(position));
                                state.menu().handle_pointer_down(position)
                            }),
                            LobbyPointerRegion::Panel => {
                                lobby.handle_panel_pointer_move(position);
                                lobby.handle_panel_pointer_down(position);
                                self.menu_state.set_pointer_position(None);
                                Ok(())
                            }
                        },
                        TouchPhase::Moved => match lobby.pointer_region(position) {
                            LobbyPointerRegion::Menu => self.handle_menu_input(|state| {
                                state.set_pointer_position(Some(position));
                                state.menu().handle_pointer_move(position)
                            }),
                            LobbyPointerRegion::Panel => {
                                lobby.handle_panel_pointer_move(position);
                                self.menu_state.set_pointer_position(None);
                                Ok(())
                            }
                        },
                        TouchPhase::Ended => match lobby.pointer_region(position) {
                            LobbyPointerRegion::Menu => {
                                let result = self.handle_menu_input(|state| {
                                    state.set_pointer_position(Some(position));
                                    state.menu().handle_pointer_up(position)
                                });
                                self.pointer_left_unchecked();
                                result
                            }
                            LobbyPointerRegion::Panel => {
                                lobby.handle_panel_pointer_move(position);
                                if let Some(action) = lobby.handle_panel_pointer_up(position) {
                                    self.process_lobby_action(action)?;
                                }
                                self.pointer_left_unchecked();
                                Ok(())
                            }
                        },
                        TouchPhase::Cancelled => {
                            self.pointer_left_unchecked();
                            Ok(())
                        }
                    }
                } else {
                    Ok(())
                }
            }
            StartupView::Options => {
                let actions = self
                    .startup_options_dialog
                    .as_mut()
                    .map(|dialog| match phase {
                        TouchPhase::Started => dialog.handle_pointer_down(position),
                        TouchPhase::Moved => dialog.handle_pointer_move(position),
                        TouchPhase::Ended => dialog.handle_pointer_up(position),
                        TouchPhase::Cancelled => Vec::new(),
                    })
                    .unwrap_or_default();
                self.process_options_dialog_actions(actions)?;
                if matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                    self.pointer_left_unchecked();
                }
                Ok(())
            }
            StartupView::About => {
                let actions = self
                    .startup_about_dialog
                    .as_mut()
                    .map(|dialog| match phase {
                        TouchPhase::Started => dialog.handle_pointer_down(position),
                        TouchPhase::Moved => dialog.handle_pointer_move(position),
                        TouchPhase::Ended => dialog.handle_pointer_up(position),
                        TouchPhase::Cancelled => Vec::new(),
                    })
                    .unwrap_or_default();
                self.process_about_dialog_actions(actions)?;
                if matches!(phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                    self.pointer_left_unchecked();
                }
                Ok(())
            }
        }
    }

    fn pointer_left(&mut self) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.pointer_left_unchecked();
        Ok(())
    }

    fn pointer_left_unchecked(&mut self) {
        self.mark_menu_dirty();
        // CursorLeft may be the only lifecycle event after an activation
        // closed the menu on down. An open popup, however, must retain its
        // capture so a later outside up cannot leak to the underlying screen.
        if self.context_menu.is_none() {
            self.context_menu_pointer_capture = None;
        }
        if let Some(dialog) = self.message_dialogs.last_mut() {
            dialog.state.pointer_left();
            let sounds = dialog.state.take_sound_events();
            self.play_message_dialog_sound_events(sounds);
            return;
        }
        if self.definition_selector.is_some() {
            if let Some(layout) = self.definition_selector_layout() {
                if let Some(controller) = self.definition_selector.as_mut() {
                    controller.pointer_left(&layout);
                }
            }
            let sounds = self
                .definition_selector
                .as_mut()
                .map(|controller| controller.take_sound_events())
                .unwrap_or_default();
            self.play_definition_selector_sound_events(sounds);
            return;
        }
        if let Some(menu) = self.context_menu.as_mut() {
            let _ = menu.handle_pointer_left();
        }
        if let Some(dialog) = self.game_option_input_dialog.as_mut() {
            dialog.controller.pointer_left();
            let sounds = dialog.controller.take_sound_events();
            self.play_input_dialog_sound_events(sounds);
            self.game_option_input_pointer_position = None;
            return;
        }
        if let Some(dialog) = self.game_over_dialog.as_mut() {
            dialog.pointer_left();
            return;
        }
        match self.mode {
            AppMode::Menu => match self.startup_view {
                StartupView::NetworkGame => {
                    if let Some(dialog) = self.startup_network_dialog.as_mut() {
                        dialog.pointer_left();
                    }
                }
                StartupView::PlayerSelection => {
                    if let Some(dialog) = self.startup_player_dialog.as_mut() {
                        dialog.pointer_left();
                    }
                }
                StartupView::ScenarioBrowser => {
                    self.scenario_game_options.pointer_left();
                    let sounds = self.scenario_game_options.take_sound_events();
                    self.play_game_option_sound_events(sounds);
                    self.menu_state.set_pointer_position(None);
                    self.menu_state.scrollbar_interaction = None;
                    self.menu_state.search_edit.dragging = false;
                    self.scensel_search_last_click = None;
                }
                StartupView::MainMenu => {
                    self.main_menu_state.pointer_left();
                }
                StartupView::NetworkLobby => {
                    if !self.classic_host_lobby_pointer_left() {
                        self.menu_state.set_pointer_position(None);
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            lobby.pointer_left();
                        }
                    }
                }
                StartupView::Options => {
                    let sounds = self
                        .startup_options_dialog
                        .as_mut()
                        .map(|dialog| dialog.handle_pointer_left())
                        .unwrap_or_default()
                        .into_iter()
                        .filter_map(|action| match action {
                            lc_frontend::startup_options_dlg::OptionsDlgAction::Sound(
                                lc_frontend::startup_options_dlg::SoundSheetAction::GuiSound(
                                    sound,
                                ),
                            ) => Some(sound),
                            unexpected => {
                                tracing::error!(
                                    ?unexpected,
                                    "unexpected mutating action while cancelling Options pointer capture"
                                );
                                None
                            }
                        })
                        .collect::<Vec<_>>();
                    for sound in sounds {
                        self.play_options_sound(sound);
                    }
                }
                StartupView::About => {
                    if let Some(dialog) = self.startup_about_dialog.as_mut() {
                        dialog.pointer_left();
                    }
                }
            },
            AppMode::Running => {
                if let Some(state) = self.mouse_state.as_mut() {
                    state.moved = true;
                }
                if let Some(state) = self.ingame_right_mouse_state.as_mut() {
                    state.motion.moved = true;
                }
                self.ingame_gui_pointer = None;
                self.ingame_pointer = None;
                self.running_pointer_position = None;
                self.scoreboard_close_pointer_capture = false;
            }
            AppMode::Loading => {}
        }
    }

    fn cancel_underlying_interaction(&mut self) {
        self.pointer_left_unchecked();
        if self.game_over_dialog.is_some() {
            return;
        }
        if let Some(dialog) = self.game_option_input_dialog.as_mut() {
            dialog.controller.cancel_interaction();
            return;
        }
        if let Some(controller) = self.definition_selector.as_mut() {
            controller.cancel_interaction();
            return;
        }
        if matches!(self.mode, AppMode::Menu) {
            match self.startup_view {
                StartupView::NetworkGame => {
                    if let Some(dialog) = self.startup_network_dialog.as_mut() {
                        dialog.cancel_interaction();
                    }
                }
                StartupView::PlayerSelection => {
                    if let Some(dialog) = self.startup_player_dialog.as_mut() {
                        dialog.cancel_interaction();
                    }
                }
                StartupView::ScenarioBrowser => {
                    self.scenario_game_options.cancel_interaction();
                    self.menu_state.menu().cancel_interaction();
                }
                StartupView::NetworkLobby => {
                    if !self.cancel_classic_host_lobby_interaction() {
                        self.menu_state.menu().cancel_interaction();
                    }
                }
                StartupView::MainMenu | StartupView::Options | StartupView::About => {}
            }
        }
    }

    fn handle_menu_input<F>(&mut self, handler: F) -> Result<(), EngineError>
    where
        F: FnOnce(&mut MenuState) -> Vec<StartupMenuAction>,
    {
        if self.game_over_dialog.is_some() || self.definition_selector.is_some() {
            return Ok(());
        }
        if self.mode != AppMode::Menu
            || !matches!(
                self.startup_view,
                StartupView::ScenarioBrowser | StartupView::NetworkLobby
            )
        {
            return Ok(());
        }

        let actions = handler(&mut self.menu_state);
        let (start_identifier, updated_label) = self
            .process_menu_actions(actions)
            .map_err(classic_parity_engine_error)?;

        if let Some(label) = updated_label {
            self.scenario_label = label;
        }

        if let Some(identifier) = start_identifier {
            if let Some(scenario) = self.scenario_catalog.get(&identifier).cloned() {
                if self.startup_view == StartupView::ScenarioBrowser
                    && self.scenario_selector_mode == ScenarioSelectorMode::Local
                {
                    if let Some(message) = self
                        .local_scenario_player_count_error(&scenario)
                        .map_err(classic_parity_engine_error)?
                    {
                        self.status_text.clear();
                        self.push_message_dialog(
                            lc_frontend::message_dialog::MessageDialogState::regular_ok(
                                message,
                                "Cannot start scenario.",
                                lc_frontend::message_dialog::MessageDialogIcon::ERROR,
                            ),
                            MessageDialogContinuation::None,
                        )?;
                        return Ok(());
                    }
                }
                if self.startup_view == StartupView::ScenarioBrowser
                    && self.menu_state.definition_checkbox_checked
                {
                    self.open_definition_selector(scenario)?;
                } else {
                    self.accept_scenario_from_selector(
                        scenario,
                        self.scenario_selector_mode,
                        None,
                    )?;
                }
            } else {
                tracing::warn!(
                    scenario = %identifier,
                    "selected scenario is not available in Rust catalog"
                );
            }
        }
        Ok(())
    }

    fn open_definition_selector(&mut self, scenario: FrontendScenario) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "C4DefinitionSelDlg",
            self.assets
                .definition_sel_resources()
                .context("exact C4DefinitionSelDlg resource set is absent")
                .and_then(|resources| resources.validate()),
        )?;
        self.close_context_menu_silently();
        self.cancel_underlying_interaction();
        let (root, custom_definition_root, entries) = if let Some(paths) = self.app_paths.as_ref() {
            let definition_paths = match startup_definition_paths(paths) {
                Ok(definition_paths) => definition_paths,
                Err(error) => {
                    let fallback = paths
                        .content_dir()
                        .unwrap_or(paths.install_root())
                        .to_path_buf();
                    tracing::error!(
                        %error,
                        fallback = %fallback.display(),
                        "failed to read General.DefinitionPath; using executable data root"
                    );
                    StartupDefinitionPaths {
                        selector_root: fallback,
                        active_custom_root: None,
                    }
                }
            };
            let root = definition_paths.selector_root;
            let entries = match definition_selector_entries(&root) {
                Ok(entries) => entries,
                Err(error) => {
                    // DirectoryIterator simply yields no files when the path
                    // cannot be enumerated; retain the modal and log it.
                    tracing::error!(
                        %error,
                        path = %root.display(),
                        "failed to enumerate definition selector root"
                    );
                    Vec::new()
                }
            };
            (root, definition_paths.active_custom_root, entries)
        } else {
            tracing::error!("cannot resolve C4DefinitionSelDlg root without application paths");
            (PathBuf::new(), None, Vec::new())
        };
        let fixed_selection = scenario_fixed_definition_modules(&scenario);
        self.definition_selector = Some(lc_frontend::definition_sel::DefinitionSelController::new(
            root.to_string_lossy().into_owned(),
            fixed_selection,
            entries,
        ));
        self.pending_definition_selection = Some(PendingDefinitionSelection {
            scenario,
            selector_mode: self.scenario_selector_mode,
            root,
            custom_definition_root,
        });
        self.definition_selector_last_click = None;
        self.definition_selector_consumed_keys.clear();
        self.definition_selector_pointer_capture = false;
        self.mark_menu_dirty();
        Ok(())
    }

    fn process_menu_actions(
        &mut self,
        actions: Vec<StartupMenuAction>,
    ) -> std::result::Result<(Option<String>, Option<String>), ClassicParityBoundary> {
        let mut start_identifier: Option<String> = None;
        let mut updated_label: Option<String> = None;
        let mut pending: VecDeque<StartupMenuAction> = actions.into();

        while let Some(action) = pending.pop_front() {
            match action {
                StartupMenuAction::SelectionChanged(_) => {
                    self.menu_state.sync_definition_checkbox_to_selection();
                    self.sync_scenario_game_option_constraint();
                    self.play_ui_sound("Command");
                }
                StartupMenuAction::StartScenario(summary) => {
                    if summary.kind == ScenarioKind::Editor {
                        return Err(report_classic_parity_boundary(
                            ClassicParityBoundary::EditorScenario {
                                identifier: summary.identifier,
                            },
                        ));
                    }
                    let entry_kind = self
                        .menu_state
                        .require_supported_activation(&summary.identifier)
                        .map_err(report_classic_parity_boundary)?;
                    if matches!(entry_kind, Some(ScenarioKind::Editor)) {
                        return Err(report_classic_parity_boundary(
                            ClassicParityBoundary::EditorScenario {
                                identifier: summary.identifier,
                            },
                        ));
                    }
                    self.play_ui_sound("Click");
                    if matches!(self.startup_view, StartupView::NetworkLobby) {
                        if let Some(lobby) = self.network_lobby.as_mut() {
                            lobby.select_scenario(&summary.identifier, &summary.title);
                            self.scenario_label = lobby.scenario_label();
                            self.status_text = format!("Selected {}", summary.title);
                        }
                    } else {
                        start_identifier = Some(summary.identifier);
                    }
                }
                StartupMenuAction::OpenEntry(summary) => {
                    if summary.identifier == BACK_ENTRY_IDENTIFIER {
                        self.play_ui_sound("DoorClose");
                        if self.menu_state.stack.len() <= 1 {
                            self.show_main_menu();
                        } else {
                            self.menu_state.leave_folder();
                            updated_label = Some(self.menu_state.label_path());
                            pending.extend(self.menu_state.select_default_entry());
                        }
                        continue;
                    }

                    if summary.kind == ScenarioKind::Editor {
                        return Err(report_classic_parity_boundary(
                            ClassicParityBoundary::EditorScenario {
                                identifier: summary.identifier,
                            },
                        ));
                    }

                    let entry_kind = self
                        .menu_state
                        .require_supported_activation(&summary.identifier)
                        .map_err(report_classic_parity_boundary)?;

                    match entry_kind {
                        Some(ScenarioKind::Folder) => {
                            self.play_ui_sound("DoorOpen");
                            self.menu_state.enter_folder(&summary.identifier);
                            self.scenario_game_options.set_focused_button(None);
                            updated_label = Some(self.menu_state.label_path());
                            pending.extend(self.menu_state.select_default_entry());
                        }
                        Some(ScenarioKind::Scenario) => {
                            self.play_ui_sound("Click");
                            if matches!(self.startup_view, StartupView::NetworkLobby) {
                                if let Some(lobby) = self.network_lobby.as_mut() {
                                    lobby.select_scenario(&summary.identifier, &summary.title);
                                    self.scenario_label = lobby.scenario_label();
                                    self.status_text = format!("Selected {}", summary.title);
                                }
                            } else {
                                start_identifier = Some(summary.identifier);
                            }
                        }
                        Some(ScenarioKind::Editor) => {
                            return Err(report_classic_parity_boundary(
                                ClassicParityBoundary::EditorScenario {
                                    identifier: summary.identifier,
                                },
                            ));
                        }
                        None => {
                            self.play_ui_sound("DoorOpen");
                            self.menu_state.enter_folder(&summary.identifier);
                            self.scenario_game_options.set_focused_button(None);
                            updated_label = Some(self.menu_state.label_path());
                            pending.extend(self.menu_state.select_default_entry());
                        }
                    }
                }
                StartupMenuAction::EditEntry(summary) => {
                    return Err(report_classic_parity_boundary(
                        ClassicParityBoundary::EditScenario {
                            identifier: summary.identifier,
                        },
                    ));
                }
            }
        }
        Ok((start_identifier, updated_label))
    }

    fn process_main_menu_actions(
        &mut self,
        actions: Vec<MainMenuAction>,
    ) -> Result<(), EngineError> {
        if self.game_over_dialog.is_some() {
            return Ok(());
        }
        for action in actions {
            match action {
                MainMenuAction::SelectionChanged(_) => {
                    self.play_ui_sound("Command");
                }
                MainMenuAction::Activate(item) => {
                    self.play_ui_sound("Click");
                    self.handle_main_menu_activation(item)?;
                }
            }
        }
        Ok(())
    }

    fn process_network_dialog_actions(
        &mut self,
        actions: Vec<lc_frontend::startup_netdlg::NetDlgAction>,
    ) -> Result<(), EngineError> {
        use lc_frontend::startup_netdlg::NetDlgAction;

        if self.startup_network_transition_active() {
            return Ok(());
        }

        for action in actions {
            match action {
                NetDlgAction::ModeChanged(lc_frontend::startup_netdlg::NetDlgMode::Chat) => {
                    return Err(classic_startup_subscreen_error(
                        ClassicStartupSubscreen::NetworkGameChat,
                    ));
                }
                NetDlgAction::FocusChanged(_)
                | NetDlgAction::ModeChanged(lc_frontend::startup_netdlg::NetDlgMode::GameList)
                | NetDlgAction::JoinAddressChanged(_) => {}
                NetDlgAction::Back => self.show_main_menu(),
                NetDlgAction::Refresh => {
                    return Err(classic_startup_action_error(
                        ClassicStartupAction::NetworkRefresh,
                    ));
                }
                NetDlgAction::JoinGame { address } => {
                    let selected_reference = self
                        .startup_network_dialog
                        .as_ref()
                        .filter(|dialog| {
                            dialog.focused_control()
                                != lc_frontend::startup_netdlg::NetDlgControl::JoinAddress
                                || dialog.join_address().is_empty()
                        })
                        .and_then(|dialog| dialog.selected_game())
                        .and_then(|index| self.startup_game_references.get(index))
                        .filter(|reference| reference.is_joinable())
                        .cloned();
                    if let Some(reference) = selected_reference {
                        self.activate_network_reference_join(reference)?;
                        continue;
                    }
                    let Some(address) = address else {
                        self.status_text.clear();
                        self.push_message_dialog(
                            lc_frontend::message_dialog::MessageDialogState::regular_ok(
                                "No reference selected. Select a game from the list or enter a direct join address below!",
                                "Cannot join game",
                                lc_frontend::message_dialog::MessageDialogIcon::ERROR,
                            ),
                            MessageDialogContinuation::None,
                        )?;
                        continue;
                    };
                    return Err(classic_startup_action_error(
                        ClassicStartupAction::NetworkDirectJoin { address },
                    ));
                }
                NetDlgAction::CreateGame => {
                    // C4StartupNetDlg opens C4StartupScenSelDlg(true) before
                    // any host socket or NetworkManager exists.
                    self.open_network_host_scenario_browser();
                }
                NetDlgAction::MasterserverSignupChanged(enabled) => {
                    if let Some(search) = self.startup_game_search.as_ref() {
                        let _ = search.set_internet_enabled(enabled);
                    }
                    if let Some(paths) = self.app_paths.as_ref() {
                        if let Err(error) = persist_config_value(
                            paths,
                            "Network",
                            "MasterServerSignUp",
                            i32::from(enabled).to_string(),
                        ) {
                            self.status_text = format!("Unable to save network setting: {error}");
                        }
                    }
                }
                NetDlgAction::RecordingChanged(record) => {
                    self.startup_view_flags.record = record;
                    self.recording_enabled = record && self.recordings_dir.is_some();
                    if let Some(paths) = self.app_paths.as_ref() {
                        if let Err(error) = persist_config_value(
                            paths,
                            "General",
                            "Record",
                            i32::from(record).to_string(),
                        ) {
                            self.status_text = format!("Unable to save recording setting: {error}");
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn begin_startup_network_connection(
        &mut self,
        receiver: Receiver<
            std::result::Result<(NetworkMode, NetworkManager), NetworkStartError>,
        >,
        purpose: StartupNetworkPurpose,
        selected_scenario: Option<(String, String)>,
    ) {
        self.startup_network_connection = Some(StartupNetworkConnection {
            receiver,
            selected_scenario,
            purpose,
        });
        if purpose == StartupNetworkPurpose::StagedHost {
            let initial_fonts = self
                .staged_network_host_scenario
                .as_ref()
                .and_then(|staged| staged.loader_screen.as_ref())
                .map(|loader| loader.resources().fonts().clone());
            let initial_tooltip = self
                .staged_network_host_scenario
                .as_ref()
                .map(|staged| staged.loader_initial_tooltip_font.clone());
            let initial_native_source = self
                .staged_network_host_scenario
                .as_ref()
                .and_then(|staged| staged.loader_initial_native_font_source.clone());
            if let (Some(fonts), Some(tooltip)) = (initial_fonts, initial_tooltip) {
                self.install_active_classic_fonts(fonts, Some(tooltip), initial_native_source);
            }
            // C4Game opens the scenario and installs its loader before
            // InitNetworkHost. Show that exact full loader while the socket
            // worker starts; the lobby later retains only its background.
            self.cancel_underlying_interaction();
            self.startup_view = StartupView::NetworkGame;
            if let Some(loader) = self
                .staged_network_host_scenario
                .as_mut()
                .and_then(|staged| staged.loader_screen.take())
            {
                self.loader_screen = Some(loader);
                self.loader_error = None;
            }
            self.status_text.clear();
            self.mode = AppMode::Loading;
        } else {
            self.status_text = "Connecting to network game…".to_string();
        }
        self.mark_menu_dirty();
    }

    fn activate_prepared_network_host(
        &mut self,
        scenario: FrontendScenario,
        bind_addr: SocketAddr,
    ) {
        if self.startup_network_connection.is_some() {
            self.status_text = "A network connection is already in progress".to_string();
            return;
        }
        let preparation = match build_network_host_preparation(self, &scenario) {
            Ok(preparation) => preparation,
            Err(error) => {
                self.status_text = format!("Unable to prepare network game: {error}");
                return;
            }
        };
        let selected_scenario = Some((scenario.identifier.clone(), scenario.title.clone()));
        self.startup_game_search = None;
        let (sender, receiver) = mpsc::channel();
        let local_owner = self.local_owner;
        let spawn = thread::Builder::new()
            .name("lc-prepare-network-host".to_string())
            .spawn(move || {
                let result = preparation
                    .prepare()
                    .map_err(|error| {
                        NetworkStartError::Other(format!("host preparation failed: {error}"))
                    })
                    .and_then(|prepared| {
                        let mode = NetworkMode::Host(HostSettings {
                            bind_addr,
                            player_name: prepared
                                .host_config()
                                .local_core
                                .name
                                .to_string_lossy()
                                .into_owned(),
                            prepared: Some(prepared),
                        });
                        NetworkManager::for_mode(mode.clone(), local_owner)
                            .map(|manager| (mode, manager))
                    });
                let _ = sender.send(result);
            });
        match spawn {
            Ok(_) => {
                self.begin_startup_network_connection(
                    receiver,
                    StartupNetworkPurpose::StagedHost,
                    selected_scenario,
                );
                self.status_text = "Preparing network game…".to_string();
            }
            Err(error) => {
                self.status_text = format!("Unable to start network preparation: {error}");
            }
        }
    }

    fn activate_network_join(&mut self, address: String) {
        if self.startup_network_connection.is_some() {
            self.status_text = "A network connection is already in progress".to_string();
            return;
        }
        if let Err(error) = self.freeze_configured_client_players_for_game() {
            self.status_text = format!("Unable to load configured players: {error}");
            return;
        }
        self.startup_game_search = None;
        let (sender, receiver) = mpsc::channel();
        let local_owner = self.local_owner;
        let player_name = self.player_name.clone();
        let app_paths = self.app_paths.clone();
        let (_, default_port) = load_network_startup_settings(self.app_paths.as_ref());
        let spawn = thread::Builder::new()
            .name("lc-startup-network".to_string())
            .spawn(move || {
                let result = resolve_join_socket(&address, default_port)
                    .map_err(|error| {
                        NetworkStartError::Other(format!(
                            "invalid network address: {error:#}"
                        ))
                    })
                    .and_then(|server_addr| {
                        let mode = NetworkMode::Client(client_settings_for_paths(
                            server_addr,
                            player_name,
                            app_paths.as_ref(),
                        ));
                        NetworkManager::for_mode(mode.clone(), local_owner)
                            .map(|manager| (mode, manager))
                    });
                let _ = sender.send(result);
            });
        match spawn {
            Ok(_) => {
                self.begin_startup_network_connection(receiver, StartupNetworkPurpose::Join, None);
            }
            Err(error) => {
                self.status_text = format!("Unable to start network worker: {error}");
            }
        }
    }

    fn activate_network_reference_join(
        &mut self,
        reference: lc_network::NetworkGameReference,
    ) -> Result<(), EngineError> {
        if self.startup_network_connection.is_some() {
            self.status_text = "A network connection is already in progress".to_string();
            return Ok(());
        }
        if let Err(error) = self.freeze_configured_client_players_for_game() {
            self.status_text = format!("Unable to load configured players: {error}");
            return Ok(());
        }
        let attempts = reference.join_attempts_for_local_host();
        let netpuncher_address = reference.netpuncher_address.clone();
        let netpuncher_game_ids = lc_network::NetpuncherGameIds {
            ipv4: reference.netpuncher_ipv4,
            ipv6: reference.netpuncher_ipv6,
        };
        let settings = client_settings_for_paths(
            reference.source_address,
            self.player_name.clone(),
            self.app_paths.as_ref(),
        )
        .with_join_attempts(attempts)
        .with_netpuncher(netpuncher_address, netpuncher_game_ids);
        self.startup_game_search = None;
        self.pending_network_join = Some(settings);
        if reference.password_needed {
            self.open_network_join_password_dialog()?;
        } else {
            self.launch_pending_network_join();
        }
        Ok(())
    }

    fn launch_pending_network_join(&mut self) {
        let Some(settings) = self.pending_network_join.clone() else {
            self.status_text = "Network join settings are unavailable".to_string();
            return;
        };
        let (sender, receiver) = mpsc::channel();
        let local_owner = self.local_owner;
        let spawn = thread::Builder::new()
            .name("lc-startup-network".to_string())
            .spawn(move || {
                let mode = NetworkMode::Client(settings);
                let result = NetworkManager::for_mode(mode.clone(), local_owner)
                    .map(|manager| (mode, manager));
                let _ = sender.send(result);
            });
        match spawn {
            Ok(_) => {
                self.begin_startup_network_connection(receiver, StartupNetworkPurpose::Join, None);
            }
            Err(error) => {
                self.pending_network_join = None;
                self.status_text = format!("Unable to start network worker: {error}");
            }
        }
    }

    fn open_network_join_password_dialog(&mut self) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "Network join password input dialog",
            self.assets.input_dialog_resources().map(|_| ()),
        )?;
        self.close_context_menu_silently();
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.cancel_interaction();
        }
        let controller = InputDialogController::new(
            "Enter password:",
            "Enter password:",
            InputDialogIcon::LOCKED,
        );
        self.game_option_input_dialog = Some(PendingGameOptionInputDialog {
            kind: GameOptionInputKind::Password,
            network_join_password: true,
            controller,
        });
        self.game_option_input_consumed_keys.clear();
        self.game_option_input_pointer_capture = None;
        self.game_option_input_pointer_position = None;
        self.game_option_input_last_click = None;
        self.status_text.clear();
        self.mark_menu_dirty();
        Ok(())
    }

    fn build_classic_host_lobby(
        &self,
        mode: &NetworkMode,
        manager: &NetworkManager,
    ) -> Result<(ClassicHostLobbyState, GameOptionButtons)> {
        let NetworkMode::Host(settings) = mode else {
            return Err(classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "client sessions do not have an app-wired classic lobby".to_string(),
            }));
        };
        if manager.local_client_id() != 0 {
            return Err(classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "classic host lobby requires local client ID zero".to_string(),
            }));
        }
        let staged = self.staged_network_host_scenario.as_ref().ok_or_else(|| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "host connection completed without a staged scenario".to_string(),
            })
        })?;
        if settings.player_name != staged.lobby.local_name {
            return Err(classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "connected host identity differs from the pre-bind accepted model"
                    .to_string(),
            }));
        }
        self.assets.game_lobby_resources().map_err(|error| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: error.to_string(),
            })
        })?;
        self.assets.game_option_resources().map_err(|error| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: error.to_string(),
            })
        })?;
        let loader = self.loader_screen.as_ref().ok_or_else(|| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: "staged scenario loader is not installed".to_string(),
            })
        })?;
        let rows = vec![LobbyRosterRow::Client(LobbyClientRow {
            id: 0,
            name: staged.lobby.local_name.clone(),
            nick: staged.lobby.nick.clone(),
            color: [255, 255, 255, 255],
            status: LobbyClientStatus::Host,
            local: true,
            connected: false,
            resource_progress: None,
            ping_ms: None,
        })];
        let mut controller = ClassicGameLobby::new(
            LobbyRole::Host,
            loader.state().title(),
            0,
            staged.lobby.max_players,
            staged.lobby.has_teams,
            false,
            false,
            false,
            staged.lobby.countdown_seconds,
            rows,
        );
        let mut values = staged.options.clone();
        values.lobby_is_league = initial_network_is_league(Some(mode));
        values.selector_fair_crew_constraint = FairCrewConstraint::Free;
        values.lobby_fair_crew_forced = staged.lobby.fair_crew_forced;
        values.fair_crew = staged.lobby.fair_crew;
        values.fair_crew_strength = staged.lobby.fair_crew_strength;
        values.countdown = false;
        let mut options = GameOptionButtons::new(GameOptionContext::LobbyHost, values);
        let fonts = self.assets.clonk_fonts.as_deref().ok_or_else(|| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: "CStdFont-faithful lobby fonts are unavailable".to_string(),
            })
        })?;
        let surface = self.graphics.surface();
        let layout = controller.layout(surface.width() as i32, surface.height() as i32, fonts);
        options.set_bounds(layout.game_option_strip);
        // Prime scroll metrics before the first pointer or wheel event.
        let _ = controller.roster_layout(&layout, fonts.text.line_height);
        Ok((
            ClassicHostLobbyState {
                controller,
                pointer: None,
                chat_history_index: -1,
            },
            options,
        ))
    }

    fn poll_startup_network_connection(&mut self) {
        let selected_scenario = self
            .startup_network_connection
            .as_ref()
            .and_then(|connection| connection.selected_scenario.clone());
        let purpose = self
            .startup_network_connection
            .as_ref()
            .map(|connection| connection.purpose);
        let result = match self
            .startup_network_connection
            .as_ref()
            .map(|connection| connection.receiver.try_recv())
        {
            Some(Ok(result)) => result,
            Some(Err(TryRecvError::Empty)) | None => return,
            Some(Err(TryRecvError::Disconnected)) => Err(NetworkStartError::Other(
                "network worker disconnected before reporting readiness".to_string(),
            )),
        };
        self.startup_network_connection = None;
        self.mark_menu_dirty();
        match result {
            Ok((mut mode, mut manager)) => {
                if let Some(response) = manager.take_league_start_response() {
                    if let NetworkMode::Host(HostSettings {
                        prepared: Some(prepared),
                        ..
                    }) = &mut mode
                    {
                        if let Err(error) = prepared.apply_league_start_response(&response) {
                            self.status_text =
                                format!("Unable to apply league registration: {error}");
                            self.mode = AppMode::Menu;
                            self.restore_startup_fonts();
                            return;
                        }
                    }
                    if response.max_players != 0 {
                        if let Some(staged) = self.staged_network_host_scenario.as_mut() {
                            staged.lobby.max_players = response.max_players;
                        }
                    }
                }
                if purpose == Some(StartupNetworkPurpose::Join) {
                    self.pending_network_join = None;
                }
                // InitNetwork constructs a fresh C4Network2Client list; no
                // activity timestamp survives into the new socket session.
                self.network_client_activity.clear();
                if purpose == Some(StartupNetworkPurpose::StagedHost) {
                    let control_clients = initial_control_clients(Some(&manager), Some(&mode));
                    let network_control_clock = initial_network_control_clock(Some(&mode));
                    let mut previous_player_infos = None;
                    let mut previous_admission_resources = None;
                    let admission_ready = match &mode {
                        NetworkMode::Host(settings) => match settings.prepared.as_ref() {
                            Some(prepared) => {
                                // C4Network2Players::Init executes the host's
                                // Initial PlayerInfo directly before C4Game opens
                                // joining (src/C4Game.cpp:3869-3876;
                                // src/C4Network2Players.cpp:38-49,78-123).
                                previous_player_infos =
                                    Some(std::mem::take(&mut self.control_player_infos));
                                previous_admission_resources =
                                    Some(std::mem::take(&mut self.admission_resources));
                                let player_infos = &mut self.control_player_infos;
                                let resources = &mut self.admission_resources;
                                match prepared.install_initial_host_player_state(
                                    player_infos,
                                    |core, path| {
                                        resources.mark_complete(core.id, path.to_path_buf())
                                    },
                                ) {
                                    Ok(ready) => Some(ready),
                                    Err(error) => {
                                        self.control_player_infos = previous_player_infos
                                            .take()
                                            .expect("prepared install saved the previous registry");
                                        self.admission_resources =
                                            previous_admission_resources.take().expect(
                                                "prepared install saved the previous resources",
                                            );
                                        self.status_text = format!(
                                            "Unable to install prepared host PlayerInfo/resources: {error}"
                                        );
                                        self.staged_network_host_scenario = None;
                                        self.loader_screen = None;
                                        self.network_control_running = true;
                                        self.control_clients = initial_control_clients(None, None);
                                        self.startup_view = StartupView::NetworkGame;
                                        self.mode = AppMode::Menu;
                                        self.restore_startup_fonts();
                                        return;
                                    }
                                }
                            }
                            None => None,
                        },
                        NetworkMode::Client(_) => None,
                    };
                    if let Some(admission_ready) = admission_ready {
                        if let Err(error) =
                            manager.set_join_allowed(admission_ready.lobby_join_allowed())
                        {
                            if let Some(previous_player_infos) = previous_player_infos.take() {
                                self.control_player_infos = previous_player_infos;
                            }
                            if let Some(previous_admission_resources) =
                                previous_admission_resources.take()
                            {
                                self.admission_resources = previous_admission_resources;
                            }
                            self.status_text =
                                format!("Unable to open prepared host admission: {error}");
                            self.staged_network_host_scenario = None;
                            self.loader_screen = None;
                            self.network_control_running = true;
                            self.control_clients = initial_control_clients(None, None);
                            self.startup_view = StartupView::NetworkGame;
                            self.mode = AppMode::Menu;
                            self.restore_startup_fonts();
                            return;
                        }
                    }
                    if self.staged_network_host_scenario.is_none()
                        && matches!(
                            &mode,
                            NetworkMode::Host(HostSettings {
                                prepared: Some(_),
                                ..
                            })
                        )
                    {
                        if let Some((identifier, title)) = selected_scenario.as_ref() {
                            // Keep the prepared host's selected scenario and
                            // admission state alive in the established network
                            // lobby projection.
                            let mut lobby = NetworkLobbyState::new(
                                manager.local_client_id(),
                                self.player_name.clone(),
                                true,
                            );
                            lobby.select_scenario(identifier, title);
                            self.scenario_label = lobby.scenario_label();
                            if let NetworkMode::Host(HostSettings {
                                prepared: Some(prepared),
                                ..
                            }) = &mode
                            {
                                self.start_prepared_network_game_advertiser(prepared, &manager);
                            }
                            self.network_max_players = initial_network_max_players(Some(&mode));
                            self.engine.set_max_players(
                                i32::try_from(self.network_max_players).unwrap_or(i32::MAX),
                            );
                            self.control_clients = control_clients;
                            self.host_join_snapshot = initial_host_join_snapshot(Some(&mode));
                            self.network_is_league = initial_network_is_league(Some(&mode));
                            self.network_league_name = initial_network_league_name(Some(&mode));
                            seed_engine_player_info_parameters(
                                &mut self.engine,
                                &self.network_league_name,
                                &self.control_player_infos,
                            );
                            self.network_team_assignment =
                                initial_network_team_assignment(
                                    Some(&mode),
                                    &self.generated_team_name_template,
                                );
                            self.network_mode = Some(mode);
                            self.network = Some(manager);
                            self.network_control_running = false;
                            self.network_control_clock = network_control_clock;
                            self.network_lobby = Some(lobby);
                            self.classic_host_lobby = None;
                            self.startup_view = StartupView::NetworkLobby;
                            self.mode = AppMode::Menu;
                            self.status_text.clear();
                            self.menu_frame_cache = None;
                            self.restore_startup_fonts();
                            return;
                        }
                    }
                    match self.build_classic_host_lobby(&mode, &manager) {
                        Ok((lobby, options)) => {
                            match &mode {
                                NetworkMode::Host(HostSettings {
                                    prepared: Some(prepared),
                                    ..
                                }) => {
                                    self.start_prepared_network_game_advertiser(prepared, &manager)
                                }
                                NetworkMode::Host(_) | NetworkMode::Client(_) => {
                                    self.network_game_advertiser = None;
                                    self.advertised_game_reference = None;
                                    self.host_reference_paused = false;
                                }
                            }
                            self.network_max_players = initial_network_max_players(Some(&mode));
                            self.engine.set_max_players(
                                i32::try_from(self.network_max_players).unwrap_or(i32::MAX),
                            );
                            self.control_clients = control_clients;
                            self.host_join_snapshot = initial_host_join_snapshot(Some(&mode));
                            self.network_is_league = initial_network_is_league(Some(&mode));
                            self.network_league_name = initial_network_league_name(Some(&mode));
                            seed_engine_player_info_parameters(
                                &mut self.engine,
                                &self.network_league_name,
                                &self.control_player_infos,
                            );
                            self.network_team_assignment =
                                initial_network_team_assignment(
                                    Some(&mode),
                                    &self.generated_team_name_template,
                                );
                            self.network_mode = Some(mode);
                            self.network = Some(manager);
                            self.network_control_running = false;
                            self.network_control_clock = network_control_clock;
                            self.network_lobby = None;
                            self.classic_host_lobby = Some(lobby);
                            self.scenario_game_options = options;
                            self.startup_view = StartupView::NetworkLobby;
                            self.mode = AppMode::Menu;
                            self.status_text.clear();
                            self.menu_frame_cache = None;
                            if let Some(audio) = self.audio.as_mut() {
                                audio.stop_music();
                            }
                            return;
                        }
                        Err(error) => {
                            if let Some(previous_player_infos) = previous_player_infos.take() {
                                self.control_player_infos = previous_player_infos;
                            }
                            if let Some(previous_admission_resources) =
                                previous_admission_resources.take()
                            {
                                self.admission_resources = previous_admission_resources;
                            }
                            tracing::error!(%error, "cannot enter exact classic host lobby");
                            self.status_text = format!("Network lobby unavailable: {error}");
                        }
                    }
                } else {
                    let lobby = NetworkLobbyState::new(
                        manager.local_client_id(),
                        self.player_name.clone(),
                        false,
                    );
                    self.network_game_advertiser = None;
                    self.advertised_game_reference = None;
                    self.host_reference_paused = false;
                    self.network_max_players = initial_network_max_players(Some(&mode));
                    self.engine.set_max_players(
                        i32::try_from(self.network_max_players).unwrap_or(i32::MAX),
                    );
                    self.network_is_league = initial_network_is_league(Some(&mode));
                    self.network_league_name = initial_network_league_name(Some(&mode));
                    seed_engine_player_info_parameters(
                        &mut self.engine,
                        &self.network_league_name,
                        &self.control_player_infos,
                    );
                    self.network_control_clock = initial_network_control_clock(Some(&mode));
                    self.control_clients = initial_control_clients(Some(&manager), Some(&mode));
                    self.host_join_snapshot = initial_host_join_snapshot(Some(&mode));
                    self.network_mode = Some(mode);
                    self.network = Some(manager);
                    self.network_control_running = false;
                    self.network_team_assignment = None;
                    self.network_lobby = Some(lobby);
                    self.classic_host_lobby = None;
                    self.host_lobby_countdown = None;
                    self.mode = AppMode::Menu;
                    self.open_network_lobby();
                    return;
                }
                self.classic_host_lobby = None;
                self.network = None;
                self.network_mode = None;
                self.host_join_snapshot = None;
                self.network_is_league = false;
                self.network_league_name.clear();
                seed_engine_player_info_parameters(
                    &mut self.engine,
                    &self.network_league_name,
                    &self.control_player_infos,
                );
                self.network_control_running = true;
                self.runtime_network_status_barrier = None;
                self.control_clients = initial_control_clients(None, None);
                self.startup_view = StartupView::NetworkGame;
                self.mode = AppMode::Menu;
            }
            Err(NetworkStartError::WrongPassword { .. })
                if purpose == Some(StartupNetworkPurpose::Join)
                    && self.pending_network_join.is_some() =>
            {
                self.mode = AppMode::Menu;
                if let Err(error) = self.open_network_join_password_dialog() {
                    self.pending_network_join = None;
                    self.status_text =
                        format!("Unable to reopen the network password prompt: {error}");
                }
            }
            Err(error) => {
                self.pending_network_join = None;
                self.status_text = format!("Unable to start network session: {error}");
                self.mode = AppMode::Menu;
            }
        }
        if purpose == Some(StartupNetworkPurpose::StagedHost) {
            self.restore_startup_fonts();
            self.classic_host_lobby = None;
            self.staged_network_host_scenario = None;
            self.loader_screen = None;
            self.network = None;
            self.network_mode = None;
            self.host_join_snapshot = None;
            self.network_is_league = false;
            self.network_league_name.clear();
            seed_engine_player_info_parameters(
                &mut self.engine,
                &self.network_league_name,
                &self.control_player_infos,
            );
            self.network_control_running = true;
            self.runtime_network_status_barrier = None;
            self.control_clients = initial_control_clients(None, None);
            self.startup_view = StartupView::NetworkGame;
        }
    }

    fn start_prepared_network_game_advertiser(
        &mut self,
        prepared: &prepared_host_bootstrap::PreparedHostBootstrap,
        network: &NetworkManager,
    ) {
        // InitLocal snapshots the canonical parameters and live admission only
        // after Players.Init/AllowJoin, then the reference server exposes that
        // complete value (src/C4Network2Reference.cpp:49-109;
        // src/C4Game.cpp:3869-3876).
        let (game_ids, addresses) = network.netpuncher_state();
        let reference = match prepared
            .initial_host_game_reference(true, &addresses)
            .map_err(|error| error.to_string())
            .and_then(|reference| {
                reference
                    .replacing_netpuncher_state(game_ids, addresses)
                    .map_err(|error| error.to_string())
            })
        {
            Ok(reference) => reference,
            Err(error) => {
                tracing::warn!(%error, "exact network game reference unavailable");
                self.network_game_advertiser = None;
                self.advertised_game_reference = None;
                self.host_reference_paused = false;
                return;
            }
        };
        let config = load_network_advertiser_settings(self.app_paths.as_ref());
        self.start_network_game_advertiser_with_reference(config, reference);
    }

    fn start_network_game_advertiser_with_reference(
        &mut self,
        config: lc_network::NetworkGameAdvertiserConfig,
        reference: lc_network::HostGameReference,
    ) {
        // The validated InitLocal value is game state, not socket state. Keep
        // it even when the optional LAN/reference listener cannot bind so a
        // later runtime or game-over rebuild never falls back to stale data.
        self.advertised_game_reference = Some(reference.clone());
        self.host_reference_paused = false;
        match lc_network::NetworkGameAdvertiser::start_exact(config, reference.clone()) {
            Ok(advertiser) => {
                self.network_game_advertiser = Some(advertiser);
            }
            Err(error) => {
                tracing::warn!(%error, "network game advertising unavailable");
                self.network_game_advertiser = None;
            }
        }
    }

    fn update_host_netpuncher_reference(
        &mut self,
        game_ids: lc_network::NetpuncherGameIds,
        addresses: Vec<lc_network::NetworkAddress>,
    ) {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return;
        }
        if let Some(network) = self.network.as_ref() {
            if let Err(error) = network.invalidate_league_reference() {
                tracing::error!(%error, "failed to invalidate netpuncher league reference");
            }
        }
        let Some(reference) = self.advertised_game_reference.clone() else {
            return;
        };
        let updated = match reference.replacing_netpuncher_state(game_ids, addresses) {
            Ok(updated) => updated,
            Err(error) => {
                tracing::error!(%error, "failed to rebuild netpuncher host reference");
                return;
            }
        };
        self.advertised_game_reference = Some(updated.clone());
        if let Some(advertiser) = self.network_game_advertiser.as_ref() {
            if let Err(error) = advertiser.update_exact(&updated) {
                tracing::error!(%error, "failed to publish netpuncher host reference");
            }
        }
    }

    fn publish_running_host_reference(&mut self) {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return;
        }
        let Some(template) = self.advertised_game_reference.clone() else {
            return;
        };
        let parameters = self
            .host_join_snapshot
            .as_ref()
            .map(|snapshot| snapshot.parameters.clone())
            .unwrap_or_else(|| template.parameters().clone());
        let max_players = self
            .engine
            .max_players()
            .unwrap_or_else(|| i32::try_from(self.network_max_players).unwrap_or(i32::MAX));
        let join_allowed = self
            .network_mode
            .as_ref()
            .and_then(|mode| match mode {
                NetworkMode::Host(HostSettings {
                    prepared: Some(prepared),
                    ..
                }) => Some(prepared.admission().runtime_join_allowed()),
                NetworkMode::Host(_) | NetworkMode::Client(_) => None,
            })
            .unwrap_or(template.summary().join_allowed);
        let updated = match running_host_reference(
            &template,
            parameters,
            &self.control_clients,
            &self.control_player_infos,
            self.engine.teams(),
            max_players,
            if self.host_reference_paused {
                "Paused"
            } else {
                "Running"
            },
            join_allowed,
            &self.snapshot,
        ) {
            Ok(reference) => reference,
            Err(error) => {
                tracing::error!(%error, "failed to rebuild running host reference");
                return;
            }
        };

        // Commit the validated state independently of advertiser I/O.
        self.advertised_game_reference = Some(updated.clone());
        if let Some(advertiser) = self.network_game_advertiser.as_ref() {
            if let Err(error) = advertiser.update_exact(&updated) {
                tracing::error!(%error, "failed to update running host reference");
            }
        }
    }

    fn publish_game_over_host_reference(&mut self) {
        let config = load_network_advertiser_settings(self.app_paths.as_ref());
        self.publish_game_over_host_reference_with_config(config);
    }

    fn publish_game_over_host_reference_with_config(
        &mut self,
        config: lc_network::NetworkGameAdvertiserConfig,
    ) {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return;
        }
        let Some(template) = self.advertised_game_reference.clone() else {
            return;
        };
        let parameters = self
            .host_join_snapshot
            .as_ref()
            .map(|snapshot| snapshot.parameters.clone())
            .unwrap_or_else(|| template.parameters().clone());
        let max_players = self
            .engine
            .max_players()
            .unwrap_or_else(|| i32::try_from(self.network_max_players).unwrap_or(i32::MAX));
        let updated = match game_over_host_reference(
            &template,
            parameters,
            &self.control_clients,
            &self.control_player_infos,
            self.engine.teams(),
            max_players,
            &self.snapshot,
        ) {
            Ok(reference) => reference,
            Err(error) => {
                tracing::error!(%error, "failed to rebuild game-over host reference");
                return;
            }
        };

        // The final reference is authoritative even if an optional listener
        // update or one-shot rebind fails.
        self.advertised_game_reference = Some(updated.clone());

        if let Some(advertiser) = self.network_game_advertiser.as_ref() {
            if let Err(error) = advertiser.update_exact(&updated) {
                tracing::error!(%error, "failed to update game-over host reference");
            }
        } else {
            match lc_network::NetworkGameAdvertiser::start_exact(config, updated.clone()) {
                Ok(advertiser) => self.network_game_advertiser = Some(advertiser),
                Err(error) => {
                    tracing::warn!(%error, "game-over network advertising unavailable");
                }
            }
        }
    }

    fn open_context_menu_at(
        &mut self,
        entries: Vec<ContextMenuEntry<AppContextMenuCommand>>,
        anchor: GuiPoint,
    ) -> Result<bool, EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        let resources = self
            .assets
            .context_menu_resources()
            .map_err(|error| Self::gui_overlay_engine_error("C4GUI context menu", error))?;
        let surface = self.graphics.surface();
        let screen = lc_frontend::classic_gui::IntRect {
            x: 0,
            y: 0,
            w: surface.width() as i32,
            h: surface.height() as i32,
        };
        let (menu, outcome) = ClassicContextMenu::open(entries, anchor, screen, resources);
        self.context_menu = Some(menu);
        self.process_context_menu_outcome(outcome)?;
        Ok(true)
    }

    fn open_options_language_combo(&mut self) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::Options
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
            || self.context_menu.is_some()
        {
            return Ok(false);
        }
        let Some((anchor, entries)) = self.startup_options_dialog.as_ref().and_then(|dialog| {
            let anchor = dialog.language_combo_anchor()?;
            let entries = dialog
                .program()
                .language_infos
                .iter()
                .map(|info| {
                    ContextMenuEntry::new(format!("{} - {}", info.code, info.name))
                        .with_icon(ContextMenuIcon::Empty)
                        .with_action(AppContextMenuCommand::OptionsLanguage(info.code.clone()))
                })
                .collect();
            Some((anchor, entries))
        }) else {
            return Ok(false);
        };
        self.open_context_menu_at(entries, anchor)
    }

    fn open_startup_player_context_menu(&mut self) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::PlayerSelection
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
        {
            return Ok(false);
        }
        let Some((index, anchor)) = self.startup_player_dialog.as_ref().and_then(|dialog| {
            let point = dialog.pointer_position()?;
            dialog
                .player_context_index_at(point)
                .map(|index| (index, point))
        }) else {
            return Ok(false);
        };
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "C4GUI context menu",
            self.assets.context_menu_resources().map(|_| ()),
        )?;
        if !self
            .startup_player_dialog
            .as_mut()
            .is_some_and(|dialog| dialog.select_player_for_context(index))
        {
            tracing::error!(index, "player context menu references a stale row");
            return Ok(false);
        }

        let model = lc_frontend::startup_plrsel::PlrSelPlayerContextMenu::for_player(index);
        let entries = model
            .entries
            .into_iter()
            .map(|entry| {
                let icon = match entry.icon {
                    lc_frontend::startup_plrsel::PlrSelPlayerContextIcon::None => {
                        ContextMenuIcon::None
                    }
                };
                let mut item = ContextMenuEntry::new(entry.label)
                    .with_icon(icon)
                    .with_action(AppContextMenuCommand::StartupPlayer(entry.command));
                if let Some(tooltip) = entry.tooltip {
                    item = item.with_tooltip(tooltip);
                }
                if let Some(hotkey) = entry.hotkey {
                    item = item.with_hotkey(hotkey);
                }
                item
            })
            .collect();
        self.open_context_menu_at(entries, anchor)
    }

    fn open_startup_participants_context_menu(&mut self) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::MainMenu
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
        {
            return Ok(false);
        }
        let Some(anchor) = self
            .main_menu_state
            .pointer_position()
            .filter(|point| self.main_menu_state.participants_contains(*point))
        else {
            return Ok(false);
        };
        let Some(paths) = self.app_paths.clone() else {
            return Err(Self::gui_overlay_engine_error(
                "startup participants context menu",
                "application paths are unavailable",
            ));
        };
        let add_paths = paths.clone();
        let remove_paths = paths;
        let entries = vec![
            ContextMenuEntry::new("Add")
                .with_tooltip("Add participant")
                .with_lazy_submenu(move || startup_participant_add_entries(&add_paths)),
            ContextMenuEntry::new("Remove")
                .with_tooltip("Remove participant")
                .with_lazy_submenu(move || startup_participant_remove_entries(&remove_paths)),
        ];
        self.open_context_menu_at(entries, anchor)
    }

    fn open_scenario_search_context_menu(
        &mut self,
        keyboard_trigger: bool,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::ScenarioBrowser
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
            || self.context_menu.is_some()
        {
            return Ok(false);
        }
        let Some(fonts) = self.assets.clonk_fonts.as_deref() else {
            return Err(Self::gui_overlay_engine_error(
                "scenario-search context menu",
                "classic GUI fonts are unavailable",
            ));
        };
        let search = lc_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            fonts,
        )
        .search_edit;
        let anchor = if keyboard_trigger {
            if !self.menu_state.search_focused() {
                return Ok(false);
            }
            GuiPoint::new(
                (search.x + search.w / 2) as f32,
                (search.y + search.h / 2) as f32,
            )
        } else {
            let Some(point) = self.menu_state.pointer_position().filter(|point| {
                point.x >= search.x as f32
                    && point.x < (search.x + search.w) as f32
                    && point.y >= search.y as f32
                    && point.y < (search.y + search.h) as f32
            }) else {
                return Ok(false);
            };
            point
        };
        let entries = scensel_search_context_entries(
            &self.menu_state.search_edit,
            clipboard_text_available(),
        );
        self.open_context_menu_at(entries, anchor)
    }

    fn process_context_menu_outcome(
        &mut self,
        outcome: ContextMenuOutcome<AppContextMenuCommand>,
    ) -> Result<(), EngineError> {
        if !outcome.events.is_empty() {
            self.mark_menu_dirty();
        }
        for event in outcome.events {
            match event {
                ContextMenuEvent::Sound(sound) => self.play_ui_sound(match sound {
                    ContextMenuSound::DoorOpen => "DoorOpen",
                    ContextMenuSound::DoorClose => "DoorClose",
                    ContextMenuSound::Command => "Command",
                    ContextMenuSound::Click => "Click",
                }),
                ContextMenuEvent::Closed => {
                    self.context_menu = None;
                }
                ContextMenuEvent::Activated(command) => match command {
                    AppContextMenuCommand::StartupPlayer(
                        PlrSelPlayerContextCommand::PlayerProperties(index),
                    ) => {
                        return Err(classic_startup_action_error(
                            ClassicStartupAction::PlayerProperties { index },
                        ));
                    }
                    AppContextMenuCommand::StartupPlayer(
                        PlrSelPlayerContextCommand::DeletePlayer(index),
                    ) => {
                        // ContextMenu already emitted the activation Click.
                        self.open_startup_player_delete_dialog(index, false)?;
                    }
                    AppContextMenuCommand::AddStartupParticipant(reference) => {
                        self.set_startup_participant(&reference, true);
                    }
                    AppContextMenuCommand::RemoveStartupParticipant(index) => {
                        self.remove_startup_participant(index);
                    }
                    AppContextMenuCommand::OptionsLanguage(code) => {
                        let selected = self
                            .startup_options_dialog
                            .as_mut()
                            .is_some_and(|dialog| dialog.select_language(&code));
                        if !selected {
                            tracing::error!(code, "language combo selected a stale entry");
                            continue;
                        }
                        match self.persist_open_options_config() {
                            Some(Ok(())) => {
                                match self.reload_application_language_resources() {
                                    Ok(charset) => {
                                        if let Some(paths) = self.app_paths.as_ref() {
                                            if let Err(error) = persist_config_value(
                                                paths,
                                                "General",
                                                "LanguageCharset",
                                                charset,
                                            ) {
                                                tracing::warn!(
                                                    error = %error,
                                                    "failed to save selected language charset"
                                                );
                                            }
                                        }
                                    }
                                    Err(error) => tracing::error!(
                                        error = %error,
                                        "failed to reload selected application language"
                                    ),
                                }
                                self.open_options_menu();
                            }
                            Some(Err(error)) => tracing::warn!(
                                error = %error,
                                "failed to save selected options language"
                            ),
                            None => {
                                let _ = self.reload_application_language_resources();
                                self.open_options_menu();
                            }
                        }
                    }
                    AppContextMenuCommand::ScenarioSearch(command) => {
                        self.execute_scenario_search_context_command(command)?;
                    }
                    AppContextMenuCommand::InputDialog(command) => {
                        self.apply_input_dialog_context_command(command)?;
                    }
                },
            }
        }
        Ok(())
    }

    fn set_startup_participant(&mut self, reference: &str, active: bool) {
        let Some(paths) = self.app_paths.as_ref() else {
            tracing::error!(
                reference,
                "cannot update participant without application paths"
            );
            self.status_text = "Unable to update participants".to_string();
            return;
        };
        let result = update_startup_participant_config(paths, |entries| {
            if active {
                if !entries
                    .iter()
                    .any(|entry| entry.eq_ignore_ascii_case(reference))
                {
                    entries.push(reference.to_string());
                }
            } else {
                entries.retain(|entry| !entry.eq_ignore_ascii_case(reference));
            }
        });
        self.finish_startup_participant_update(result, reference);
    }

    fn remove_startup_participant(&mut self, raw_index: usize) {
        let Some(paths) = self.app_paths.as_ref() else {
            tracing::error!(
                raw_index,
                "cannot remove participant without application paths"
            );
            self.status_text = "Unable to update participants".to_string();
            return;
        };
        match remove_startup_participant_config(paths, raw_index) {
            Ok(removed) => self.finish_startup_participant_update(
                Ok(()),
                removed.as_deref().unwrap_or("<stale participant>"),
            ),
            Err(error) => self.finish_startup_participant_update(
                Err(error),
                "<unreadable participant configuration>",
            ),
        }
    }

    fn finish_startup_participant_update(&mut self, result: io::Result<()>, reference: &str) {
        match result {
            Ok(()) => {
                self.sync_startup_participant_models();
                self.refresh_participants_label();
                self.status_text.clear();
                self.mark_menu_dirty();
            }
            Err(error) => {
                tracing::error!(reference, %error, "failed to update startup participants");
                self.status_text = format!("Unable to update participants: {error}");
            }
        }
    }

    fn poll_startup_game_search(&mut self) {
        let events = self
            .startup_game_search
            .as_ref()
            .map(|search| search.events().try_iter().collect::<Vec<_>>())
            .unwrap_or_default();
        if events.is_empty() {
            return;
        }
        for event in events {
            match event {
                lc_network::StartupGameSearchEvent::Cleared => {
                    self.startup_game_references.clear();
                    if let Some(dialog) = self.startup_network_dialog.as_mut() {
                        dialog.set_games(Vec::new());
                    }
                    self.status_text = "Querying game infos…".to_string();
                }
                lc_network::StartupGameSearchEvent::ReferencesUpdated(references) => {
                    let games = references
                        .iter()
                        .map(|reference| {
                            let host = if reference.host_name.is_empty() {
                                "unknown"
                            } else {
                                reference.host_name.as_str()
                            };
                            let title = format!("{} on {host}", reference.title);
                            let details = format!(
                                "{} — {} {}.{}.{}.{} [{}]",
                                reference.state,
                                reference.game,
                                reference.version[0],
                                reference.version[1],
                                reference.version[2],
                                reference.version[3],
                                reference.build,
                            );
                            lc_frontend::startup_netdlg::NetDlgGameEntry {
                                title,
                                details,
                                address: reference.tcp_addresses.first().map(ToString::to_string),
                                joinable: reference.is_joinable(),
                            }
                        })
                        .collect::<Vec<_>>();
                    self.startup_game_references = references;
                    let count = games.len();
                    if let Some(dialog) = self.startup_network_dialog.as_mut() {
                        dialog.set_games(games);
                    }
                    self.status_text = format!("Found {count} network game(s)");
                }
                lc_network::StartupGameSearchEvent::SearchError { source, message } => {
                    tracing::warn!(?source, %message, "network game search failed");
                    self.status_text = message;
                }
            }
        }
        self.mark_menu_dirty();
    }

    fn sync_startup_participant_models(&mut self) {
        let active = self
            .app_paths
            .as_ref()
            .and_then(|paths| startup_participant_references(paths).ok())
            .unwrap_or_default();
        for (file, model) in self
            .startup_player_files
            .iter_mut()
            .zip(self.startup_player_models.iter_mut())
        {
            let enabled = active
                .iter()
                .any(|entry| entry.eq_ignore_ascii_case(&file.file_name));
            file.set_activated(enabled);
            model.activated = enabled;
        }
        self.selected_player_file = active.iter().find_map(|reference| {
            self.startup_player_files
                .iter()
                .find(|player| player.file_name.eq_ignore_ascii_case(reference))
                .map(|player| player.player_file.clone())
        });
        if let Some(dialog) = self.startup_player_dialog.as_mut() {
            dialog.set_player_activations(
                self.startup_player_models
                    .iter()
                    .map(|player| player.activated)
                    .collect(),
            );
        }
    }

    fn handle_context_menu_pointer_move(&mut self, point: GuiPoint) -> Result<bool, EngineError> {
        let Some(menu) = self.context_menu.as_mut() else {
            return Ok(false);
        };
        let outcome = menu.handle_pointer_move(point);
        let captured = outcome.captured && !outcome.pass_through;
        self.process_context_menu_outcome(outcome)?;
        Ok(captured)
    }

    fn consume_closed_context_pointer_release(
        &mut self,
        state: ElementState,
        button: ContextMenuPointerButton,
    ) -> bool {
        if state == ElementState::Released
            && self.context_menu.is_none()
            && self.context_menu_pointer_capture == Some(button)
        {
            self.context_menu_pointer_capture = None;
            return true;
        }
        false
    }

    fn handle_context_menu_pointer_button(
        &mut self,
        state: ElementState,
        button: ContextMenuPointerButton,
    ) -> Result<bool, EngineError> {
        let retained_release =
            state == ElementState::Released && self.context_menu_pointer_capture == Some(button);
        if retained_release {
            self.context_menu_pointer_capture = None;
        }
        let Some(menu) = self.context_menu.as_mut() else {
            return Ok(retained_release);
        };
        let point = menu.pointer_position();
        let outcome = match state {
            ElementState::Pressed => menu.handle_pointer_down(point, button),
            ElementState::Released => menu.handle_pointer_up(point, button),
        };
        let captured = outcome.captured && !outcome.pass_through;
        if state == ElementState::Pressed && captured {
            self.context_menu_pointer_capture = Some(button);
        }
        self.process_context_menu_outcome(outcome)?;
        Ok(captured || retained_release)
    }

    fn handle_context_menu_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.context_menu.is_none() {
            return Ok(false);
        }
        if state == ElementState::Released {
            return Ok(false);
        }
        let outcome = {
            let menu = self.context_menu.as_mut().expect("checked above");
            menu.note_non_pointer_input();
            if let Some(key) = context_menu_key_code(key) {
                menu.handle_key(key)
            } else if let Some(hotkey) = context_menu_hotkey(key) {
                menu.handle_hotkey(hotkey)
            } else {
                return Ok(false);
            }
        };
        let captured = outcome.captured && !outcome.pass_through;
        if captured {
            self.message_dialog_consumed_keys.insert(key);
        }
        self.process_context_menu_outcome(outcome)?;
        Ok(captured)
    }

    fn handle_context_menu_gamepad_event(
        &mut self,
        event: GamepadEvent,
    ) -> Result<bool, EngineError> {
        let outcome = self.context_menu.as_mut().and_then(|menu| {
            menu.note_non_pointer_input();
            match event {
                GamepadEvent::Direction {
                    button,
                    state: ElementState::Pressed,
                    ..
                } => Some(menu.handle_gamepad_direction(match button {
                    ControlButton::Up => ContextMenuDirection::Up,
                    ControlButton::Down => ContextMenuDirection::Down,
                    ControlButton::Left => ContextMenuDirection::Left,
                    ControlButton::Right => ContextMenuDirection::Right,
                })),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::Low,
                    state: ElementState::Pressed,
                    ..
                } => Some(menu.handle_gamepad_low()),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::High,
                    state: ElementState::Pressed,
                    ..
                } => Some(menu.handle_gamepad_high()),
                GamepadEvent::Clear { .. } => Some(menu.dismiss(false)),
                GamepadEvent::Direction { .. }
                | GamepadEvent::Button { .. }
                | GamepadEvent::Action { .. }
                | GamepadEvent::GuiButton { .. } => None,
            }
        });
        if let Some(outcome) = outcome {
            let captured = outcome.captured && !outcome.pass_through;
            self.process_context_menu_outcome(outcome)?;
            return Ok(captured);
        }
        Ok(false)
    }

    fn close_context_menu_silently(&mut self) {
        let Some(mut menu) = self.context_menu.take() else {
            return;
        };
        let _ = menu.dismiss(false);
        self.context_menu_pointer_capture = None;
        self.mark_menu_dirty();
    }

    fn process_player_dialog_actions(
        &mut self,
        actions: Vec<lc_frontend::startup_plrsel::PlrSelAction>,
    ) -> Result<(), EngineError> {
        use lc_frontend::startup_plrsel::PlrSelAction;

        for action in actions {
            match action {
                PlrSelAction::SelectionChanged(_) | PlrSelAction::FocusChanged(_) => {}
                PlrSelAction::Back => self.show_main_menu(),
                PlrSelAction::NewPlayer => {
                    return Err(classic_startup_action_error(
                        ClassicStartupAction::PlayerNew,
                    ));
                }
                PlrSelAction::ActivationChanged { index, activated } => {
                    let selected_before = self
                        .startup_player_dialog
                        .as_ref()
                        .and_then(|dialog| dialog.selected_index());
                    let old_activated = self
                        .startup_player_models
                        .get(index)
                        .map(|player| player.activated);
                    if let Some(player) = self.startup_player_files.get_mut(index) {
                        player.set_activated(activated);
                    }
                    if let Some(player) = self.startup_player_models.get_mut(index) {
                        player.activated = activated;
                    }
                    let persisted = self
                        .app_paths
                        .as_ref()
                        .ok_or_else(|| "application paths are unavailable".to_string())
                        .and_then(|paths| {
                            persist_activations(&paths.config_file(), &self.startup_player_files)
                                .map_err(|error| error.to_string())
                        });
                    match persisted {
                        Ok(()) => {
                            self.selected_player_file = self
                                .startup_player_files
                                .iter()
                                .find(|player| player.render_model.activated)
                                .map(|player| player.player_file.clone());
                            self.refresh_participants_label();
                            self.status_text.clear();
                        }
                        Err(error) => {
                            if let Some(old_activated) = old_activated {
                                if let Some(player) = self.startup_player_files.get_mut(index) {
                                    player.set_activated(old_activated);
                                }
                                if let Some(player) = self.startup_player_models.get_mut(index) {
                                    player.activated = old_activated;
                                }
                                if let Some(dialog) = self.startup_player_dialog.as_mut() {
                                    dialog.set_player_activations(
                                        self.startup_player_models
                                            .iter()
                                            .map(|player| player.activated)
                                            .collect(),
                                    );
                                    dialog.set_selected_index(selected_before);
                                }
                            }
                            self.status_text = format!("Unable to save player selection: {error}");
                        }
                    }
                }
                PlrSelAction::DeletePlayer(index) => {
                    self.open_startup_player_delete_dialog(index, true)?;
                }
                PlrSelAction::PlayerProperties(index) => {
                    return Err(classic_startup_action_error(
                        ClassicStartupAction::PlayerProperties { index },
                    ));
                }
                PlrSelAction::ShowCrew(index) => {
                    return Err(classic_startup_action_error(
                        ClassicStartupAction::PlayerCrew { index },
                    ));
                }
            }
        }
        Ok(())
    }

    fn open_startup_player_delete_dialog(
        &mut self,
        index: usize,
        play_source_click: bool,
    ) -> Result<(), EngineError> {
        let delete = self
            .startup_player_files
            .get(index)
            .zip(self.startup_player_models.get(index))
            .map(|(player_file, player)| {
                (
                    player_file.path.clone(),
                    lc_frontend::startup_plrsel::player_delete_warning(player),
                )
            });
        let Some((path, warning)) = delete else {
            tracing::error!(index, "player-delete action references a stale row");
            return Ok(());
        };
        if play_source_click {
            self.play_ui_sound("Click");
        }
        self.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::new(
                warning,
                "Delete",
                lc_frontend::message_dialog::MessageDialogButtons::YES_NO,
                lc_frontend::message_dialog::MessageDialogIcon::CONFIRM,
                lc_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::DeleteStartupPlayer { path },
        )
    }

    fn process_options_dialog_actions(
        &mut self,
        actions: Vec<lc_frontend::startup_options_dlg::OptionsDlgAction>,
    ) -> Result<(), EngineError> {
        use lc_frontend::startup_options_dlg::{
            OptionsDlgAction, SoundCheckboxId, SoundSheetAction, SoundVolumeId,
        };

        for action in actions {
            match action {
                OptionsDlgAction::Back => self.close_options_menu(),
                OptionsDlgAction::SheetChanged(
                    lc_frontend::startup_options_dlg::OptionsSheet::Program,
                ) => self.play_ui_sound("Command"),
                OptionsDlgAction::SheetChanged(
                    lc_frontend::startup_options_dlg::OptionsSheet::Sound,
                ) => {
                    if self.audio.is_none() {
                        return Err(classic_parity_engine_error(report_classic_parity_boundary(
                            ClassicParityBoundary::RuntimeAudioSystem {
                                action: "the startup Options Sound sheet",
                            },
                        )));
                    }
                    self.play_ui_sound("Command");
                }
                OptionsDlgAction::SheetChanged(sheet) => {
                    return Err(classic_startup_subscreen_error(
                        ClassicStartupSubscreen::Options(sheet),
                    ));
                }
                OptionsDlgAction::ShowLogTimestampsChanged(enabled) => {
                    self.show_log_timestamps = enabled;
                    self.play_ui_sound("ArrowHit");
                }
                OptionsDlgAction::OpenLanguageCombo => {
                    self.open_options_language_combo()?;
                }
                OptionsDlgAction::Sound(action) => match action {
                    SoundSheetAction::GuiSound(sound) | SoundSheetAction::TestSound(sound) => {
                        self.play_options_sound(sound);
                    }
                    SoundSheetAction::CheckboxChanged { id, checked } => match id {
                        SoundCheckboxId::FrontendMusic => {
                            self.set_frontend_music_option(checked)?;
                        }
                        SoundCheckboxId::FrontendSoundEffects => {
                            self.set_frontend_sound_option(checked)?;
                        }
                        SoundCheckboxId::GameMusic => {
                            self.set_startup_game_music_option(checked)?;
                        }
                        SoundCheckboxId::GameSoundEffects => {
                            self.set_startup_game_sound_option(checked)?;
                        }
                    },
                    SoundSheetAction::VolumeChanged { id, value } => match id {
                        SoundVolumeId::Music => {
                            self.set_startup_music_volume(i32::from(value))?;
                        }
                        SoundVolumeId::SoundEffects => {
                            self.set_startup_sound_volume(i32::from(value))?;
                        }
                    },
                },
                OptionsDlgAction::UnsupportedProgramFocus(target) => {
                    return Err(classic_startup_action_error(
                        ClassicStartupAction::OptionsProgramFocus(target),
                    ));
                }
            }
        }
        Ok(())
    }

    fn play_options_sound(&mut self, sound: lc_frontend::startup_options_dlg::SoundSheetSound) {
        self.play_ui_sound(match sound {
            lc_frontend::startup_options_dlg::SoundSheetSound::ArrowHit => "ArrowHit",
            lc_frontend::startup_options_dlg::SoundSheetSound::Command => "Command",
        });
    }

    fn process_about_dialog_actions(
        &mut self,
        actions: Vec<lc_frontend::startup_about_dlg::AboutDlgAction>,
    ) -> Result<(), EngineError> {
        use lc_frontend::startup_about_dlg::AboutDlgAction;

        for action in actions {
            match action {
                AboutDlgAction::Back => self.show_main_menu(),
                AboutDlgAction::CheckForUpdates => {
                    return Err(classic_startup_action_error(
                        ClassicStartupAction::AboutCheckForUpdates,
                    ));
                }
                AboutDlgAction::PageChanged(_) => self.play_ui_sound("Click"),
                AboutDlgAction::LicenseChanged(_) => self.play_ui_sound("Command"),
            }
        }
        Ok(())
    }

    fn start_network_game_now(&mut self) -> Result<(), EngineError> {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            self.status_text = "Only the host can start the game".to_string();
            return Ok(());
        }
        let prepared = self.network_mode.as_ref().and_then(|mode| match mode {
            NetworkMode::Host(HostSettings {
                prepared: Some(prepared),
                ..
            }) => Some(prepared.clone()),
            NetworkMode::Host(_) | NetworkMode::Client(_) => None,
        });
        if let Some(prepared) = prepared {
            let Some((
                restore_player_infos,
                random_seed,
                use_fair_crew,
                fair_crew_strength,
                fair_crew_forced,
                allow_debug,
                team_configuration,
                team_registry,
            )) = self
                .host_join_snapshot
                .as_ref()
                .or_else(|| prepared.host_config().initial_join_snapshot.as_ref())
                .map(|snapshot| {
                    (
                        player_info_list_entries(&snapshot.parameters.restore_player_infos)
                            .collect::<Vec<_>>(),
                        u64::from(snapshot.parameters.random_seed as u32),
                        snapshot.parameters.use_fair_crew,
                        snapshot.parameters.fair_crew_strength,
                        snapshot.parameters.fair_crew_forced,
                        snapshot.parameters.allow_debug,
                        synchronized_team_configuration(&snapshot.parameters),
                        runtime_teams_from_join_snapshot(&snapshot.parameters.teams),
                    )
                })
            else {
                self.status_text =
                    "Unable to start prepared host: initial JoinData is missing".to_string();
                return Ok(());
            };
            // C++ leaves the lobby through Network.Start: close or
            // preserve admission from NoRuntimeJoin, commit GS_Go,
            // and initialize the already-opened scenario
            // (src/C4Network2.cpp:510-530;
            // src/C4GameLobby.cpp:442-472). Reopening the source here
            // would diverge from the JoinData already sent to peers.
            let Some(lobby) = self.network_lobby.as_ref() else {
                return Ok(());
            };
            let Some(identifier) = lobby.selected_identifier() else {
                self.status_text = "Select a scenario before starting".to_string();
                return Ok(());
            };
            let scenario = match self.scenario_catalog.get(identifier).cloned() {
                Some(scenario) => scenario,
                None => {
                    self.status_text =
                        format!("Scenario `{identifier}` is not available in the catalog");
                    return Ok(());
                }
            };
            let scenario_data = match prepared.claim_scenario() {
                Ok(scenario) => scenario,
                Err(error) => {
                    self.status_text = format!("Unable to start prepared host: {error}");
                    return Ok(());
                }
            };
            let target_tick =
                i32::try_from(self.local_control_submission_tick()).unwrap_or(i32::MAX);
            let status = lc_network::NetworkStatus {
                state: lc_network::NETWORK_STATE_GO,
                control_mode: prepared.host_config().initial_status.control_mode,
                target_tick,
            };
            let Some(network) = self.network.as_ref() else {
                self.status_text = "Prepared host network is unavailable".to_string();
                return Ok(());
            };
            if let Err(error) = network.change_status(status) {
                self.status_text = format!("Unable to start prepared host: {error}");
                return Ok(());
            }
            if let Some(clock) = self.network_control_clock.as_mut() {
                clock.set_target_tick(Some(target_tick));
            }
            self.play_ui_sound("Click");
            self.fade_out_game_music();
            self.status_text.clear();
            self.loading_state = Some(ScenarioLoadingState::from_loaded(
                scenario,
                scenario_data,
                status,
                restore_player_infos,
                random_seed,
                use_fair_crew,
                fair_crew_strength,
                fair_crew_forced,
                allow_debug,
                team_configuration,
                team_registry,
            ));
            self.mode = AppMode::Loading;
            return Ok(());
        }
        let Some(lobby) = self.network_lobby.as_ref() else {
            return Ok(());
        };
        let Some(identifier) = lobby.selected_identifier() else {
            self.status_text = "Select a scenario before starting".to_string();
            return Ok(());
        };
        let scenario = match self.scenario_catalog.get(identifier).cloned() {
            Some(scenario) => scenario,
            None => {
                self.status_text =
                    format!("Scenario `{}` is not available in the catalog", identifier);
                return Ok(());
            }
        };
        self.play_ui_sound("Click");
        self.start_scenario(scenario)?;
        Ok(())
    }

    fn network_game_start_guard_passes(&mut self) -> bool {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            self.status_text = "Only the host can start the game".to_string();
            return false;
        }
        if self.network_mode.as_ref().is_some_and(|mode| match mode {
            NetworkMode::Host(HostSettings {
                prepared: Some(prepared),
                ..
            }) => prepared.host_config().initial_join_snapshot.is_none(),
            NetworkMode::Host(_) | NetworkMode::Client(_) => false,
        }) {
            self.status_text =
                "Unable to start prepared host: initial JoinData is missing".to_string();
            return false;
        }
        let Some(lobby) = self.network_lobby.as_ref() else {
            return false;
        };
        let Some(identifier) = lobby.selected_identifier() else {
            self.status_text = "Select a scenario before starting".to_string();
            return false;
        };
        if !self.scenario_catalog.contains_key(identifier) {
            self.status_text = format!("Scenario `{identifier}` is not available in the catalog");
            return false;
        }
        true
    }

    fn start_network_lobby_countdown(&mut self) -> Result<(), EngineError> {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            self.network_game_start_guard_passes();
            return Ok(());
        }
        if self.abort_network_lobby_countdown() {
            return Ok(());
        }
        if !self.network_game_start_guard_passes() {
            return Ok(());
        }
        let Some(network) = self.network.as_ref() else {
            return self.start_network_game_now();
        };
        self.host_lobby_countdown = Some(HostLobbyCountdown::new());
        let packet = lc_network::LobbyCountdownPacket::new(DEFAULT_LOBBY_COUNTDOWN_SECONDS);
        if let Err(error) = network.submit_lobby_countdown(packet) {
            tracing::error!(%error, "failed to submit host lobby countdown");
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.apply_lobby_countdown(packet);
        }
        Ok(())
    }

    fn abort_network_lobby_countdown(&mut self) -> bool {
        if self.host_lobby_countdown.take().is_none() {
            return false;
        }
        let packet = lc_network::LobbyCountdownPacket::new(lc_network::LobbyCountdownPacket::ABORT);
        if let Some(Err(error)) = self
            .network
            .as_ref()
            .map(|network| network.submit_lobby_countdown(packet))
        {
            tracing::error!(%error, "failed to abort host lobby countdown");
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.apply_lobby_countdown(packet);
        }
        true
    }

    fn request_lobby_ready_check_at(&mut self, now: Instant) -> Result<bool, EngineError> {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return Ok(false);
        }
        if !self.lobby_ready_check_cooldown.try_reset_at(now) {
            let remaining = self.lobby_ready_check_cooldown.remaining_seconds_at(now);
            self.status_text = format!("Too early! Please wait {remaining} seconds.");
            return Ok(false);
        }
        self.abort_network_lobby_countdown();
        if let Some(lobby) = self.network_lobby.as_mut() {
            for (client_id, participant) in &mut lobby.participants {
                if *client_id != 0 {
                    participant.ready = false;
                }
            }
        }
        if self.control_clients.clear_nonhost_lobby_ready() {
            self.publish_updated_host_join_snapshot();
        }
        if let Some(Err(error)) = self
            .network
            .as_ref()
            .map(|network| network.submit_ready_check(lc_network::ReadyCheckData::Request))
        {
            tracing::error!(%error, "failed to submit lobby ready check request");
        }
        Ok(true)
    }

    fn handle_lobby_ready_check_request(
        &mut self,
        packet: lc_network::ReadyCheckPacket,
    ) -> Result<(), EngineError> {
        if self.message_dialogs.iter().any(|dialog| {
            matches!(
                &dialog.continuation,
                MessageDialogContinuation::LobbyReadyCheck { .. }
            )
        }) {
            return Ok(());
        }
        if !matches!(self.network_mode, Some(NetworkMode::Client(_))) || packet.client_id != 0 {
            return Ok(());
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            for (client_id, participant) in &mut lobby.participants {
                if *client_id != 0 {
                    participant.ready = false;
                }
            }
        }
        if !self.admission_resources.lobby_ready_available() {
            if let Some(Err(error)) = self
                .network
                .as_ref()
                .map(|network| network.submit_ready_check(lc_network::ReadyCheckData::NotReady))
            {
                tracing::error!(%error, "failed to submit lobby ready check response");
            }
            return Ok(());
        }
        let remaining_seconds = LOBBY_READY_CHECK_PROMPT_SECONDS;
        self.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::new(
                lobby_ready_check_message(remaining_seconds),
                "Are you ready?",
                lc_frontend::message_dialog::MessageDialogButtons::YES_NO,
                lc_frontend::message_dialog::MessageDialogIcon::Standard(30),
                lc_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            )
            .with_centered_message()
            .without_focus(),
            MessageDialogContinuation::LobbyReadyCheck { remaining_seconds },
        )?;
        Ok(())
    }

    fn on_lobby_client_ready_state_change(
        &mut self,
        changed_client_id: ClientId,
    ) -> Result<(), EngineError> {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return Ok(());
        }
        let player_infos = &self.control_player_infos;
        let first_relevant_unready = self.network_lobby.as_ref().and_then(|lobby| {
            lobby
                .participants
                .iter()
                .find_map(|(client_id, participant)| {
                    let relevant = *client_id == 0
                        || i32::try_from(*client_id).ok().is_some_and(|client_id| {
                            !player_infos.client_info_ids(client_id).is_empty()
                        });
                    (relevant && !participant.ready).then_some(*client_id)
                })
        });
        if let Some(unready_client_id) = first_relevant_unready {
            if unready_client_id == changed_client_id {
                self.abort_network_lobby_countdown();
            }
            return Ok(());
        }
        if self.host_lobby_countdown.is_none() {
            self.start_network_lobby_countdown()?;
        }
        Ok(())
    }

    fn handle_network_lobby_chat_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.startup_view != StartupView::NetworkLobby
            || self.classic_host_lobby_active()
            || self.network_lobby.is_none()
        {
            return Ok(false);
        }
        let modifiers = LobbyChatKeyModifiers {
            shift: self.keyboard_modifiers.shift(),
            control: self.keyboard_modifiers.ctrl(),
        };
        let clipboard = modifiers.control.then(|| match key {
            VirtualKeyCode::C => Some(LobbyChatClipboardShortcut::Copy),
            VirtualKeyCode::X => Some(LobbyChatClipboardShortcut::Cut),
            VirtualKeyCode::V => Some(LobbyChatClipboardShortcut::Paste),
            VirtualKeyCode::A => Some(LobbyChatClipboardShortcut::SelectAll),
            _ => None,
        });
        let edit = match key {
            VirtualKeyCode::Left => Some(LobbyChatEditKey::Left),
            VirtualKeyCode::Right => Some(LobbyChatEditKey::Right),
            VirtualKeyCode::Home => Some(LobbyChatEditKey::Home),
            VirtualKeyCode::End => Some(LobbyChatEditKey::End),
            VirtualKeyCode::Back => Some(LobbyChatEditKey::Backspace),
            VirtualKeyCode::Delete => Some(LobbyChatEditKey::Delete),
            _ => None,
        };
        let recognized = clipboard.flatten().is_some()
            || edit.is_some()
            || matches!(
                key,
                VirtualKeyCode::Return
                    | VirtualKeyCode::NumpadEnter
                    | VirtualKeyCode::Up
                    | VirtualKeyCode::Down
            );
        if !recognized {
            return Ok(false);
        }
        if state == ElementState::Released {
            return Ok(true);
        }
        if let Some(shortcut) = clipboard.flatten() {
            let Some(lobby) = self.network_lobby.as_mut() else {
                return Ok(true);
            };
            match shortcut {
                LobbyChatClipboardShortcut::Copy | LobbyChatClipboardShortcut::Cut => {
                    if let Some(range) = lobby_chat_selection(&lobby.chat_edit) {
                        let selected = lobby.chat_edit.text[range].to_string();
                        let copied = arboard::Clipboard::new()
                            .and_then(|mut clipboard| clipboard.set_text(selected))
                            .is_ok();
                        if copied && shortcut == LobbyChatClipboardShortcut::Cut {
                            lobby_chat_delete_selection(&mut lobby.chat_edit);
                        }
                    }
                }
                LobbyChatClipboardShortcut::Paste => {
                    if let Ok(text) =
                        arboard::Clipboard::new().and_then(|mut clipboard| clipboard.get_text())
                    {
                        lobby_chat_insert_text(&mut lobby.chat_edit, &text);
                    }
                }
                LobbyChatClipboardShortcut::SelectAll => {
                    lobby.chat_edit.caret = lobby.chat_edit.text.len();
                    lobby.chat_edit.selection = (!lobby.chat_edit.text.is_empty())
                        .then_some((0, lobby.chat_edit.caret));
                }
            }
            return Ok(true);
        }
        if let Some(edit) = edit {
            if let Some(lobby) = self.network_lobby.as_mut() {
                lobby_chat_apply_edit_key(&mut lobby.chat_edit, edit, modifiers);
            }
            return Ok(true);
        }
        match key {
            VirtualKeyCode::Return | VirtualKeyCode::NumpadEnter => {
                let text = self
                    .network_lobby
                    .as_mut()
                    .map(NetworkLobbyState::take_chat_submission)
                    .unwrap_or_default();
                self.process_lobby_action(LobbyAction::SubmitMessage(text))?;
            }
            VirtualKeyCode::Up | VirtualKeyCode::Down => {
                let history = self.message_input_history.clone();
                if let Some(lobby) = self.network_lobby.as_mut() {
                    lobby.browse_chat_history(key == VirtualKeyCode::Up, &history);
                }
            }
            _ => {}
        }
        Ok(true)
    }

    fn process_lobby_action(&mut self, action: LobbyAction) -> Result<(), EngineError> {
        match action {
            LobbyAction::ToggleReady => {
                if !self.admission_resources.lobby_ready_available() {
                    return Ok(());
                }
                if let Some((changed_client_id, ready)) =
                    self.network_lobby.as_mut().and_then(|lobby| {
                        let client_id = lobby.local_client_id;
                        lobby
                            .participants
                            .contains_key(&client_id)
                            .then(|| (client_id, lobby.toggle_local_ready()))
                    })
                {
                    let data = if ready {
                        lc_network::ReadyCheckData::Ready
                    } else {
                        lc_network::ReadyCheckData::NotReady
                    };
                    if i32::try_from(changed_client_id)
                        .ok()
                        .is_some_and(|client_id| {
                            self.control_clients.set_lobby_ready(client_id, ready)
                        })
                    {
                        self.publish_updated_host_join_snapshot();
                    }
                    if let Some(Err(error)) = self
                        .network
                        .as_ref()
                        .map(|network| network.submit_ready_check(data))
                    {
                        tracing::error!(%error, "failed to submit lobby ready state");
                    }
                    self.status_text = if ready {
                        "You are ready".to_string()
                    } else {
                        "You are not ready".to_string()
                    };
                    self.on_lobby_client_ready_state_change(changed_client_id)?;
                }
            }
            LobbyAction::StartGame => self.start_network_lobby_countdown()?,
            LobbyAction::SubmitMessage(text) => {
                self.store_message_input_history(&text);
                if self.process_control_message_local_command(&text) {
                    return Ok(());
                }
                if is_team_message_syntax(&text) && self.engine.team_distribution() == 4 {
                    self.append_control_message_log(
                        "Can't send team message: Teams not known.".to_string(),
                        CONTROL_LOG_COLOR,
                        None,
                    );
                    return Ok(());
                }
                let control = match parse_lobby_message_control(&text) {
                    Ok(control) => control,
                    Err(error) => {
                        tracing::warn!(%error, "classic lobby chat command is not implemented");
                        self.append_control_message_log(
                            "Unknown command.".to_string(),
                            0x00ff_1f1f,
                            None,
                        );
                        return Ok(());
                    }
                };
                if let Some(control) = control {
                    if let Some(Err(error)) = self
                        .network
                        .as_ref()
                        .map(|network| network.submit_message(control))
                    {
                        tracing::error!(%error, "failed to submit classic lobby message");
                    }
                }
            }
            LobbyAction::ChatEdited => {}
        }
        Ok(())
    }

    fn classic_host_lobby_layouts(
        &mut self,
    ) -> std::result::Result<(LobbyLayout, LobbyRosterLayout), EngineError> {
        let fonts = self.assets.clonk_fonts.clone().ok_or_else(|| {
            classic_parity_engine_error(report_classic_parity_boundary(
                ClassicParityBoundary::GameLobby(ClassicGameLobbyBoundary::Resources {
                    detail: "CStdFont-faithful lobby fonts are unavailable".to_string(),
                }),
            ))
        })?;
        let surface = self.graphics.surface();
        let (width, height) = (surface.width() as i32, surface.height() as i32);
        let state = self.classic_host_lobby.as_mut().ok_or_else(|| {
            classic_parity_engine_error(report_classic_parity_boundary(
                ClassicParityBoundary::GameLobby(ClassicGameLobbyBoundary::Model {
                    detail: "exact host lobby state is absent".to_string(),
                }),
            ))
        })?;
        let layout = state.controller.layout(width, height, &fonts);
        let _ = state.controller.chat_scroll_metrics(&layout, &fonts.text);
        let roster = state
            .controller
            .roster_layout(&layout, fonts.text.line_height);
        Ok((layout, roster))
    }

    fn play_classic_lobby_sounds(&mut self) {
        let sounds = self
            .classic_host_lobby
            .as_mut()
            .map(|state| state.controller.take_sounds())
            .unwrap_or_default();
        for sound in sounds {
            self.play_ui_sound(match sound {
                LobbySound::ArrowHit => "ArrowHit",
                LobbySound::Click => "Click",
                LobbySound::Command => "Command",
                LobbySound::Fuse => "Fuse",
                LobbySound::StartElevatorLoop | LobbySound::StopElevatorLoop => "Elevator",
                LobbySound::Pshshsh => "Pshshsh",
                LobbySound::Blast3 => "Blast3",
            });
        }
        let option_sounds = self.scenario_game_options.take_sound_events();
        self.play_game_option_sound_events(option_sounds);
    }

    fn cancel_classic_host_lobby_interaction(&mut self) -> bool {
        let Some(lobby) = self.classic_host_lobby.as_mut() else {
            return false;
        };
        lobby.pointer = None;
        lobby.controller.cancel_interaction();
        self.scenario_game_options.cancel_interaction();
        self.play_classic_lobby_sounds();
        self.mark_menu_dirty();
        true
    }

    fn classic_host_lobby_pointer_left(&mut self) -> bool {
        let Some(lobby) = self.classic_host_lobby.as_mut() else {
            return false;
        };
        lobby.pointer = None;
        lobby.controller.pointer_left();
        self.scenario_game_options.pointer_left();
        self.play_classic_lobby_sounds();
        self.mark_menu_dirty();
        true
    }

    fn route_classic_lobby_game_option_input(
        &mut self,
        input: LobbyGameOptionInput,
    ) -> Result<Vec<ClassicLobbyAction>, EngineError> {
        let previous_focus = self.scenario_game_options.focused_button();
        let mut unhandled = false;
        let option_actions = match input {
            LobbyGameOptionInput::PointerMove(point) => {
                self.scenario_game_options.handle_pointer_move(point)
            }
            LobbyGameOptionInput::PointerDown(point) => {
                self.scenario_game_options.handle_pointer_down(point)
            }
            LobbyGameOptionInput::PointerUp(point) => {
                self.scenario_game_options.handle_pointer_up(point)
            }
            LobbyGameOptionInput::MouseLeave => {
                self.scenario_game_options.pointer_left();
                Vec::new()
            }
            LobbyGameOptionInput::TouchCancel => {
                self.scenario_game_options.handle_touch_cancel();
                Vec::new()
            }
            LobbyGameOptionInput::Focus(button) => {
                self.scenario_game_options.set_focused_button(Some(button));
                Vec::new()
            }
            LobbyGameOptionInput::ClearFocus => {
                self.scenario_game_options.set_focused_button(None);
                Vec::new()
            }
            LobbyGameOptionInput::KeyDown { key, shift } => {
                let outcome = self
                    .scenario_game_options
                    .handle_key_down_with_tab_direction(key, shift);
                unhandled = !outcome.captured;
                outcome.actions
            }
            LobbyGameOptionInput::KeyUp(key) => {
                let outcome = self.scenario_game_options.handle_key_up(key);
                unhandled = !outcome.captured;
                outcome.actions
            }
            LobbyGameOptionInput::Hotkey(hotkey) => {
                self.scenario_game_options.handle_hotkey(hotkey)
            }
            LobbyGameOptionInput::GamepadLowDown => {
                let outcome = self.scenario_game_options.handle_gamepad_low_down();
                unhandled = !outcome.captured;
                outcome.actions
            }
            LobbyGameOptionInput::GamepadLowUp => {
                let outcome = self.scenario_game_options.handle_gamepad_low_up();
                unhandled = !outcome.captured;
                outcome.actions
            }
            LobbyGameOptionInput::GamepadDirection {
                horizontal,
                vertical,
            } => {
                let direction = if horizontal < 0 {
                    GameOptionGamepadDirection::Left
                } else if horizontal > 0 {
                    GameOptionGamepadDirection::Right
                } else if vertical < 0 {
                    GameOptionGamepadDirection::Up
                } else {
                    GameOptionGamepadDirection::Down
                };
                let outcome = self
                    .scenario_game_options
                    .handle_gamepad_direction(direction);
                unhandled = !outcome.captured;
                outcome.actions
            }
        };

        let mut lobby_actions = Vec::new();
        for action in option_actions {
            match action {
                GameOptionAction::FocusTraversalRequested { backwards } => {
                    lobby_actions.extend(
                        self.classic_host_lobby
                            .as_mut()
                            .map(|state| {
                                state
                                    .controller
                                    .game_option_focus_traversal_requested(backwards)
                            })
                            .unwrap_or_default(),
                    );
                }
                GameOptionAction::InternetSignupChanged { .. } => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::GameOptionSideEffect("Internet signup"),
                    ));
                }
                GameOptionAction::LeagueSignupChanged(_) => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::GameOptionSideEffect("League signup"),
                    ));
                }
                GameOptionAction::ShowInputDialog(_) => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::GameOptionSideEffect("Password/Comment dialog"),
                    ));
                }
                GameOptionAction::PasswordChanged { .. } => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::GameOptionSideEffect("Password mutation"),
                    ));
                }
                GameOptionAction::CommentChanged(_) => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::GameOptionSideEffect("Comment mutation"),
                    ));
                }
                GameOptionAction::FairCrewPreferenceChanged(_)
                | GameOptionAction::SendLobbyFairCrewControl { .. } => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::GameOptionSideEffect("FairCrew control"),
                    ));
                }
                GameOptionAction::RecordPreferenceChanged(_) => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::GameOptionSideEffect("Record preference"),
                    ));
                }
            }
        }
        let focused = self.scenario_game_options.focused_button();
        if focused != previous_focus {
            if let Some(button) = focused {
                let actions = self
                    .classic_host_lobby
                    .as_mut()
                    .ok_or_else(|| {
                        classic_game_lobby_child_error(ClassicGameLobbyChild::GameOptionSideEffect(
                            "recursive focus",
                        ))
                    })?
                    .controller
                    .game_option_focus_changed(button)
                    .map_err(|error| {
                        classic_game_lobby_child_error(ClassicGameLobbyChild::GameOptionSideEffect(
                            if error.to_string().is_empty() {
                                "recursive focus"
                            } else {
                                "invalid recursive focus"
                            },
                        ))
                    })?;
                lobby_actions.extend(actions);
            }
        }
        if unhandled {
            lobby_actions.extend(
                self.classic_host_lobby
                    .as_mut()
                    .map(|state| state.controller.game_option_input_unhandled())
                    .unwrap_or_default(),
            );
        }
        Ok(lobby_actions)
    }

    fn process_classic_lobby_actions(
        &mut self,
        actions: Vec<ClassicLobbyAction>,
    ) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        if actions
            .iter()
            .any(|action| matches!(action, ClassicLobbyAction::StartRequested { .. }))
        {
            if let Some(overrides) = self
                .staged_network_host_scenario
                .as_ref()
                .map(|staged| &staged.pending_global_gui_overrides)
            {
                self.assets
                    .require_classic_global_gui_bootstrap_resources(overrides)
                    .map_err(report_classic_parity_boundary)
                    .map_err(classic_parity_engine_error)?;
            }
        }
        let mut pending: VecDeque<ClassicLobbyAction> = actions.into();
        while let Some(action) = pending.pop_front() {
            self.mark_menu_dirty();
            match action {
                ClassicLobbyAction::FocusChanged(control) => {
                    let focused = match control {
                        LobbyControl::GameOption(button) => Some(button),
                        _ => None,
                    };
                    self.scenario_game_options.set_focused_button(focused);
                }
                ClassicLobbyAction::RosterSelectionChanged(_) => {}
                ClassicLobbyAction::SheetRequested(LobbySheet::Players) => {}
                ClassicLobbyAction::SheetRequested(sheet) => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::Sheet(sheet),
                    ));
                }
                ClassicLobbyAction::GameOptions(input) => {
                    pending.extend(self.route_classic_lobby_game_option_input(input)?);
                }
                ClassicLobbyAction::ExitRequested => {
                    // C4GUI::Button raises its click sound before invoking
                    // MainDlg::OnExitBtn. Drain the controller queue while
                    // the lobby still exists so pointer/key activation keeps
                    // that ordering; Escape and Alt+X enqueue no click.
                    self.play_classic_lobby_sounds();
                    self.show_main_menu();
                    self.begin_frontend_music_entry();
                    return Ok(());
                }
                ClassicLobbyAction::StartRequested { .. } => {
                    return Err(classic_game_lobby_child_error(ClassicGameLobbyChild::Start));
                }
                ClassicLobbyAction::AbortCountdownRequested => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::AbortCountdown,
                    ));
                }
                ClassicLobbyAction::ReadyChanged(_) => {
                    return Err(classic_game_lobby_child_error(ClassicGameLobbyChild::Ready));
                }
                ClassicLobbyAction::TabContextRequested { .. } => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::TabContext,
                    ));
                }
                ClassicLobbyAction::RosterContextRequested { row, .. } => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::RosterContext(row),
                    ));
                }
                ClassicLobbyAction::AddPlayerRequested { client_id } => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::AddPlayer(client_id),
                    ));
                }
                ClassicLobbyAction::AddScriptPlayerRequested => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::AddScriptPlayer,
                    ));
                }
                ClassicLobbyAction::TeamSelectionRequested { player_id } => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::TeamSelection(player_id),
                    ));
                }
                ClassicLobbyAction::Chat(request) => {
                    self.process_classic_lobby_chat_request(request)?;
                }
                ClassicLobbyAction::CountdownChanged(_)
                | ClassicLobbyAction::NotifyUserIfInactive
                | ClassicLobbyAction::AppendLog(_) => {
                    return Err(classic_game_lobby_child_error(
                        ClassicGameLobbyChild::NetworkEvent("lobby countdown"),
                    ));
                }
            }
        }
        self.play_classic_lobby_sounds();
        Ok(())
    }

    fn process_classic_lobby_chat_request(
        &mut self,
        request: LobbyChatRequest,
    ) -> Result<(), EngineError> {
        let current_view = || {
            self.classic_host_lobby
                .as_ref()
                .map(|lobby| lobby.controller.chat_edit_view().clone())
                .unwrap_or_default()
        };
        let install_view = |app: &mut Self, view: LobbyChatEditView| {
            if let Some(lobby) = app.classic_host_lobby.as_mut() {
                lobby.controller.set_chat_edit_view(view);
            }
        };
        match request {
            LobbyChatRequest::FocusInput => {
                let mut view = current_view();
                view.caret = view.text.len();
                view.selection = (!view.text.is_empty()).then_some((0, view.caret));
                view.cursor_visible = true;
                install_view(self, view);
            }
            LobbyChatRequest::InsertText(text) => {
                let mut view = current_view();
                lobby_chat_insert_text(&mut view, &text);
                install_view(self, view);
            }
            LobbyChatRequest::RefocusAndInsert(text) => {
                let mut view = current_view();
                view.caret = view.text.len();
                view.selection = (!view.text.is_empty()).then_some((0, view.caret));
                lobby_chat_insert_text(&mut view, &text);
                install_view(self, view);
            }
            LobbyChatRequest::EditKey { key, modifiers } => {
                let mut view = current_view();
                lobby_chat_apply_edit_key(&mut view, key, modifiers);
                install_view(self, view);
            }
            LobbyChatRequest::Clipboard { shortcut } => {
                let mut view = current_view();
                match shortcut {
                    LobbyChatClipboardShortcut::Copy | LobbyChatClipboardShortcut::Cut => {
                        if let Some(range) = lobby_chat_selection(&view) {
                            let selected = view.text[range].to_string();
                            let copied = arboard::Clipboard::new()
                                .and_then(|mut clipboard| clipboard.set_text(selected))
                                .is_ok();
                            if copied && shortcut == LobbyChatClipboardShortcut::Cut {
                                lobby_chat_delete_selection(&mut view);
                            }
                        }
                    }
                    LobbyChatClipboardShortcut::Paste => {
                        if let Ok(text) =
                            arboard::Clipboard::new().and_then(|mut clipboard| clipboard.get_text())
                        {
                            lobby_chat_insert_text(&mut view, &text);
                        }
                    }
                    LobbyChatClipboardShortcut::SelectAll => {
                        view.caret = view.text.len();
                        view.selection = (!view.text.is_empty()).then_some((0, view.caret));
                    }
                }
                view.cursor_visible = true;
                install_view(self, view);
            }
            LobbyChatRequest::ContextCommand(command) => {
                let shortcut = match command {
                    LobbyChatContextCommand::Cut => Some(LobbyChatClipboardShortcut::Cut),
                    LobbyChatContextCommand::Copy => Some(LobbyChatClipboardShortcut::Copy),
                    LobbyChatContextCommand::Paste => Some(LobbyChatClipboardShortcut::Paste),
                    LobbyChatContextCommand::SelectAll => {
                        Some(LobbyChatClipboardShortcut::SelectAll)
                    }
                    LobbyChatContextCommand::Clear => None,
                };
                if let Some(shortcut) = shortcut {
                    return self.process_classic_lobby_chat_request(
                        LobbyChatRequest::Clipboard { shortcut },
                    );
                }
                let mut view = current_view();
                lobby_chat_delete_selection(&mut view);
                install_view(self, view);
            }
            LobbyChatRequest::Submit(text) => {
                self.store_message_input_history(&text);
                if let Some(lobby) = self.classic_host_lobby.as_mut() {
                    lobby.chat_history_index = -1;
                    lobby.controller.set_chat_draft("");
                }
                if self.process_control_message_local_command(&text) {
                    return Ok(());
                }
                if is_team_message_syntax(&text) && self.engine.team_distribution() == 4 {
                    self.append_control_message_log(
                        "Can't send team message: Teams not known.".to_string(),
                        CONTROL_LOG_COLOR,
                        None,
                    );
                    return Ok(());
                }
                let control = parse_lobby_message_control(&text).map_err(|error| {
                    tracing::warn!(%error, "classic lobby chat command is not implemented");
                    classic_game_lobby_child_error(ClassicGameLobbyChild::Chat)
                })?;
                if let Some(control) = control {
                    if let Some(Err(error)) = self
                        .network
                        .as_ref()
                        .map(|network| network.submit_message(control))
                    {
                        tracing::error!(%error, "failed to submit classic lobby message");
                    }
                }
            }
            LobbyChatRequest::History { older } => {
                let Some(lobby) = self.classic_host_lobby.as_mut() else {
                    return Ok(());
                };
                lobby.chat_history_index += if older { 1 } else { -1 };
                let text = usize::try_from(lobby.chat_history_index)
                    .ok()
                    .and_then(|index| self.message_input_history.get(index))
                    .cloned();
                match text {
                    Some(text) => {
                        lobby.controller.set_chat_draft(text.clone());
                        lobby.controller.set_chat_edit_view(LobbyChatEditView {
                            caret: text.len(),
                            selection: (!text.is_empty()).then_some((0, text.len())),
                            text,
                            cursor_visible: true,
                            ..LobbyChatEditView::default()
                        });
                    }
                    None => {
                        lobby.chat_history_index = -1;
                        lobby.controller.set_chat_draft("");
                    }
                }
            }
            LobbyChatRequest::PointerDown(_)
            | LobbyChatRequest::PointerMove(_)
            | LobbyChatRequest::PointerUp(_)
            | LobbyChatRequest::PointerDoubleClick(_)
            | LobbyChatRequest::PointerMiddleDown(_)
            | LobbyChatRequest::TouchCancel
            | LobbyChatRequest::OpenContextMenu { .. } => {
                // The controller already owns focus/capture. Text mutation is
                // handled by keyboard/clipboard actions above; retaining the
                // request is safe until the recursive context menu is wired.
            }
            LobbyChatRequest::OpenExternalDialog => {
                return Err(classic_game_lobby_child_error(ClassicGameLobbyChild::Chat));
            }
        }
        Ok(())
    }

    fn handle_classic_lobby_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<(), EngineError> {
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        if state == ElementState::Pressed {
            let chat_actions = if key == VirtualKeyCode::Apps {
                self.classic_host_lobby
                    .as_ref()
                    .map(|lobby| {
                        let actions = lobby.controller.chat_context_from_key(&layout);
                        if !actions.is_empty() {
                            return actions;
                        }
                        let anchor = lobby
                            .controller
                            .selected_roster_id()
                            .and_then(|selected| {
                                roster.rows.iter().find(|row_layout| {
                                    lobby
                                        .controller
                                        .rows()
                                        .get(row_layout.index)
                                        .is_some_and(|row| &row.id() == selected)
                                })
                            })
                            .map(|row| {
                                GuiPoint::new(
                                    (row.rect.x + row.rect.w / 2) as f32,
                                    (row.rect.y + row.rect.h / 2) as f32,
                                )
                            })
                            .unwrap_or_else(|| {
                                GuiPoint::new(
                                    (layout.roster.x + layout.roster.w / 2) as f32,
                                    (layout.roster.y + layout.roster.h / 2) as f32,
                                )
                            });
                        lobby.controller.request_focused_context(anchor)
                    })
                    .unwrap_or_default()
            } else {
                let shortcut = if self.keyboard_modifiers.ctrl() {
                    match key {
                        VirtualKeyCode::C => Some(LobbyChatClipboardShortcut::Copy),
                        VirtualKeyCode::X => Some(LobbyChatClipboardShortcut::Cut),
                        VirtualKeyCode::V => Some(LobbyChatClipboardShortcut::Paste),
                        VirtualKeyCode::A => Some(LobbyChatClipboardShortcut::SelectAll),
                        _ => None,
                    }
                } else {
                    None
                };
                if let Some(shortcut) = shortcut {
                    self.classic_host_lobby
                        .as_ref()
                        .map(|lobby| lobby.controller.chat_clipboard(shortcut))
                        .unwrap_or_default()
                } else {
                    let edit_key = match key {
                        VirtualKeyCode::Left => Some(LobbyChatEditKey::Left),
                        VirtualKeyCode::Right => Some(LobbyChatEditKey::Right),
                        VirtualKeyCode::Home => Some(LobbyChatEditKey::Home),
                        VirtualKeyCode::End => Some(LobbyChatEditKey::End),
                        VirtualKeyCode::Back => Some(LobbyChatEditKey::Backspace),
                        VirtualKeyCode::Delete => Some(LobbyChatEditKey::Delete),
                        _ => None,
                    };
                    edit_key
                        .and_then(|edit_key| {
                            self.classic_host_lobby.as_ref().map(|lobby| {
                                lobby.controller.chat_edit_key(
                                    edit_key,
                                    LobbyChatKeyModifiers {
                                        shift: self.keyboard_modifiers.shift(),
                                        control: self.keyboard_modifiers.ctrl(),
                                    },
                                )
                            })
                        })
                        .unwrap_or_default()
                }
            };
            if !chat_actions.is_empty() {
                return self.process_classic_lobby_actions(chat_actions);
            }
        }
        let actions = if state == ElementState::Pressed && self.keyboard_modifiers.alt() {
            context_menu_hotkey(key)
                .and_then(|hotkey| {
                    self.classic_host_lobby
                        .as_mut()
                        .map(|lobby| lobby.controller.hotkey(hotkey, Instant::now()))
                })
                .unwrap_or_default()
        } else if let Some(key) = map_key_code(key) {
            match state {
                ElementState::Pressed => self
                    .classic_host_lobby
                    .as_mut()
                    .map(|lobby| {
                        lobby.controller.key_down(
                            key,
                            self.keyboard_modifiers.shift(),
                            &layout,
                            &roster,
                            Instant::now(),
                        )
                    })
                    .unwrap_or_default(),
                ElementState::Released => self
                    .classic_host_lobby
                    .as_mut()
                    .map(|lobby| lobby.controller.key_up(key))
                    .unwrap_or_default(),
            }
        } else {
            Vec::new()
        };
        self.process_classic_lobby_actions(actions)
    }

    fn handle_classic_lobby_pointer_move(&mut self, point: GuiPoint) -> Result<(), EngineError> {
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let actions = self
            .classic_host_lobby
            .as_mut()
            .map(|lobby| {
                lobby.pointer = Some(point);
                lobby.controller.pointer_move(point, &layout, &roster)
            })
            .unwrap_or_default();
        self.process_classic_lobby_actions(actions)
    }

    fn handle_classic_lobby_pointer_button(
        &mut self,
        state: ElementState,
    ) -> Result<(), EngineError> {
        let Some(point) = self
            .classic_host_lobby
            .as_ref()
            .and_then(|lobby| lobby.pointer)
        else {
            return Ok(());
        };
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let actions = match state {
            ElementState::Pressed => self
                .classic_host_lobby
                .as_mut()
                .map(|lobby| lobby.controller.pointer_down(point, &layout, &roster))
                .unwrap_or_default(),
            ElementState::Released => self
                .classic_host_lobby
                .as_mut()
                .map(|lobby| {
                    lobby
                        .controller
                        .pointer_up(point, &layout, &roster, Instant::now())
                })
                .unwrap_or_default(),
        };
        self.process_classic_lobby_actions(actions)
    }

