    fn handle_classic_lobby_wheel(&mut self, delta: i32) -> Result<(), EngineError> {
        let Some(point) = self
            .classic_host_lobby
            .as_ref()
            .and_then(|lobby| lobby.pointer)
        else {
            return Ok(());
        };
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        if self
            .classic_host_lobby
            .as_mut()
            .is_some_and(|lobby| lobby.controller.wheel(point, delta, &layout, &roster))
        {
            self.mark_menu_dirty();
        }
        Ok(())
    }

    fn handle_classic_lobby_touch(
        &mut self,
        phase: TouchPhase,
        point: GuiPoint,
    ) -> Result<(), EngineError> {
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let actions = self
            .classic_host_lobby
            .as_mut()
            .map(|lobby| {
                lobby.pointer = (!matches!(phase, TouchPhase::Cancelled)).then_some(point);
                match phase {
                    TouchPhase::Started => lobby.controller.touch_start(point, &layout, &roster),
                    TouchPhase::Moved => lobby.controller.touch_move(point, &layout, &roster),
                    TouchPhase::Ended => {
                        lobby
                            .controller
                            .touch_end(point, &layout, &roster, Instant::now())
                    }
                    TouchPhase::Cancelled => lobby.controller.touch_cancel(),
                }
            })
            .unwrap_or_default();
        self.process_classic_lobby_actions(actions)
    }

    fn handle_classic_lobby_gamepad_direction(
        &mut self,
        button: ControlButton,
        state: ElementState,
    ) -> Result<(), EngineError> {
        if state == ElementState::Released {
            return Ok(());
        }
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let (horizontal, vertical) = match button {
            ControlButton::Left => (-1, 0),
            ControlButton::Right => (1, 0),
            ControlButton::Up => (0, -1),
            ControlButton::Down => (0, 1),
        };
        let actions = self
            .classic_host_lobby
            .as_mut()
            .map(|lobby| {
                lobby
                    .controller
                    .gamepad_direction(horizontal, vertical, &layout, &roster)
            })
            .unwrap_or_default();
        self.process_classic_lobby_actions(actions)
    }

    fn handle_classic_lobby_gamepad_action(
        &mut self,
        action: GamepadActionType,
        state: ElementState,
    ) -> Result<(), EngineError> {
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let actions = self
            .classic_host_lobby
            .as_mut()
            .map(|lobby| match action {
                GamepadActionType::Select => match state {
                    ElementState::Pressed => {
                        lobby
                            .controller
                            .gamepad_low_down(Instant::now(), &layout, &roster)
                    }
                    ElementState::Released => lobby.controller.gamepad_low_up(),
                },
                GamepadActionType::Cancel | GamepadActionType::MenuToggle => {
                    if state == ElementState::Pressed {
                        lobby.controller.gamepad_high_down()
                    } else {
                        Vec::new()
                    }
                }
            })
            .unwrap_or_default();
        self.process_classic_lobby_actions(actions)
    }

    fn handle_main_menu_activation(&mut self, item: MainMenuItem) -> Result<(), EngineError> {
        match item {
            MainMenuItem::LocalGame => {
                self.open_scenario_browser();
            }
            MainMenuItem::NetworkGame => {
                if self.network_mode.is_some() && self.network_lobby.is_some() {
                    self.open_network_lobby();
                } else {
                    self.open_network_game_dialog();
                }
            }
            MainMenuItem::PlayerSelection => {
                self.open_player_selection_dialog();
            }
            MainMenuItem::Options => {
                self.open_options_menu();
            }
            MainMenuItem::About => {
                self.open_about_dialog();
            }
            MainMenuItem::Quit => {
                self.request_exit();
            }
        }
        Ok(())
    }

    /// C4StartupScenSelDlg::DoBack(true) (cpp:1705-1725): backtrace the
    /// folder stack first; from the root, return to the main screen.
    fn scensel_do_back(&mut self) -> Result<(), EngineError> {
        if self.menu_state.stack.len() <= 1 {
            self.close_scenario_browser();
        } else {
            self.play_ui_sound("DoorClose");
            self.menu_state.leave_folder();
            self.set_scensel_dialog_focus(ScenselDialogFocus::List);
            self.scenario_label = self.menu_state.label_path();
            self.handle_menu_input(|menu| menu.select_default_entry())?;
        }
        Ok(())
    }

    fn close_scenario_browser(&mut self) {
        match self.scenario_selector_mode {
            ScenarioSelectorMode::Local => self.show_main_menu(),
            ScenarioSelectorMode::NetworkHost => {
                self.close_context_menu_silently();
                self.game_option_input_dialog = None;
                self.game_option_input_consumed_keys.clear();
                self.game_option_input_pointer_capture = None;
                self.game_option_consumed_keys.clear();
                self.scenario_game_options.cancel_interaction();
                self.refresh_retained_network_dialog_internet();
                self.startup_view = StartupView::NetworkGame;
                if let Some(dialog) = self.startup_network_dialog.as_mut() {
                    dialog.pointer_left();
                }
                self.status_text.clear();
                self.mark_menu_dirty();
            }
        }
    }

    /// Routes a click through the C++-faithful scenario book layout
    /// (Back / Open buttons + list rows, C4StartupScenSelDlg.cpp:1349-1382).
    fn handle_scensel_parity_click(&mut self, point: GuiPoint) -> Result<(), EngineError> {
        let Some(fonts) = self.assets.clonk_fonts.clone() else {
            return Ok(());
        };
        let layout = lc_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            &fonts,
        );
        let (px, py) = (point.x as i32, point.y as i32);
        let inside =
            |x: i32, y: i32, w: i32, h: i32| px >= x && px < x + w && py >= y && py < y + h;
        let (back, open, list, search, definitions) = (
            layout.back_button,
            layout.open_button,
            layout.list,
            layout.search_edit,
            layout.user_change_checkbox,
        );
        if inside(search.x, search.y, search.w, search.h) {
            self.set_scensel_dialog_focus(ScenselDialogFocus::Search);
        } else if inside(definitions.x, definitions.y, definitions.h, definitions.h) {
            if self.menu_state.definition_checkbox_enabled {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Definitions);
            }
            if self.menu_state.toggle_definition_checkbox() {
                self.play_ui_sound("ArrowHit");
            }
        } else if inside(back.x, back.y, back.w, back.h) {
            self.set_scensel_dialog_focus(ScenselDialogFocus::Back);
            self.scensel_do_back()?;
        } else if inside(open.x, open.y, open.w, open.h) {
            self.set_scensel_dialog_focus(ScenselDialogFocus::Open);
            self.handle_menu_input(|menu| menu.menu().handle_key_down(KeyCode::Enter))?;
            self.handle_menu_input(|menu| menu.menu().handle_key_up(KeyCode::Enter))?;
        } else if inside(list.x + 3, list.y + 3, list.w - 6 - 16, list.h - 6) {
            self.set_scensel_dialog_focus(ScenselDialogFocus::List);
            if let Some(book) = self.assets.book_fonts.clone() {
                let pitch = lc_frontend::startup_scensel::scen_list_item_height(&book.text) + 1;
                let index = ((py - (list.y + 3) + self.menu_state.scenario_list_scroll()) / pitch)
                    .max(0) as usize;
                // Double-click on the selected row opens/starts it
                // (OnSelDblClick -> DoOK, C4StartupScenSelDlg.h:430).
                let now = Instant::now();
                let is_double = self.scensel_last_click.is_some_and(|(last_index, at)| {
                    last_index == index && now.duration_since(at) < Duration::from_millis(500)
                }) && self.menu_state.menu().selected_index() == Some(index);
                self.scensel_last_click = Some((index, now));
                if is_double {
                    self.handle_menu_input(|menu| menu.menu().handle_key_down(KeyCode::Enter))?;
                    self.handle_menu_input(|menu| menu.menu().handle_key_up(KeyCode::Enter))?;
                } else {
                    self.handle_menu_input(|menu| {
                        menu.menu().select_entry_by_index(index).unwrap_or_default()
                    })?;
                }
            }
        }
        Ok(())
    }

    fn open_scenario_browser(&mut self) {
        self.open_scenario_browser_with_mode(ScenarioSelectorMode::Local);
    }

    fn open_network_host_scenario_browser(&mut self) {
        self.open_scenario_browser_with_mode(ScenarioSelectorMode::NetworkHost);
    }

    fn open_scenario_browser_with_mode(&mut self, selector_mode: ScenarioSelectorMode) {
        self.close_context_menu_silently();
        self.game_option_input_dialog = None;
        self.game_option_input_consumed_keys.clear();
        self.game_option_input_pointer_capture = None;
        self.game_option_pointer_capture = false;
        self.game_option_consumed_keys.clear();
        self.scenario_selector_mode = selector_mode;
        let values = load_scenario_game_option_values(self.app_paths.as_ref());
        self.startup_view_flags.fair_crew = values.fair_crew;
        self.startup_view_flags.record = values.record;
        self.recording_enabled = values.record && self.recordings_dir.is_some();
        self.scenario_game_options =
            GameOptionButtons::new(selector_mode.game_option_context(), values);
        self.startup_view = StartupView::ScenarioBrowser;
        self.menu_state.set_pointer_position(None);
        // The C++ dialog reloads from the root folder every time it is
        // shown (OnShown -> pScenLoader->Load(ExePath), cpp:1431-1443).
        self.menu_state.stack.truncate(1);
        self.menu_state.clear_search();
        self.menu_state.scenario_list_scroll = 0;
        self.menu_state.selection_info_scroll = 0;
        self.menu_state.scrollbar_interaction = None;
        self.menu_state.set_dialog_focus(ScenselDialogFocus::List);
        // The C++ book has no Back list entry — Back is a button/K_LEFT
        // (C4StartupScenSelDlg.cpp:1367-1369,1388-1389).
        self.menu_state.set_include_back(false);
        self.menu_state.refresh_menu_entries();
        let width = self.graphics.surface().width() as f32;
        let height = self.graphics.surface().height() as f32;
        self.menu_state.menu().resize(width, height);
        if let Err(err) = self.handle_menu_input(|menu| menu.select_default_entry()) {
            tracing::error!(error = %err, "failed to select default scenario entry");
        }
        self.sync_scenario_game_option_bounds();
        self.sync_scenario_game_option_constraint();
        self.scenario_label = self.menu_state.label_path();
        self.status_text.clear();
    }

    fn open_network_lobby(&mut self) {
        self.close_context_menu_silently();
        self.startup_view = StartupView::NetworkLobby;
        self.menu_state.set_pointer_position(None);
        self.menu_state.set_include_back(true);
        self.menu_state.refresh_menu_entries();
        let width = self.graphics.surface().width() as f32;
        let height = self.graphics.surface().height() as f32;
        self.menu_state.menu().resize(width, height);
        if let Err(err) = self.handle_menu_input(|menu| menu.select_default_entry()) {
            tracing::error!(error = %err, "failed to select default scenario entry");
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.update_layout(width, height);
            self.scenario_label = lobby.scenario_label();
        } else {
            self.scenario_label = "Network lobby unavailable".to_string();
        }
        self.status_text.clear();
        self.acknowledge_initial_lobby_status_if_ready();
    }

    fn open_network_game_dialog(&mut self) {
        self.close_context_menu_silently();
        self.startup_game_references.clear();
        self.pending_network_join = None;
        let (masterserver_signup, _) = load_network_startup_settings(self.app_paths.as_ref());
        let metrics = self
            .assets
            .clonk_fonts
            .as_deref()
            .map(lc_frontend::startup_netdlg::NetDlgFontMetrics::from_fonts)
            .unwrap_or(lc_frontend::startup_netdlg::NetDlgFontMetrics {
                caption_back_extent: 51,
                text_ip_extent: 18,
                text_line_height: 22,
                caption_line_height: 25,
                title_line_height: 34,
            });
        let mut dialog = lc_frontend::startup_netdlg::NetDlgController::new(
            lc_frontend::startup_netdlg::NetDlgConfig {
                masterserver_signup,
                record: self.startup_view_flags.record,
            },
            metrics,
        );
        dialog.resize(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
        );
        let search_config = load_network_search_settings(self.app_paths.as_ref());
        let reference_config = load_reference_query_settings(self.app_paths.as_ref());
        self.startup_game_search = match lc_network::StartupGameSearch::start_with_reference_config(
            search_config,
            reference_config,
        ) {
            Ok(search) => {
                if search.initial_refresh().is_err() {
                    self.status_text = "Unable to start network game search".to_string();
                }
                Some(search)
            }
            Err(error) => {
                self.status_text = format!("Unable to start network game search: {error}");
                None
            }
        };
        self.startup_network_dialog = Some(dialog);
        self.startup_view = StartupView::NetworkGame;
        if self.startup_game_search.is_some() {
            self.status_text = "Querying game infos…".to_string();
        }
    }

