    /// Pump the app until asynchronous boot loading completes and the main menu
    /// is shown. A freshly constructed `GameApp` starts in `AppMode::Loading`
    /// while the boot/material-library thread runs; it transitions to
    /// `AppMode::Menu` only after `update()` polls the boot completion. Panics if
    /// it never settles, so a genuinely stuck boot still fails the test.
    fn wait_for_menu(app: &mut GameApp) {
        // Asset-less unit fixtures intentionally test isolated menu logic.
        // Production stays in Loading and reports the typed loader boundary;
        // only this test helper bypasses startup presentation explicitly.
        if app.app_paths.is_none() && app.loader_error.is_some() {
            app.boot_loading = None;
            app.mode = AppMode::Menu;
            return;
        }
        for _ in 0..480 {
            if matches!(app.mode, AppMode::Menu) {
                return;
            }
            app.update().expect("tick while waiting for boot to finish");
            thread::sleep(Duration::from_millis(2));
        }
        panic!("app did not reach menu mode in time");
    }

    fn app_default_rank_promotion_name(app: &GameApp) -> String {
        let script = r#"#strict 2
func Award()
{
    DoCrewExp(1000);
    return GetObjectInfoCoreVal("RankName", "ObjectInfo");
}
"#;
        let mut engine = Engine::with_seed(0);
        app.apply_material_library_to(&mut engine);
        let mut crew = Definition::from_script("CREW", "Crew", script)
            .expect("default-rank app probe compiles");
        crew.set_crew_member(true);
        engine.register_definition(crew).expect("probe crew registers");
        engine.set_player_starts(vec![lc_engine::scenario::PlayerStart {
            ready_crew: vec![("CREW".to_string(), 1)],
            ..Default::default()
        }]);
        engine
            .join_player(JoinPlayerConfig {
                name: "Rank owner".to_string(),
                player_info_id: 1,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0xff0000,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                control_style: false,
                auto_context_menu: false,
                startup_player_count: 1,
            })
            .expect("rank owner joins");
        let crew_id = engine.player(0).expect("rank owner exists").crew()[0];
        let crew_index = engine.find_object_index(crew_id).expect("probe crew exists");
        match engine
            .call_object_function(crew_index, "Award", Vec::new())
            .expect("default-rank promotion succeeds")
        {
            lc_script::Value::String(name) => name,
            other => panic!("promotion returned {other:?}"),
        }
    }

    fn wait_for_running(app: &mut GameApp) {
        for _ in 0..480 {
            if matches!(app.mode, AppMode::Running) {
                return;
            }
            app.update()
                .expect("tick while waiting for scenario to start");
            thread::sleep(Duration::from_millis(2));
        }
        panic!(
            "scenario did not enter running mode in time (mode={:?}, status={})",
            app.mode, app.status_text
        );
    }

    #[test]
    fn event_loop_second_accumulator_pulses_the_engine_clock() {
        // StdApp's one-second callback is independent from frame scheduling
        // (StdAppUnix.cpp:286-291); C4Game::Sec1Timer consumes TimeGo
        // (C4Game.cpp:1755-1759). Partial elapsed durations accumulate, but
        // headless Engine::tick calls alone never advance Game.Time.
        let mut app = new_menu_app(320, 200);
        let mut seconds = Duration::ZERO;
        app.engine.tick().expect("tick arms clock");
        advance_game_clock_from_elapsed(&mut app, &mut seconds, Duration::from_millis(400))
            .expect("partial second pulse");
        assert_eq!(app.game_time_seconds(), 0);
        advance_game_clock_from_elapsed(&mut app, &mut seconds, Duration::from_millis(600))
            .expect("completed second pulse");
        assert_eq!(app.game_time_seconds(), 1);

        // Two elapsed seconds without another game tick are two timer pulses
        // but still only observe the already-consumed bool latch.
        advance_game_clock_from_elapsed(&mut app, &mut seconds, Duration::from_secs(2))
            .expect("two elapsed timer pulses");
        assert_eq!(app.game_time_seconds(), 1);
    }

    #[test]
    fn second_timer_captures_and_resets_cpp_game_fps() {
        // C4Game::Ticks increments cFPS once per executed simulation frame;
        // Sec1Timer copies it to FPS and resets the accumulator. The host uses
        // that exact FPS for late-client activation lag admission
        // (pristine 9ffa0a5d src/C4Game.cpp:1731-1735,1884-1889;
        // src/C4Network2.cpp:1553-1571).
        let mut app = new_running_sandbox_app();
        for _ in 0..3 {
            app.update().expect("execute simulation frame");
        }

        app.sec1_timer().expect("capture the first second FPS");
        assert_eq!(app.frames_per_second, 3);
        assert_eq!(app.frames_since_second, 0);

        app.update().expect("execute next-second frame");
        app.sec1_timer().expect("capture the next second FPS");
        assert_eq!(app.frames_per_second, 1);
        assert_eq!(app.frames_since_second, 0);
    }

    fn network_catch_up_fixture(
        ready_count: u32,
        control_rate: i32,
    ) -> (GameApp, FrameSchedule, Duration) {
        let mut app = new_running_sandbox_app();
        let (manager, events) = NetworkManager::test_stub();
        let start_tick = 41_u32;
        app.network = Some(manager);
        app.network_control_clock = Some(NetworkControlClock::new(
            i32::try_from(start_tick).unwrap(),
            control_rate,
        ));
        app.engine.initialize_network_control_timing(
            lc_engine::NetworkControlTiming::new(
                i32::try_from(start_tick).unwrap(),
                control_rate,
            )
            .expect("valid catch-up control timing"),
        );
        for offset in 0..ready_count {
            events
                .send(NetworkEvent::ReadyTick {
                    tick: start_tick + offset,
                    controls: Vec::new(),
                })
                .expect("queue ready control tick");
        }
        let schedule = frame_schedule_for_mode(
            app.mode,
            app.engine.game_tick_delay_ms(),
            app.engine.game_tick_delay_revision(),
        );
        let accumulator = schedule.simulation_interval;
        (app, schedule, accumulator)
    }

    #[test]
    fn network_control_catch_up_drains_ten_ready_ticks_in_one_pass() {
        let (mut app, mut schedule, mut accumulator) = network_catch_up_fixture(11, 1);
        let frame_before = app.engine.frame();

        let outcome = advance_simulation_pass(&mut app, &mut schedule, &mut accumulator)
            .expect("catch up ready control backlog");

        assert_eq!(outcome.executed_frames, 8);
        assert_eq!(app.engine.frame(), frame_before + 8);
        assert_eq!(app.network_control_pacing().behind, 3);
        assert!(!app.network_control_pacing().overflow);
        assert_eq!(accumulator, Duration::ZERO);
    }

    #[test]
    fn network_control_catch_up_latches_and_releases_render_skip() {
        let (mut app, mut schedule, mut accumulator) = network_catch_up_fixture(31, 1);

        let catch_up = advance_simulation_pass(&mut app, &mut schedule, &mut accumulator)
            .expect("catch up deep ready-control backlog");
        assert!(catch_up.skipped_render_frames > 0);
        assert!(!catch_up.skip_redraw, "the recovered final frame is rendered");
        assert_eq!(app.network_control_pacing().behind, 3);
        assert!(!app.network_control_pacing().skip_render);

        accumulator += schedule.simulation_interval;
        let paced = advance_simulation_pass(&mut app, &mut schedule, &mut accumulator)
            .expect("resume normal rendering after catch-up");
        assert_eq!(paced.executed_frames, 1);
        assert!(!paced.skip_redraw);
    }

    #[test]
    fn network_control_within_overflow_limit_keeps_normal_pacing() {
        let (mut app, mut schedule, mut accumulator) = network_catch_up_fixture(4, 1);

        let outcome = advance_simulation_pass(&mut app, &mut schedule, &mut accumulator)
            .expect("execute one timer-paced network frame");

        assert_eq!(outcome.executed_frames, 1);
        assert_eq!(app.network_control_pacing().behind, 3);
        assert!(!outcome.skip_redraw);
        assert_eq!(accumulator, Duration::ZERO);
    }

    #[test]
    fn network_control_catch_up_stops_at_a_ready_tick_gap() {
        let mut gate = NetworkTickGate::default();
        gate.queue(7, 7, Vec::new());
        gate.queue(7, 11, Vec::new());

        assert_eq!(gate.contiguous_ready_behind(7), 1);

        gate.queue(7, 8, Vec::new());
        gate.queue(7, 9, Vec::new());
        let mut inspected = 0;
        assert_eq!(
            gate.contiguous_ready_behind_if(7, |_| {
                inspected += 1;
                inspected < 2
            }),
            1,
            "a future control that fails PreExecute ends the ready prefix"
        );
    }

    #[test]
    fn network_control_catch_up_advances_non_control_frames() {
        let (mut app, mut schedule, mut accumulator) = network_catch_up_fixture(11, 2);
        assert_eq!(app.engine.frame() % 2, 0, "fixture starts on control cadence");

        let outcome = advance_simulation_pass(&mut app, &mut schedule, &mut accumulator)
            .expect("catch up across rate-two non-control frames");

        assert_eq!(outcome.executed_frames, 16);
        assert_eq!(app.network_control_pacing().behind, 3);
        assert!(!app.network_control_pacing().overflow);
    }

    #[test]
    fn event_loop_uses_cpp_startup_and_ingame_tick_delays() {
        // C4Application starts and returns to startup at 16 ms, while
        // C4Game::Init switches the running simulation to 28 ms
        // (C4Application.cpp:44,234; C4Game.cpp:63,443).
        let startup = FrameSchedule {
            simulation_interval: STARTUP_FRAME_INTERVAL,
            refresh_interval: STARTUP_FRAME_INTERVAL,
            running_revision: None,
        };
        assert_eq!(frame_schedule_for_mode(AppMode::Menu, 28, 1), startup);
        assert_eq!(frame_schedule_for_mode(AppMode::Loading, 28, 1), startup);
        assert_eq!(
            frame_schedule_for_mode(AppMode::Running, 28, 1),
            FrameSchedule {
                simulation_interval: INGAME_FRAME_INTERVAL,
                refresh_interval: INGAME_FRAME_INTERVAL,
                running_revision: Some(1),
            }
        );

        let mut schedule = startup;
        let mut accumulator = Duration::from_millis(15);
        accumulate_frame_time_for_mode(
            AppMode::Running,
            28,
            1,
            &mut schedule,
            &mut accumulator,
            Duration::from_millis(10),
        );
        assert_eq!(schedule.simulation_interval, INGAME_FRAME_INTERVAL);
        assert_eq!(
            accumulator,
            Duration::ZERO,
            "elapsed time measured under the startup cadence must not leak into the game timer"
        );

        accumulate_frame_time_for_mode(
            AppMode::Running,
            28,
            1,
            &mut schedule,
            &mut accumulator,
            Duration::from_millis(27),
        );
        assert_eq!(accumulator, Duration::from_millis(27));

        assert!(synchronize_frame_schedule(
            AppMode::Running,
            28,
            2,
            &mut schedule,
            &mut accumulator,
        ));
        assert_eq!(accumulator, Duration::ZERO);

        assert!(synchronize_frame_schedule(
            AppMode::Running,
            1_000,
            3,
            &mut schedule,
            &mut accumulator,
        ));
        assert_eq!(schedule.simulation_interval, Duration::from_millis(1_000));
        assert_eq!(schedule.refresh_interval, Duration::from_millis(29));
        accumulate_frame_time_for_mode(
            AppMode::Running,
            1_000,
            3,
            &mut schedule,
            &mut accumulator,
            Duration::from_millis(1_000),
        );
        assert_eq!(accumulator, Duration::from_millis(1_000));

        accumulate_frame_time_for_mode(
            AppMode::Menu,
            1_000,
            3,
            &mut schedule,
            &mut accumulator,
            Duration::from_millis(1),
        );
        assert_eq!(schedule, startup);
        assert_eq!(accumulator, Duration::ZERO);
    }

