    #[test]
    fn network_lobby_renders_classic_base_without_enabling_generic_fallback() {
        // MainDlg is a FullscreenDialog with exact client margins and a
        // ComponentAligner-owned bottom row. A non-host gets no Start button;
        // its ready checkbox occupies the rightmost 110x32 cell
        // (pristine 9ffa0a5d src/C4GuiDialogs.cpp:813-822,858-862;
        // src/C4GameLobby.cpp:141-218).
        let _lock = env_lock().lock();
        reset_cached_app_paths();
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover installed assets");
        let mut app = GameApp::new(
            640,
            480,
            AudioOptions {
                sound_enabled: false,
                music_enabled: false,
                menu_music_enabled: false,
                menu_sound_enabled: false,
                ..AudioOptions::default()
            },
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Client".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise installed app");
        wait_for_menu(&mut app);
        app.startup_view = StartupView::NetworkLobby;
        app.network_lobby = Some(NetworkLobbyState::new(7, "Client".to_string(), false));
        let mut frame = vec![0x5a; 640 * 480 * 4];

        app.render(&mut frame)
            .expect("classic network lobby base renders");

        let layout = app
            .network_lobby
            .as_ref()
            .and_then(|lobby| lobby.layout.as_ref())
            .expect("render computes lobby layout");
        assert_eq!(
            (
                layout.ready_button.origin.x as i32,
                layout.ready_button.origin.y as i32,
                layout.ready_button.size.width as i32,
                layout.ready_button.size.height as i32,
            ),
            (508, 400, 110, 32)
        );
        assert!(layout.start_button.is_none());
        assert!(frame.iter().any(|byte| *byte != 0x5a));

        // The classic renderer remains fail-closed when its required assets
        // are absent; NetworkLobby must not re-enable the old generic pane.
        let mut assetless = new_menu_app(320, 200);
        Arc::get_mut(&mut assetless.assets)
            .expect("frontend assets are app-owned")
            .startup_dialog_images
            .remove("GUIButtonDown.png")
            .expect("classic fixture includes the pressed button sheet");
        assetless.startup_view = StartupView::NetworkLobby;
        assetless.network_lobby = Some(NetworkLobbyState::new(7, "Client".to_string(), false));
        let mut untouched = vec![0x3c; 320 * 200 * 4];
        let error = assetless
            .render(&mut untouched)
            .expect_err("assetless lobby refuses generic fallback");
        assert!(matches!(
            error.downcast_ref::<ClassicParityBoundary>(),
            Some(ClassicParityBoundary::GlobalGuiBootstrapResources { issues })
                if issues.contains(&ClassicGuiBootstrapIssue::missing("GUIButtonDown"))
        ));
        assert!(untouched.iter().all(|byte| *byte == 0x3c));
        reset_cached_app_paths();
    }

    #[test]
    fn menu_music_runs_in_menu_cycle() {
        lc_core::logging::init();
        assert_eq!(GAME_MUSIC_FADE_OUT_MS, 2_000);

        // Music discovery reads process env; hold the env lock so the
        // EnvGuard-based tests cannot redirect paths mid-load.
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app with audio");

        // Menu music is started by `ensure_menu_music()` when asynchronous boot
        // loading completes and the menu is shown; pump boot to that point first.
        wait_for_menu(&mut app);

        // Music decodes on a worker thread now (the FluidSynth render must
        // never block the caller) — poll for playback start.
        let wait_for_music = |app: &GameApp| {
            let started = std::time::Instant::now();
            loop {
                let playing = app
                    .audio
                    .as_ref()
                    .map(|audio| audio.system.music_is_playing())
                    .unwrap_or(false);
                if playing || started.elapsed() > std::time::Duration::from_secs(20) {
                    break playing;
                }
                std::thread::sleep(std::time::Duration::from_millis(50));
            }
        };
        assert!(wait_for_music(&app), "menu music should start on launch");

        app.start_sandbox_scenario(FrontendScenario::fallback())
            .expect("start sandbox scenario");
        assert!(
            wait_for_music(&app),
            "sandbox scenario should have looping music"
        );

        app.return_to_menu();
        assert!(
            app.audio
                .as_ref()
                .expect("test audio")
                .system
                .music_is_playing(),
            "game teardown must leave the current song active while it fades"
        );
        assert!(app.resume_frontend_music_after_fade);

        // Complete the asynchronous fade without making this regression wait
        // two wall-clock seconds. The menu cycle must then request frontend
        // music once instead of replacing the fading game song immediately.
        app.audio
            .as_ref()
            .expect("test audio")
            .system
            .halt_music();
        app.update().expect("poll completed teardown fade");
        assert!(!app.resume_frontend_music_after_fade);
        assert!(
            wait_for_music(&app),
            "menu music should resume after returning to the menu"
        );
    }

