        let (_guard, paths, content) = loader_origin_fixture_paths(root.path());
        let inner = packed_test_group(&[]);
        let outer = packed_test_file_group(&[("INNER.C4F", true, inner.as_slice())]);
        let outer_path = content.join("Outer.c4f");
