    #[test]
    fn pending_preflight_retains_the_exact_network_tick() {
        // C4Control::PreExecute inspects the complete list before execution;
        // a pending packet leaves iControlReady unchanged so the same tick is
        // retried intact (src/C4Control.cpp:73-90;
        // src/C4GameControlNetwork.cpp:687-719).
        let tick = 7;
        let controls = vec![NetworkControl::JoinPlayer(
            lc_engine::JoinPlayerControlData::default(),
        )];
        let mut gate = NetworkTickGate::default();
        gate.queue(tick, tick, controls.clone());

        assert!(gate.take_exact_if_ready(tick, |_| false).is_none());
        assert_eq!(
            gate.take_exact_if_ready(tick, |_| true),
            Some(controls),
            "the retained tick executes once its preflight becomes ready"
        );
    }

    #[test]
    fn direct_lobby_player_info_survives_network_game_initialization() {
        // Network PlayerInfo is applied directly in the lobby and the same
        // registry is reused when the game starts; the later synchronized
        // JoinPlayer resolves its InfoID there (src/C4Network2Players.cpp:245-269;
        // src/C4Game.cpp:2392-2423).
        let mut app = new_menu_app(320, 200);
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let info_id = 41;
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                lc_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: info_id,
                        ..Default::default()
                    }],
                    by_client: 0,
                    ..Default::default()
                },
            )))
            .expect("queue direct lobby PlayerInfo");

        app.process_network_events()
            .expect("apply direct lobby PlayerInfo");
        assert!(app.control_player_infos.get(info_id).is_some());

        app.configure_running_state("Network".to_string(), DEFAULT_GROUND_HEIGHT);

        assert!(
            app.control_player_infos.get(info_id).is_some(),
            "network game initialization must retain lobby PlayerInfo"
        );
    }

    #[test]
    fn client_retains_exact_join_data_until_resource_bootstrap_can_apply_it() {
        // HandleJoinData retains the synchronized parameters and dynamic core;
        // InitNetworkFromReference retrieves and overlays those resources later
        // (src/C4Network2.cpp:281-344,1574-1623).
        let mut app = new_menu_app(320, 200);
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let host_config = lc_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot.parameters.control_rate = 3;
        let join_data = lc_network::JoinDataEnvelope {
            client_id: 3,
            start_control_tick: 23,
            status: host_config.initial_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data.clone()))
            .expect("queue JoinData");

        app.process_network_events().expect("retain JoinData");

        assert_eq!(app.pending_network_join_data, Some(join_data));
        assert_eq!(
            app.network_control_clock,
            Some(NetworkControlClock::new(23, 3))
        );
    }

