    #[test]
    fn approved_self_kick_clears_network_and_ends_local_round() {
        // When approved VT_Kick targets the local client, C++ records the
        // voted-out result, clears the network into local control, and calls
        // DoGameOver immediately so the removed client cannot continue alone
        // (src/C4Control.cpp:1497-1506; src/C4Network2.cpp:746-789).
        let mut app = new_running_sandbox_app();
        let local_client = 7;
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        let (manager, _events) = NetworkManager::test_stub_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.control_clients = ControlClientRegistry::default();
        app.control_clients.register(0, true, false);
        app.control_clients.register(local_client, true, false);

        app.apply_ready_controls(
            23,
            vec![NetworkControl::VoteEnd(lc_engine::VoteControlData {
                vote_type: lc_engine::VOTE_TYPE_KICK,
                approve: true,
                data: local_client,
                by_client: 0,
            })],
        )
        .expect("execute approved self-kick");

        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(app
            .engine
            .player(app.local_owner)
            .expect("local player remains for evaluation")
            .surrendered());
        app.update().expect("finish voted-out round");
        assert!(app.snapshot.game_over);
    }

    #[test]
    fn eligible_client_vote_prompt_defaults_no_and_yes_submits_ballot() {
        // A connected client with a currently joined local player gets one
        // exclusive Yes/No C4VoteDialog for a subject it has not voted on.
        // The dialog uses Ico_Confirm and fDefaultNo=true; closing Yes calls
        // Vote with the local authenticated client ID
        // (src/C4Network2.cpp:2941-2972,2992-3033).
        let mut app = new_running_sandbox_app();
        let local_client = 7;
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        let (manager, event_tx, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.control_clients.replace_snapshot([
            lc_engine::ClientCoreControlData {
                client_id: 0,
                name: lc_engine::LegacyCString::from_bytes(b"Host".to_vec()).expect("host name"),
                ..Default::default()
            },
            lc_engine::ClientCoreControlData {
                client_id: local_client,
                name: lc_engine::LegacyCString::from_bytes(b"Client".to_vec())
                    .expect("client name"),
                ..Default::default()
            },
        ]);
        let subject = LeagueVoteSubject {
            vote_type: lc_engine::VOTE_TYPE_KICK,
            data: local_client,
        };
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::Vote(
                lc_engine::VoteControlData {
                    vote_type: subject.vote_type,
                    approve: true,
                    data: subject.data,
                    by_client: 0,
                },
            )))
            .expect("queue host vote");

        app.process_network_events().expect("open vote prompt");

        assert_eq!(app.message_dialogs.len(), 1);
        let prompt = &app.message_dialogs[0].state;
        assert_eq!(prompt.caption(), "Voting");
        assert_eq!(
            prompt.message(),
            "Host wants to kick client Client. Allow?|Notice: if a player leaves without being defeated, the opposing players will gain less league score in case of a win."
        );
        assert_eq!(
            prompt.buttons(),
            lc_frontend::message_dialog::MessageDialogButtons::YES_NO
        );
        assert_eq!(
            prompt.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::CONFIRM
        );
        assert_eq!(
            prompt.focused_button(),
            Some(lc_frontend::message_dialog::MessageDialogButton::No)
        );

        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Yes)
            .expect("approve vote");

        assert_eq!(
            commands.take_submitted_votes(),
            vec![lc_engine::VoteControlData {
                vote_type: subject.vote_type,
                approve: true,
                data: subject.data,
                by_client: local_client,
            }]
        );
    }

    #[test]
    fn rejected_own_self_kick_opens_default_no_surrender_prompt() {
        // If an own-origin self-kick is rejected, EndVote offers the separate
        // league surrender dialog. It is Yes/No with default No; declining
        // leaves the network round running (src/C4Network2.cpp:2900-2928,
        // 2974-3033).
        let mut app = new_running_sandbox_app();
        let local_client = 7;
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        let (manager, _events) = NetworkManager::test_stub_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.control_clients.register(0, true, false);
        app.control_clients.register(local_client, true, false);
        app.execute_league_vote(lc_engine::VoteControlData {
            vote_type: lc_engine::VOTE_TYPE_KICK,
            approve: true,
            data: local_client,
            by_client: local_client,
        })
        .expect("store own self-kick");

        app.apply_ready_controls(
            23,
            vec![NetworkControl::VoteEnd(lc_engine::VoteControlData {
                vote_type: lc_engine::VOTE_TYPE_KICK,
                approve: false,
                data: local_client,
                by_client: 0,
            })],
        )
        .expect("reject own self-kick");

        assert_eq!(app.message_dialogs.len(), 1);
        let prompt = &app.message_dialogs[0].state;
        assert_eq!(prompt.caption(), "Voting");
        assert_eq!(
            prompt.message(),
            "It was decided that you cannot leave the game. However, you can forfeit the game instead.||Do you want to surrender?"
        );
        assert_eq!(
            prompt.focused_button(),
            Some(lc_frontend::message_dialog::MessageDialogButton::No)
        );

        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::No)
            .expect("decline surrender");

        assert!(app.message_dialogs.is_empty());
        assert!(app.network.is_some());
        assert!(matches!(app.mode, AppMode::Running));
    }

    #[test]
    fn accepting_league_surrender_clears_network_and_aborts_round() {
        // Accepting the fallback surrender records a league forfeit, clears
        // C4Network2 without a normal Part notification, then Game.Abort(true)
        // exits the round (src/C4Network2.cpp:2974-3033,2823-2828).
        let mut app = new_running_sandbox_app();
        let local_client = 7;
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        let (manager, _events) = NetworkManager::test_stub_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.control_clients.register(0, true, false);
        app.control_clients.register(local_client, true, false);
        app.execute_league_vote(lc_engine::VoteControlData {
            vote_type: lc_engine::VOTE_TYPE_KICK,
            approve: true,
            data: local_client,
            by_client: local_client,
        })
        .expect("store own self-kick");
        app.apply_ready_controls(
            23,
            vec![NetworkControl::VoteEnd(lc_engine::VoteControlData {
                vote_type: lc_engine::VOTE_TYPE_KICK,
                approve: false,
                data: local_client,
                by_client: 0,
            })],
        )
        .expect("reject own self-kick");

        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Yes)
            .expect("accept league surrender");

        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(matches!(app.mode, AppMode::Menu));
    }

    #[test]
    fn approved_cancel_vote_end_aborts_network_round() {
        // Approved VT_Cancel marks the round's players voted out and calls
        // Game.Abort(true), leaving the active network round
        // (src/C4Control.cpp:1472-1481).
        let mut app = new_running_sandbox_app();
        let local_client = 7;
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        let (manager, _events) = NetworkManager::test_stub_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));

        app.apply_ready_controls(
            23,
            vec![NetworkControl::VoteEnd(lc_engine::VoteControlData {
                vote_type: lc_engine::VOTE_TYPE_CANCEL,
                approve: true,
                data: 0,
                by_client: 0,
            })],
        )
        .expect("execute approved cancel");

        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(matches!(app.mode, AppMode::Menu));
    }

    #[test]
    fn host_vote_pause_lifecycle_matches_pause_vote_result() {
        // The running host pauses for any active vote. Approved VT_Pause(1)
        // leaves that pause in place; an approved VT_Pause(0) begun while
        // already paused restores GS_Go once no ballots remain
        // (src/C4Network2.cpp:2861-2883,2929-2938;
        // src/C4Game.cpp:1024-1054).
        let mut pause_app = new_running_sandbox_app();
        pause_app
            .engine
            .player_mut(pause_app.local_owner)
            .expect("host player")
            .set_at_client(lc_engine::PlayerAtClient::HOST);
        let (pause_snapshot, pause_reference) = default_exact_host_reference();
        pause_app.control_clients = ControlClientRegistry::default();
        pause_app
            .control_clients
            .replace_snapshot(pause_snapshot.parameters.clients.clients.clone());
        pause_app.host_join_snapshot = Some(pause_snapshot);
        pause_app.advertised_game_reference = Some(pause_reference);
        let (manager, _events, mut commands) = NetworkManager::test_stub_with_commands();
        pause_app.network = Some(manager);
        pause_app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        let pause = lc_engine::VoteControlData {
            vote_type: lc_engine::VOTE_TYPE_PAUSE,
            approve: true,
            data: 1,
            by_client: 0,
        };

        pause_app
            .execute_league_vote(pause)
            .expect("start pause vote");

        let pause_changes = commands.take_status_changes();
        assert_eq!(pause_changes.len(), 1);
        assert_eq!(pause_changes[0].state, lc_network::NETWORK_STATE_PAUSE);
        assert_eq!(
            pause_app
                .advertised_game_reference
                .as_ref()
                .expect("pause refreshes the retained reference")
                .summary()
                .state,
            "Paused"
        );
        pause_app.execute_league_vote_end(pause);
        assert!(commands.take_status_changes().is_empty());
        assert_eq!(
            pause_app
                .advertised_game_reference
                .as_ref()
                .expect("approved pause remains advertised")
                .summary()
                .state,
            "Paused"
        );

        let mut unpause_app = new_running_sandbox_app();
        unpause_app
            .engine
            .player_mut(unpause_app.local_owner)
            .expect("host player")
            .set_at_client(lc_engine::PlayerAtClient::HOST);
        let (unpause_snapshot, unpause_reference) = default_exact_host_reference();
        unpause_app.control_clients = ControlClientRegistry::default();
        unpause_app
            .control_clients
            .replace_snapshot(unpause_snapshot.parameters.clients.clients.clone());
        unpause_app.host_join_snapshot = Some(unpause_snapshot);
        unpause_app.advertised_game_reference = Some(unpause_reference);
        let (manager, _events, mut commands) = NetworkManager::test_stub_with_commands();
        unpause_app.network = Some(manager);
        unpause_app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        unpause_app.network_control_running = false;
        unpause_app.league_votes.paused_for_vote = true;
        unpause_app.host_reference_paused = true;
        unpause_app.publish_running_host_reference();
        let unpause = lc_engine::VoteControlData { data: 0, ..pause };

        unpause_app
            .execute_league_vote(unpause)
            .expect("start unpause vote");
        assert!(commands.take_status_changes().is_empty());
        unpause_app.execute_league_vote_end(unpause);

        let go_changes = commands.take_status_changes();
        assert_eq!(go_changes.len(), 1);
        assert_eq!(go_changes[0].state, lc_network::NETWORK_STATE_GO);
        assert_eq!(
            unpause_app
                .advertised_game_reference
                .as_ref()
                .expect("GO request refreshes the retained reference")
                .summary()
                .state,
            "Running"
        );
    }

    #[test]
    fn league_observer_part_uses_ordinary_network_clear_path() {
        // League changes Part into a self-kick vote only when
        // Game.Players.GetLocalByIndex(0) exists. An observer with no local
        // player follows the ordinary result+Network.Clear path
        // (src/C4MainMenu.cpp:820-831).
        let mut app = new_running_sandbox_app();
        let local_client = 7;
        app.engine
            .remove_player(app.local_owner)
            .expect("remove observer's synthetic local player");
        let (manager, _events, commands) =
            NetworkManager::test_stub_with_commands_for_client_id(local_client);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Observer",
        )));
        app.network_is_league = true;
        app.control_clients = ControlClientRegistry::default();
        app.control_clients
            .register(local_client as i32, false, true);
        let graceful_write = thread::spawn(move || commands.complete_graceful_part());

        app.apply_ingame_menu_action(MenuAction::Part)
            .expect("observer parts from league game");

        assert!(graceful_write.join().expect("graceful writer exits"));
        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(matches!(app.mode, AppMode::Running));
    }

    #[test]
    fn synchronized_surrender_executes_only_for_the_runtime_player_owner() {
        // C4Control executes CID_SurrenderPlayer through
        // C4ControlInternalPlayerScriptBase::Allowed, which requires the
        // runtime C4Player::AtClient to equal iByClient
        // (src/C4Control.cpp:93-109,1546-1578).
        let mut app = new_running_sandbox_app();
        let player = app.local_owner;
        app.engine
            .player_mut(player)
            .expect("local player")
            .set_at_client(lc_engine::PlayerAtClient::new(3));
        assert_eq!(
            app.engine.player(player).expect("local player").at_client(),
            lc_engine::PlayerAtClient::new(3)
        );

        app.apply_ready_controls(
            0,
            vec![NetworkControl::SurrenderPlayer(
                lc_engine::SurrenderPlayerControlData {
                    player,
                    by_client: 7,
                },
            )],
        )
        .expect("execute spoofed surrender control");
        assert!(!app
            .engine
            .player(player)
            .expect("local player")
            .surrendered());

        app.apply_ready_controls(
            1,
            vec![NetworkControl::SurrenderPlayer(
                lc_engine::SurrenderPlayerControlData {
                    player,
                    by_client: 3,
                },
            )],
        )
        .expect("execute owner surrender control");
        assert!(app
            .engine
            .player(player)
            .expect("local player")
            .surrendered());
    }

    #[test]
    fn next_mission_action_launches_the_catalog_target() {
        // C4GameOverDlg's Next button passes Game.NextMission through
        // C4Application::SetNextMission/QuitGame and starts that scenario
        // (C4GameOverDlg.cpp:335-382; C4Application.cpp:373-399).
        let fixture = tempdir().expect("next-mission fixture");
        let user_data = tempdir().expect("isolated user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        configure_test_startup_participant(&paths, user_data.path());
        let mut app = new_menu_app_with_paths(320, 200, &paths);
        app.start_sandbox_scenario(FrontendScenario::fallback())
            .expect("start sandbox scenario");
        wait_for_running(&mut app);
        let target_path = fixture.path().join("Tutorial02.c4s");
        let carried_definition = fixture.path().join("Carry.c4d");
        fs::create_dir_all(&target_path).expect("target scenario");
        fs::create_dir_all(&carried_definition).expect("carried definition");
        fs::write(
            target_path.join("Scenario.txt"),
            "[Head]\nTitle=The First Hut\n",
        )
        .expect("target Scenario.txt");
        fs::write(
            carried_definition.join("DefCore.txt"),
            "[DefCore]\nid=CARY\nName=Carry\nCategory=1\n",
        )
        .expect("carried DefCore.txt");
        fs::write(carried_definition.join("Script.c"), "// carried\n").expect("carried Script.c");
        write_test_definition_graphics(&carried_definition);
        let mut target = FrontendScenario::fallback();
        target.identifier = "Tutorial.c4f/Tutorial02.c4s".to_string();
        target.title = "The First Hut".to_string();
        target.path = Some(target_path);
        app.scenario_catalog
            .insert(target.identifier.clone(), target.clone());
        app.active_definition_load = Some(ScenarioDefinitionLoad::Fixed {
            modules: vec![carried_definition.to_string_lossy().into_owned()],
            definition_root: None,
        });

        let mut state = app.engine.capture_state();
        state.next_mission = lc_engine::NextMissionState {
            path: "Tutorial.c4f\\Tutorial02.c4s".to_string(),
            text: "Next tutorial".to_string(),
            description: "Continue learning".to_string(),
        };
        app.engine.restore_state(&state).expect("state restores");

        app.handle_game_over_action(GameOverAction::NextMission)
            .expect("next mission starts");
        wait_for_running(&mut app);

        assert_eq!(
            app.active_scenario
                .as_ref()
                .map(|scenario| scenario.identifier.as_str()),
            Some("Tutorial.c4f/Tutorial02.c4s")
        );
        assert!(matches!(
            app.active_definition_load.as_ref(),
            Some(ScenarioDefinitionLoad::Fixed {
                modules,
                definition_root: None,
            }) if modules == &[carried_definition.to_string_lossy().as_ref()]
        ));
        assert!(app.game_over_dialog.is_none());
    }

    #[test]
    fn evaluation_dialog_joins_frozen_results_by_player_info_id() {
        // C4GameOverDlg consumes C4RoundResults goals/player records, and
        // C4PlayerInfoListBox joins each record through C4PlayerInfo::GetID,
        // never C4Player::Number (C4GameOverDlg.cpp:145-220;
        // C4PlayerInfoListBox.cpp:132-143,344-425,1529-1592).
        let mut snapshot = make_snapshot(Vec::new(), Vec::new());
        snapshot.players = vec![
            PlayerState {
                id: 99,
                player_info_id: 41,
                name: "Player".into(),
                status: PlayerStatus::Eliminated,
                won: true,
                color: Some(RgbColor::new(0xe8, 0, 0)),
                ..PlayerState::default()
            },
            PlayerState {
                id: 41,
                player_info_id: 7,
                name: "Decoy".into(),
                status: PlayerStatus::Active,
                won: false,
                ..PlayerState::default()
            },
        ];
        snapshot.round_results = lc_engine::RoundResultsState {
            goals: vec!["SCRG".into()],
            fulfilled_goals: vec!["SCRG".into()],
            players: vec![
                lc_engine::RoundResultsPlayerState {
                    player_info_id: 41,
                    total_playing_time: 3_661,
                    score_old: 10,
                    score_new: Some(110),
                    league_progress_data: None,
                    league_performance: 0,
                    custom_evaluation_strings: String::new(),
                    ..lc_engine::RoundResultsPlayerState::default()
                },
                lc_engine::RoundResultsPlayerState {
                    player_info_id: 99,
                    total_playing_time: 9,
                    score_old: 900,
                    score_new: Some(901),
                    league_progress_data: None,
                    league_performance: 0,
                    custom_evaluation_strings: "wrong runtime-number join".into(),
                    ..lc_engine::RoundResultsPlayerState::default()
                },
            ],
            ..lc_engine::RoundResultsState::default()
        };
        let next_mission = lc_engine::NextMissionState {
            path: "Tutorial.c4f\\Tutorial02.c4s".into(),
            text: "Next tutorial".into(),
            description: "Continue learning".into(),
        };
        let picture = ImageData::new(1, 1, vec![12, 34, 56, 255]);

        let dialog = build_game_over_dialog(
            &snapshot,
            99,
            1024,
            "decoy title".into(),
            &next_mission,
            |definition_id| (definition_id == "SCRG").then(|| picture.clone()),
        );

        assert_eq!(
            dialog.actions(),
            vec![
                GameOverAction::End,
                GameOverAction::Continue,
                GameOverAction::NextMission,
            ],
            "Tutorial02 is exposed through the classic next-mission button"
        );
        assert_eq!(dialog.evaluation().goals().len(), 1);
        let goal = &dialog.evaluation().goals()[0];
        assert_eq!(goal.definition_id, "SCRG");
        assert!(goal.fulfilled);
        assert_eq!(
            goal.picture.as_ref().map(|image| image.pixels().to_vec()),
            Some(vec![12, 34, 56, 255])
        );
        let player = dialog
            .evaluation()
            .player_by_info_id(41)
            .expect("result joins the profile ID");
        assert_eq!(player.name, "Player");
        assert!(player.won, "won comes from frozen player info, not Active");
        assert_eq!(player.color_dw, 0x00e8_0000);
        assert_eq!(player.total_playing_time, 3_661);
        assert_eq!((player.score_old, player.score_new), (10, Some(110)));
        assert_eq!(
            dialog.evaluation().players().count(),
            1,
            "a result keyed like the runtime number must not attach to the player"
        );

        snapshot.round_results.hide_settlement_score = true;
        let hidden = build_game_over_dialog(
            &snapshot,
            99,
            1024,
            "decoy title".into(),
            &next_mission,
            |_| None,
        );
        let player = hidden
            .evaluation()
            .player_by_info_id(41)
            .expect("hidden result still joins the profile");
        assert_eq!(
            (player.score_old, player.score_new),
            (-1, None),
            "HideSettlementScoreInEvaluation suppresses the score line"
        );
    }

    #[test]
    fn quick_save_round_trips_state() {
        lc_core::logging::init();

        reset_cached_app_paths();
        {
            let _guard = EnvGuard::set(&[]);
            reset_cached_app_paths();

            let mut app = GameApp::new(
                320,
                200,
                AudioOptions::default(),
                None,
                RuntimeConfig {
                    player_owner: 1,
                    player_name: "Player".to_string(),
                    network: None,
                    record_enabled: false,
                },
            )
            .expect("initialise app");
            install_classic_test_assets(&mut app);
            app.start_sandbox_scenario(FrontendScenario::fallback())
                .expect("start sandbox scenario");

            for _ in 0..5 {
                app.update().expect("tick before save");
            }
            assert_eq!(
                app.snapshot.game_time, 0,
                "headless frame updates do not synthesize real-time pulses"
            );
            assert!(
                app.sec1_timer().expect("explicit saved-game clock pulse"),
                "explicit pulse consumes the tick latch"
            );
            let saved_frame = app.snapshot.frame;
            let saved_game_time = app.snapshot.game_time;

            app.quick_save().expect("quick save succeeds");
            assert!(
                app.last_save_path
                    .as_ref()
                    .map(|path| path.ends_with(QUICK_SAVE_FILE))
                    .unwrap_or(false),
                "quick save should note the save path"
            );
            let thumbnail_path = resolve_save_directory().join("quicksave.png");
            assert!(
                thumbnail_path.exists(),
                "expected quick save thumbnail to be written"
            );

            for _ in 0..3 {
                app.update().expect("advance after save");
            }
            assert!(
                app.sec1_timer().expect("later saved-game clock pulse"),
                "later pulse advances Game.Time"
            );
            assert!(
                app.snapshot.frame > saved_frame,
                "frame should advance after save"
            );
            assert!(app.snapshot.game_time > saved_game_time);

            app.quick_load().expect("quick load succeeds");
            assert_eq!(
                app.snapshot.frame, saved_frame,
                "quick load should restore saved frame"
            );
            assert_eq!(
                app.snapshot.game_time, saved_game_time,
                "quick load should restore Game.Time"
            );
            assert_eq!(app.game_time_seconds(), saved_game_time.max(0) as u64);
            assert!(
                matches!(app.mode, AppMode::Running),
                "quick load should keep the game running"
            );

            cleanup_quicksave_file();
        }
        reset_cached_app_paths();
    }

    #[test]
    fn quick_save_persists_across_sessions() {
        lc_core::logging::init();

        reset_cached_app_paths();

        let fixture = tempdir().unwrap();
        let user_dir = fixture.path().join("user-data");
        fs::create_dir_all(&user_dir).unwrap();
        let scenario_dir = user_dir.join("Scenarios").join("Alpha.c4s");
        let scripts_dir = scenario_dir.join("scripts");
        fs::create_dir_all(&scripts_dir).unwrap();
        fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Alpha Mission\n",
        )
        .unwrap();
        fs::write(
            scenario_dir.join("Scenario.json"),
            r#"
            {
                "name": "Alpha Mission",
                "ground_height": 72,
                "landscape": { "kind": "flat", "width": 160, "height": 80 },
                "definitions": [
                    { "id": "Mover", "name": "Mover", "script": "scripts/mover.aul" }
                ],
                "initial_objects": [
                    {
                        "definition": "Mover",
                        "position": [40, 48],
                        "owner": 1,
                        "crew_member": true,
                        "alive": true
                    }
                ]
            }
            "#,
        )
        .unwrap();
        fs::write(scripts_dir.join("mover.aul"), walker_script()).unwrap();

        let quicksave_path = user_dir.join(SAVE_DIR_NAME).join(QUICK_SAVE_FILE);

        {
            let (_guard, paths) = exact_loader_test_paths(&user_dir, None);

            reset_cached_app_paths();

            let saved_frame = {
                let mut app = GameApp::new(
                    320,
                    200,
                    AudioOptions::default(),
                    Some(&paths),
                    RuntimeConfig {
                        player_owner: 1,
                        player_name: "Player".to_string(),
                        network: None,
                        record_enabled: false,
                    },
                )
                .expect("initialise app");

                let scenario = app
                    .scenario_catalog
                    .get("Alpha.c4s")
                    .cloned()
                    .expect("scenario discovered");
                app.start_scenario(scenario).expect("start disk scenario");
                wait_for_running(&mut app);

                for _ in 0..5 {
                    app.update().expect("advance simulation before save");
                }
                let frame_before_save = app.snapshot.frame;

                app.quick_save().expect("quick save succeeds");
                assert!(
                    quicksave_path.exists(),
                    "expected quick save file to be written"
                );
                assert!(
                    quicksave_path.with_extension("png").exists(),
                    "expected quick save thumbnail to be written"
                );

                frame_before_save
            };

            {
                let mut app = GameApp::new(
                    320,
                    200,
                    AudioOptions::default(),
                    Some(&paths),
                    RuntimeConfig {
                        player_owner: 1,
                        player_name: "Player".to_string(),
                        network: None,
                        record_enabled: false,
                    },
                )
                .expect("initialise app after restart");

                // Boot loading is asynchronous; let it settle to the menu before
                // asserting the fresh session is at the menu (not mid-game).
                wait_for_menu(&mut app);

                assert!(
                    app.last_save_path
                        .as_ref()
                        .map(|path| path.ends_with(QUICK_SAVE_FILE))
                        .unwrap_or(false),
                    "expected quick save path to be remembered"
                );
                assert!(
                    matches!(app.mode, AppMode::Menu),
                    "new session should start in menu"
                );

                app.quick_load().expect("quick load succeeds");

                assert!(
                    matches!(app.mode, AppMode::Running),
                    "quick load should enter running mode"
                );
                assert_eq!(
                    app.snapshot.frame, saved_frame,
                    "quick load should restore the saved frame"
                );
                assert!(
                    app.active_scenario
                        .as_ref()
                        .and_then(|scenario| scenario.path.as_ref())
                        .map(|path| path.ends_with("Alpha.c4s"))
                        .unwrap_or(false),
                    "loaded scenario should reference disk path"
                );
            }

            reset_cached_app_paths();
        }
        reset_cached_app_paths();
    }

